import{o as e}from"./questionShuffle-56eeoPlz.js";var t=[(t,n,r,i=`medium`)=>e({q:`下列哪一組漢字之造字原理「完全屬於指事字」？`,c:`「本」、「末」、「刃」、「寸」`,d:[`「日」、「月」、「山」、「水」`,`「休」、「信」、「武」、「森」`,`「江」、「河」、「松」、「柏」`],h:`指事字多包含抽象指示符號。`,e:`「本、末、刃、寸」皆是在象形基礎上加指示符號標明抽象部位，全為指事字。`},r),(t,n,r,i=`medium`)=>e({q:`「休」與「武」在六書造字法中，皆屬於下列何者？`,c:`會意字`,d:[`象形字`,`形聲字`,`轉注字`],h:`人倚木為休，止戈為武。`,e:`「休」（人依木休息）與「武」（止戈為武）均為合併兩個以上字意產生新意義之會意字。`},r),(t,n,r,i=`medium`)=>e({q:`下列漢字中，造字方法屬於「純粹象形」且無形聲成分的是哪一組？`,c:`「魚」、「鳥」、「鹿」、「龜」`,d:[`「問」、「聞」、「悶」、「闊」`,`「上」、「下」、「一」、「二」`,`「祭」、「劣」、「森」、「淼」`],h:`象形是畫成其物，隨體詰詘。`,e:`「魚、鳥、鹿、龜」皆是描摹動物具體外形之獨體象形字。`},r),(t,n,r,i=`medium`)=>e({q:`漢字中數量最多（佔 80% 以上）的造字法則為下列何者？`,c:`形聲字`,d:[`會意字`,`象形字`,`指事字`],h:`一邊表示意義類別，一邊表示讀音。`,e:`形聲字由意符與聲符結合，極具造字彈性，佔漢字總數八成以上。`},r),(t,n,r,i=`medium`)=>e({q:`「江」與「河」的造字原理相同，下列關於其結構的分析何者正確？`,c:`形符為「水」，聲符分別為「工」與「可」`,d:[`形符分別為「工」與「可」，聲符為「水」`,`兩者皆為會意字，表示水流匯聚`,`兩者皆為獨體指事字`],h:`左形右聲結構。`,e:`「江、河」左邊的三點水（水部）為意符，右側的「工、可」為表音之聲符。`},r),(t,n,r,i=`medium`)=>e({q:`下列「門」字旁的漢字中，何者之「門」為「聲符」而非「形符」？`,c:`「悶」`,d:[`「閉」`,`「開」`,`「閨」`],h:`注意其部首在心部還是門部。`,e:`「悶」從心、門聲，字義與心情憂愁有關，故門為聲符。`},r),(t,n,r,i=`medium`)=>e({q:`許慎《說文解字》中所謂「視而可識，察而見意」所指的造字法則為何？`,c:`指事`,d:[`象形`,`會意`,`形聲`],h:`看一眼能認出大體，仔細觀察能看出標示之意象。`,e:`許慎定義：「指事者，視而可識，察而見意，上下是也。」`},r),(t,n,r,i=`medium`)=>e({q:`下列哪一組漢字的造字法則「完全屬於會意字」？`,c:`「伐」、「劣」、「苗」、「明」`,d:[`「牟」、「刃」、「甘」、「寸」`,`「湖」、「海」、「江」、「洋」`,`「羊」、「牛」、「馬」、「犬」`],h:`合兩字之意以成新義。`,e:`伐（人戈相殘）、劣（少力）、苗（田間長草）、明（日月生輝）皆為會意字。`},r),(t,n,r,i=`medium`)=>e({q:`「上」與「下」二字在甲骨文中以弧線標示位置，其造字法屬於：`,c:`指事字`,d:[`象形字`,`會意字`,`假借字`],h:`以抽象符號指稱方位。`,e:`「上、下」用基準線加符號標示抽象方位概念，屬指事字。`},r),(t,n,r,i=`medium`)=>e({q:`下列關於「六書」順序與歸類的說明，何者最為正確？`,c:`象形、指事、會意、形聲為造字法；轉注、假借為用字法`,d:[`六書皆為古代聖賢先定法則後造文字`,`轉注與假借創造了大量的新字形`,`形聲與會意屬於獨體字，象形與指事屬於合體字`],h:`四體二用說。`,e:`清代戴震提出「四體二用」：前四者為造字之法，後二者為用字之法。`},r),(t,n,r,i=`medium`)=>e({q:`「牟」字本義為牛鳴，其中之撇筆象氣出於口，此字造字法則為：`,c:`指事字`,d:[`象形字`,`形聲字`,`會意字`],h:`牛口吐氣的抽象指事符號。`,e:`「牟」在牛角上加一筆象徵氣息冒出，代表牛叫聲，是指事字。`},r),(t,n,r,i=`medium`)=>e({q:`「採」字從手、從采，其造字法則屬於下列何者？`,c:`形聲字`,d:[`象形字`,`指事字`,`轉注字`],h:`從手表示動作，采表音。`,e:`「採」從手、采聲，以手取物，屬形聲字。`},r),(t,n,r,i=`medium`)=>e({q:`下列各字中，何者為「左聲右形」結構的形聲字？`,c:`「期」`,d:[`「估」`,`「銅」`,`「管」`],h:`注意哪邊是表示類別的偏旁。`,e:`「期」左邊的「其」為聲符，右邊的「月」為形符，屬左聲右形。`},r),(t,n,r,i=`medium`)=>e({q:`「森」與「淼」皆由三個相同字形疊合而成，其造字法則為：`,c:`同字疊合之會意字`,d:[`形聲字`,`象形字`,`指事字`],h:`木多為森，水廣為淼。`,e:`三木為森、三水為淼，皆透過多個實體字形疊加表意，屬會意字。`},r),(t,n,r,i=`medium`)=>e({q:`下列哪一個字在許慎《說文解字》中的解釋屬於「獨體為象形」？`,c:`「鼎」`,d:[`「銅」`,`「信」`,`「末」`],h:`描畫器物之形狀。`,e:`「鼎」描摹青銅鼎三足兩耳之具體器形，為獨體象形字。`},r),(t,n,r,i=`medium`)=>e({q:`「寸」字從又（手），一標示手腕動脈處，此字的造字法則為：`,c:`指事字`,d:[`象形字`,`會意字`,`形聲字`],h:`在手的特定部位點上記號。`,e:`「寸」以手為基礎，在一寸處加一橫指明動脈跳動處，屬指事字。`},r),(t,n,r,i=`medium`)=>e({q:`下列何組漢字皆屬於「內形外聲」的形聲字結構？`,c:`「聞」、「悶」`,d:[`「園」、「圍」`,`「街」、「衝」`,`「闊」、「閥」`],h:`意符在內，聲符包在外面。`,e:`「聞」從耳門聲，「悶」從心門聲，形在內而聲在外。`},r),(t,n,r,i=`medium`)=>e({q:`漢字六書中，「令」借為縣令，「長」借為官長，此種用字現象屬於：`,c:`假借`,d:[`轉注`,`形聲`,`會意`],h:`本無其字，依聲託事。`,e:`六書中的「假借」是本無其字或借用音同義近之字來表示新概念。`},r),(t,n,r,i=`medium`)=>e({q:`「考」與「老」在六書分類中，許慎將其列為哪一類的經典代表？`,c:`轉注`,d:[`會意`,`指事`,`象形`],h:`建類一首，同意相受。`,e:`《說文解字》：「轉注者，建類一首，同意相受，考老是也。」`},r),(t,n,r,i=`medium`)=>e({q:`「解」字由「刀」、「角」、「牛」三字構成，意為以刀剖牛角，其造字法為：`,c:`會意字`,d:[`象形字`,`指事字`,`形聲字`],h:`三個字共同組合表達剖分之動作。`,e:`「解」字以刀剖判牛角，透過三部分組合會合其意，屬會意字。`},r),(t,n,r,i=`medium`)=>e({q:`「齒」字的上方為「止」聲，下方描畫牙齒之形，此字之造字法則為：`,c:`形聲字`,d:[`指事字`,`假借字`,`轉注字`],h:`止為聲符，齒為形符。`,e:`「齒」字上從止聲，下象牙齒排列之形，屬形聲字。`},r),(t,n,r,i=`medium`)=>e({q:`下列何者為「上形下聲」結構的形聲字？`,c:`「霧」`,d:[`「架」`,`「想」`,`「忠」`],h:`形符在上方，聲符在下方。`,e:`「霧」上方「雨」表自然氣象（形符），下方「務」表讀音（聲符）。`},r),(t,n,r,i=`medium`)=>e({q:`下列各字何者不屬於「象形字」？`,c:`「甘」`,d:[`「日」`,`「月」`,`「舟」`],h:`甘是在口中加一橫表示甜味。`,e:`「甘」是在口中加一橫指示甘甜滋味之處，屬於指事字。`},r),(t,n,r,i=`medium`)=>e({q:`「初」字從衣從刀，意為裁製衣服之始，其造字法為：`,c:`會意字`,d:[`象形字`,`形聲字`,`指事字`],h:`用刀裁布是做衣服的開端。`,e:`「初」以刀剖布製衣，組合「刀」與「衣」表開始之意，為會意字。`},r),(t,n,r,i=`medium`)=>e({q:`「刃」字在「刀」的刃口上加一點，這點符號的作用是：`,c:`指事符號，標示刀口鋒利之處`,d:[`形符，表示金屬材質`,`聲符，表示讀音`,`裝飾筆畫，無特定意義`],h:`抽象指示標記。`,e:`「刃」之點劃乃指事符號，標記出刀具最鋒利之切割邊緣。`},r),(t,n,r,i=`medium`)=>e({q:`下列漢字哪一個「非」形聲字？`,c:`「休」`,d:[`「花」`,`「草」`,`「清」`],h:`休是人靠在樹旁休息。`,e:`「休」是人倚木旁，屬會意字；其餘三者皆由形符與聲符組合而成。`},r),(t,n,r,i=`medium`)=>e({q:`「鳴」字從口從鳥，表示鳥類發聲，其造字原理為：`,c:`會意字`,d:[`形聲字`,`象形字`,`指事字`],h:`鳥張口發出叫聲。`,e:`「鳴」合「口」與「鳥」以會鳥鳴之意，為經典會意字。`},r),(t,n,r,i=`medium`)=>e({q:`「網」在古代寫作「罔」，描繪漁網之交織形狀，其原初造字法則為：`,c:`象形字`,d:[`形聲字`,`指事字`,`會意字`],h:`描摹編織網線的外觀。`,e:`「罔/網」原本直接描繪繩索編織之交錯羅網，屬象形字。`},r),(t,n,r,i=`medium`)=>e({q:`「自」在甲骨文中為鼻子的象形，後假借為「自己」，此現象說明了：`,c:`字義引申與同音借用豐富了文字系統`,d:[`六書造字法則在古代完全無序`,`古人無法分辨自己與鼻子之差異`,`象形字無法轉化為代名詞`],h:`文字發展由具體向抽象引申借用。`,e:`「自」本象鼻形，後假借為第一人稱自己，為漢字演進之常見假借範例。`},r),(t,n,r,i=`medium`)=>e({q:`下列關於「象形」與「指事」之主要差異，敘述何者最精確？`,c:`象形為描摹具體實物之全體外觀；指事則表示抽象概念或在象形上加提示符號`,d:[`象形都是合體字，指事都是獨體字`,`象形字有讀音，指事字沒有固定讀音`,`象形只能造名詞，指事只能造動詞`],h:`獨體為象形，加符或抽象符號為指事。`,e:`清代王筠《文字蒙求》指明：描繪實體為象形，標明虛象為指事。`},r),(t,n,r,i=`medium`)=>e({q:`下列各組「冠」字之讀音，何者「前後相同」？`,c:`「冠」軍寶座 ／ 奪「冠」熱門`,d:[`怒髮衝「冠」 ／ 沐猴而「冠」`,`「冠」冕堂皇 ／ 勇「冠」三軍`,`名「冠」群倫 ／ 衣「冠」楚楚`],h:`名詞讀ㄍㄨㄢ（帽子），動詞讀ㄍㄨㄢˋ（位居第一、戴帽）。`,e:`「冠軍」與「奪冠」皆作動詞取得第一解，讀ㄍㄨㄢˋ。`},r),(t,n,r,i=`medium`)=>e({q:`下列各句中的「質」字，何者讀音為「ㄓˋ」且當作「抵押品」解？`,c:`乃令太子為「質」於秦`,d:[`天生麗「質」難自棄`,`這件衣服的「質」感很好`,`他生性「質」樸不喜浮誇`],h:`人質、抵押品讀ㄓˋ。`,e:`古人送王子入敵國為抵押人選稱為「質子」，讀ㄓˋ。`},r),(t,n,r,i=`medium`)=>e({q:`「哽咽」與「咽喉」中的「咽」字讀音依序為何？`,c:`ㄧㄝˋ ／ ㄧㄢ`,d:[`ㄧㄢ ／ ㄧㄝˋ`,`ㄧㄢˋ ／ ㄧㄢ`,`ㄧㄝˋ ／ ㄧㄢˋ`],h:`聲音阻塞讀ㄧㄝˋ，呼吸道喉嚨讀ㄧㄢ，吞嚥讀ㄧㄢˋ。`,e:`哽咽讀ㄧㄝˋ，咽喉讀ㄧㄢ，細嚼慢嚥讀ㄧㄢˋ。`},r),(t,n,r,i=`medium`)=>e({q:`下列詞語中的「扁」字，何者讀音為「ㄆㄧㄢ」？`,c:`「扁」舟一葉`,d:[`「扁」擔挑水`,`踩「扁」鋁罐`,`「扁」平足症`],h:`扁舟讀ㄆㄧㄢ，小船的意思。`,e:`「扁舟」意為孤獨輕便的小船，讀ㄆㄧㄢ ㄓㄡ。`},r),(t,n,r,i=`medium`)=>e({q:`下列文句中的「泊」字，何者讀音與其他三者「不同」？`,c:`倒臥血「泊」之中`,d:[`淡「泊」名利`,`漂「泊」天涯`,`停「泊」碼頭`],h:`湖澤積水處讀ㄆㄛ；停船寄宿與恬靜寡欲皆讀ㄅㄛˊ。`,e:`「血泊」與「湖泊」讀ㄆㄛ；「淡泊」、「漂泊」、「停泊」依教育部辭典皆讀ㄅㄛˊ。`},r),(t,n,r,i=`medium`)=>e({q:`下列詞語中的「處」字，何者讀為「ㄔㄨˇ」且作動詞使用？`,c:`設身「處」地為人著想`,d:[`辦事「處」公文`,`這篇文章有多「處」筆誤`,`長「處」與短處`],h:`動詞居處、處理讀ㄔㄨˇ；名詞地方、機構讀ㄔㄨˋ。`,e:`「設身處地」之處為動詞，指將自己置身於該境地，讀ㄔㄨˇ。`},r),(t,n,r,i=`medium`)=>e({q:`「入場券」與「穩操勝券」中的「券」字標準讀音為：`,c:`ㄑㄩㄢˋ`,d:[`ㄐㄩㄢˋ`,`ㄑㄩㄢ`,`ㄐㄩㄢ`],h:`不可誤讀為卷（ㄐㄩㄢˋ）。`,e:`「券」音ㄑㄩㄢˋ，票據或憑證；「卷」音ㄐㄩㄢˋ，試卷或書卷。`},r),(t,n,r,i=`medium`)=>e({q:`下列各詞語中的「差」字，何者讀音為「ㄘ」？`,c:`參「差」不齊`,d:[`出「差」洽公`,`「差」強人意`,`「差」遣使者`],h:`參差音ㄘㄣ ㄘ，長短不齊貌。`,e:`參差不齊讀ㄘㄣ ㄘ，差強人意讀ㄔㄚ，出差讀ㄔㄞ。`},r),(t,n,r,i=`medium`)=>e({q:`「三年五載」與「載歌載舞」中的「載」字讀音依序為何？`,c:`ㄗㄞˇ ／ ㄗㄞˋ`,d:[`ㄗㄞˋ ／ ㄗㄞˇ`,`ㄗㄞˇ ／ ㄗㄞˇ`,`ㄗㄞˋ ／ ㄗㄞˋ`],h:`年歲、記錄讀ㄗㄞˇ；承載、充滿、一邊...一邊讀ㄗㄞˋ。`,e:`年歲稱「載」讀ㄗㄞˇ；載歌載舞為同時進行，讀ㄗㄞˋ。`},r),(t,n,r,i=`medium`)=>e({q:`下列詞語中的「傳」字，何者讀音為「ㄓㄨㄢˋ」？`,c:`《水滸「傳」》`,d:[`「傳」承文化`,`「傳」遞消息`,`謠言流「傳」`],h:`書籍傳記讀ㄓㄨㄢˋ；傳送傳播讀ㄔㄨㄢˊ。`,e:`紀傳、傳奇書籍讀ㄓㄨㄢˋ，如水滸傳、自傳。`},r),(t,n,r,i=`medium`)=>e({q:`下列句子中的「喝」字，何者讀音為「ㄏㄜˋ」？`,c:`當頭棒「喝」`,d:[`「喝」口溫水`,`大口「喝」湯`,`「喝」茶聊天`],h:`大聲斥責讀ㄏㄜˋ；飲用讀ㄏㄜ。`,e:`「當頭棒喝」指大聲喝斥以促人警醒，讀ㄏㄜˋ。`},r),(t,n,r,i=`medium`)=>e({q:`下列各句中的「間」字，何者讀音為「ㄐㄧㄢˋ」？`,c:`挑撥離「間」`,d:[`房「間」寬敞`,`天地之「間」`,`字裡行「間」`],h:`挑撥使產生嫌隙讀ㄐㄧㄢˋ；處所與範圍之中讀ㄐㄧㄢ。`,e:`離間之「間」作動詞使生隔閡，讀ㄐㄧㄢˋ；房間、天地之間、字裡行間皆讀ㄐㄧㄢ。`},r),(t,n,r,i=`medium`)=>e({q:`「反躬自省」與「不省人事」中的「省」字讀音依序為何？`,c:`ㄒㄧㄥˇ ／ ㄒㄧㄥˇ`,d:[`ㄒㄧㄥˇ ／ ㄕㄥˇ`,`ㄕㄥˇ ／ ㄒㄧㄥˇ`,`ㄕㄥˇ ／ ㄕㄥˇ`],h:`檢查自知讀ㄒㄧㄥˇ；節約讀ㄕㄥˇ。`,e:`自省（自我反省）與人事省知皆讀ㄒㄧㄥˇ。`},r),(t,n,r,i=`medium`)=>e({q:`下列詞語中的「降」字，何者讀音為「ㄒㄧㄤˊ」？`,c:`降龍伏虎、誘「降」敵軍`,d:[`「降」低成本`,`氣溫驟「降」`,`「降」落傘兵`],h:`投降、降伏讀ㄒㄧㄤˊ；落下減低讀ㄐㄧㄤˋ。`,e:`降龍伏虎之「降」為降伏服從，讀ㄒㄧㄤˊ。`},r),(t,n,r,i=`medium`)=>e({q:`「少不更事」與「改弦更張」中的「更」字讀音依序為何？`,c:`ㄍㄥ ／ ㄍㄥ`,d:[`ㄍㄥˋ ／ ㄍㄥ`,`ㄍㄥ ／ ㄍㄥˋ`,`ㄍㄥˋ ／ ㄍㄥˋ`],h:`經歷、改變讀ㄍㄥ；更加讀ㄍㄥˋ。`,e:`少不更事（經歷）與改弦更張（改變）皆讀ㄍㄥ。`},r),(t,n,r,i=`medium`)=>e({q:`下列各句中的「強」字，何者讀音為「ㄑㄧㄤˇ」？`,c:`勉強答應、強詞奪理`,d:[`身體強壯`,`強弩之末`,`強項令名`],h:`硬逼、勉強讀ㄑㄧㄤˇ；強大讀ㄑㄧㄤˊ。`,e:`強詞奪理、強人所難讀ㄑㄧㄤˇ。`},r),(t,n,r,i=`medium`)=>e({q:`下列文句中的「和」字，何者讀音為「ㄏㄜˋ」？`,c:`曲高「和」寡`,d:[`「和」睦相處`,`「和」顏悅色`,`風「和」日麗`],h:`唱和、應和讀ㄏㄜˋ；溫和、和諧讀ㄏㄜˊ。`,e:`曲高和寡指曲調高雅而跟著唱和的人稀少，和讀ㄏㄜˋ；其餘三項皆讀ㄏㄜˊ。`},r),(t,n,r,i=`medium`)=>e({q:`下列詞語中的「量」字，何者讀音為「ㄌㄧㄤˋ」？`,c:`量入為出、前途不可限「量」`,d:[`丈「量」土地`,`思「量」再三`,`「量」體溫計`],h:`測量讀ㄌㄧㄤˊ；限度、容量讀ㄌㄧㄤˋ。`,e:`量入為出之「量」指限度份量，讀ㄌㄧㄤˋ。`},r),(t,n,r,i=`medium`)=>e({q:`「百折不撓」與「折本賠錢」中的「折」字讀音依序為何？`,c:`ㄓㄜˊ ／ ㄕㄜˊ`,d:[`ㄓㄜˊ ／ ㄓㄜˊ`,`ㄕㄜˊ ／ ㄓㄜˊ`,`ㄓㄜ ／ ㄕㄜˊ`],h:`虧本讀ㄕㄜˊ；彎曲挫折讀ㄓㄜˊ。`,e:`挫折讀ㄓㄜˊ；折本、賠本讀ㄕㄜˊ。`},r),(t,n,r,i=`medium`)=>e({q:`下列各詞語中的「著」字，何者讀音為「ㄓㄨㄛˊ」？`,c:`「著」手進行、棋高一「著」`,d:[`「著」急萬分`,`順水推舟「著」`,`名「著」出版`],h:`接觸、下手讀ㄓㄨㄛˊ；著急讀ㄓㄠˊ；著名讀ㄓㄨˋ。`,e:`著手處理之「著」讀ㄓㄨㄛˊ。`},r),(t,n,r,i=`medium`)=>e({q:`下列成語中的「拾」字，何者讀音為「ㄕㄜˋ」？`,c:`「拾」級而上`,d:[`「拾」人牙慧`,`「拾」金不昧`,`路不「拾」遺`],h:`拾級而上之拾為升登階梯，讀ㄕㄜˋ。`,e:`拾級而上指順著台階一步步往上走，讀ㄕㄜˋ。`},r),(t,n,r,i=`medium`)=>e({q:`「奇貨可居」與「奇數偶數」中的「奇」字讀音依序為何？`,c:`ㄑㄧˊ ／ ㄐㄧ`,d:[`ㄐㄧ ／ ㄑㄧˊ`,`ㄑㄧˊ ／ ㄑㄧˊ`,`ㄐㄧ ／ ㄐㄧ`],h:`單數讀ㄐㄧ；稀奇奇特讀ㄑㄧˊ。`,e:`奇貨為稀奇少見之貨物，讀ㄑㄧˊ；單數為奇數，讀ㄐㄧ。`},r),(t,n,r,i=`medium`)=>e({q:`「宿敵」與「星宿」中的「宿」字讀音依序為何？`,c:`ㄙㄨˋ ／ ㄒㄧㄡˋ`,d:[`ㄒㄧㄡˋ ／ ㄙㄨˋ`,`ㄙㄨˋ ／ ㄙㄨˇ`,`ㄒㄧㄡ ／ ㄙㄨˋ`],h:`星座讀ㄒㄧㄡˋ；長久、住宿讀ㄙㄨˋ。`,e:`星宿指天體二十八星官，讀ㄒㄧㄡˋ；宿敵指舊日敵手，讀ㄙㄨˋ。`},r),(t,n,r,i=`medium`)=>e({q:`「乳臭未乾」中的「臭」字標準讀音為：`,c:`ㄒㄧㄡˋ`,d:[`ㄔㄡˋ`,`ㄡˋ`,`ㄐㄧㄡˋ`],h:`古代臭泛指氣味，音ㄒㄧㄡˋ。`,e:`乳臭未乾之「臭」音ㄒㄧㄡˋ，指身上還有吃奶的氣味，形容年少無知。`},r),(t,n,r,i=`medium`)=>e({q:`「熨帖」一詞形容心裡平靜安適或事情妥貼，其中的「熨」字讀音為：`,c:`ㄩˋ`,d:[`ㄩㄣˋ`,`ㄨㄟˋ`,`ㄧㄢˋ`],h:`注意熨斗讀ㄩㄣˋ，熨帖讀ㄩˋ。`,e:`熨帖音ㄩˋ ㄊㄧㄝ，形容妥貼適切。`},r),(t,n,r,i=`medium`)=>e({q:`「拓印」與「開拓」中的「拓」字讀音依序為何？`,c:`ㄊㄚˋ ／ ㄊㄨㄛˋ`,d:[`ㄊㄨㄛˋ ／ ㄊㄚˋ`,`ㄊㄨㄛˋ ／ ㄊㄨㄛˋ`,`ㄊㄚˋ ／ ㄊㄚˋ`],h:`用墨水摹印碑帖讀ㄊㄚˋ；擴展土地讀ㄊㄨㄛˋ。`,e:`拓印石碑讀ㄊㄚˋ；開拓疆土讀ㄊㄨㄛˋ。`},r),(t,n,r,i=`medium`)=>e({q:`「綢繆」一詞比喻未雨綢繆、事先防範，其「繆」字讀音為：`,c:`ㄇㄡˊ`,d:[`ㄇㄧㄡˋ`,`ㄇㄧㄠˋ`,`ㄌㄧㄠˊ`],h:`荒謬讀ㄇㄧㄡˋ；綢繆讀ㄇㄡˊ。`,e:`未雨綢繆之「繆」音ㄇㄡˊ，指纏縛修補。`},r),(t,n,r,i=`medium`)=>e({q:`「商賈」一詞指經商之人，其中的「賈」字讀音為：`,c:`ㄍㄨˇ`,d:[`ㄐㄧㄚˇ`,`ㄐㄧㄚˋ`,`ㄒㄧㄚˇ`],h:`姓賈讀ㄐㄧㄚˇ；商人、買賣讀ㄍㄨˇ。`,e:`行商坐賈之「賈」指商人，讀ㄍㄨˇ。`},r),(t,n,r,i=`medium`)=>e({q:`「審度」與「制度」中的「度」字讀音依序為何？`,c:`ㄉㄨㄛˋ ／ ㄉㄨˋ`,d:[`ㄉㄨˋ ／ ㄉㄨㄛˋ`,`ㄉㄨˋ ／ ㄉㄨˋ`,`ㄉㄨㄛˋ ／ ㄉㄨㄛˋ`],h:`估計衡量讀ㄉㄨㄛˋ；法規限度讀ㄉㄨˋ。`,e:`審度形勢之「度」為推測衡量，讀ㄉㄨㄛˋ；法度制度讀ㄉㄨˋ。`},r),(t,n,r,i=`medium`)=>e({q:`「參見」與「人參」中的「參」字讀音依序為何？`,c:`ㄘㄢ ／ ㄕㄣ`,d:[`ㄕㄣ ／ ㄘㄢ`,`ㄘㄣ ／ ㄕㄣ`,`ㄘㄢ ／ ㄘㄣ`],h:`參拜讀ㄘㄢ；補品人參讀ㄕㄣ；參差讀ㄘㄣ。`,e:`參見讀ㄘㄢ；中藥人參讀ㄕㄣ。`},r),(t,n,r,i=`medium`)=>e({q:`下列成語中，何者字形「完全無誤」？`,c:`墨守成規`,d:[`墨守成歸`,`墨守陳規`,`默守成規`],h:`戰國墨子善於守城。`,e:`戰國時墨子善於守城防禦，後人稱為「墨守成規」，不可寫作「歸」或「默」。`},r),(t,n,r,i=`medium`)=>e({q:`下列文句中，何者「沒有」錯別字？`,c:`他在考試中名列前茅，表現優異`,d:[`他在考試中名列前矛，表現優異`,`他在考試中明列前茅，表現優異`,`他在考試中名列前芒，表現優異`],h:`前茅為古代行軍在前持茅草示警者。`,e:`「名列前茅」指成績名列前席，茅不可寫作「矛」。`},r),(t,n,r,i=`medium`)=>e({q:`「做事應該＿＿＿＿，不可急於求成。」空格處最適宜填入的正確成語為：`,c:`按部就班`,d:[`按步就班`,`案部就班`,`按部究班`],h:`部指門類，班指次序。`,e:`「按部就班」指依照規矩門類次序做事，部不可寫作「步」。`},r),(t,n,r,i=`medium`)=>e({q:`下列成語何者字形「正確無誤」？`,c:`趨之若鶩`,d:[`趨之若騖`,`趨之若鰵`,`驅之若鶩`],h:`鶩為野鴨，奔走如鴨成群。`,e:`「趨之若鶩」指像野鴨群集一樣奔赴，鶩為鴨，不可寫作奔馳之「騖」。`},r),(t,n,r,i=`medium`)=>e({q:`「他為人＿＿＿＿，從不聽取別人的善意建言。」下列用字何者完全正確？`,c:`剛愎自用`,d:[`剛復自用`,`剛腹自用`,`剛履自用`],h:`愎音ㄅㄧˋ，任性固執。`,e:`「剛愎自用」指性情倔強任性，自以為是，不可寫作「復」或「腹」。`},r),(t,n,r,i=`medium`)=>e({q:`下列文句中的成語用字，何者「完全正確」？`,c:`為了大局著想，他選擇委曲求全`,d:[`為了大局著想，他選擇委屈求全`,`為了大局著想，他選擇委曲求權`,`為了大局著想，他選擇微曲求全`],h:`曲指曲折遷就。`,e:`「委曲求全」指勉強遷就以求事情圓滿，應作「曲」而非「屈」。`},r),(t,n,r,i=`medium`)=>e({q:`「這篇社論切中時弊，堪稱＿＿＿＿之作。」空格處應填入：`,c:`針砭時弊`,d:[`針貶時弊`,`針乏時弊`,`真砭時弊`],h:`砭為古代治病石針。`,e:`「針砭」為古代以石針治病，引申為指出缺點勸誡，不可寫作貶謫之「貶」。`},r),(t,n,r,i=`medium`)=>e({q:`下列各組詞語中，何者「沒有」任何錯別字？`,c:`再接再厲、未雨綢繆`,d:[`再接再勵、未雨綢繆`,`再接再厲、未雨愁繆`,`再接再利、未雨稠繆`],h:`厲為磨刀石，接厲為雞相鬥磨喙。`,e:`「再接再厲」之厲為磨礪，不可作「勵」；綢繆為修補纏縛。`},r),(t,n,r,i=`medium`)=>e({q:`「在合唱團裡滥竽充數是不可能長久的。」句中劃線處字形何者完全正確？`,c:`濫竽充數`,d:[`爛竽充數`,`濫竿充數`,`濫竽衝數`],h:`竽為古代竹製吹奏樂器。`,e:`「濫竽充數」之竽為竹製樂器，不可寫作釣竿之「竿」。`},r),(t,n,r,i=`medium`)=>e({q:`下列文句中，何者字形「完全正確」？`,c:`他因投資失利而走投無路，最後鋌而走險`,d:[`他因投資失利而走投無路，最後挺而走險`,`他因投資失利而走投無路，最後艇而走險`,`他因投資失利而走投無路，最後廷而走險`],h:`鋌音ㄊㄧㄥˇ，快走急奔貌。`,e:`「鋌而走險」指在窮途末路中冒險行事，作「鋌」不可作「挺」。`},r),(t,n,r,i=`medium`)=>e({q:`「街道上車水馬龍，人潮＿＿＿＿。」空格處最適當之成語為：`,c:`川流不息`,d:[`穿流不息`,`川流不熄`,`穿流不熄`],h:`川為河流，如水奔流不停。`,e:`「川流不息」形容往來不絕像河流奔騰，不可寫作穿透之「穿」。`},r),(t,n,r,i=`medium`)=>e({q:`下列何者「沒有」錯別字？`,c:`世事難料，昔日的繁華不過是黃粱一夢`,d:[`世事難料，昔日的繁華不過是黃梁一夢`,`世事難料，昔日的繁華不過是黃糧一夢`,`世事難料，昔日的繁華不過是黃涼一夢`],h:`粱為黃米小米。`,e:`唐代盧生夢中歷盡富貴，醒來鍋中黃粱飯未熟，故作「黃粱一夢」，非棟樑之「梁」。`},r),(t,n,r,i=`medium`)=>e({q:`「這個制度的弊端已經＿＿＿＿，非改革不可。」應填入：`,c:`病入膏肓`,d:[`病入高肓`,`病入膏盲`,`病入高盲`],h:`膏為心尖脂肪，肓為心臟與橫膈膜之間。`,e:`「膏肓」指人體心膈微深之處，藥力難及，作「膏肓」不可寫作「盲」。`},r),(t,n,r,i=`medium`)=>e({q:`項羽率軍渡河後「皆沉船，破釜甑，燒廬舍」，此歷史典故形成的成語為：`,c:`破釜沉舟`,d:[`破斧沉舟`,`破釜陳舟`,`破斧成舟`],h:`釜為煮飯鐵鍋。`,e:`「破釜沉舟」指砸破鐵鍋鑿沉渡船以示必死決心，釜為炊具，不可寫作斧頭之「斧」。`},r),(t,n,r,i=`medium`)=>e({q:`下列文句中，哪一個成語用字「完全正確」？`,c:`只要持之以恆融會貫通，學問自然精進`,d:[`只要持之以恆融匯貫通，學問自然精進`,`只要持之以恆融惠貫通，學問自然精進`,`只要持之以恆榮會貫通，學問自然精進`],h:`融會指融合領會。`,e:`「融會貫通」之會為領會理解，不可寫作水流匯聚之「匯」。`},r),(t,n,r,i=`medium`)=>e({q:`警方透過現場遺留的微小線索，終於找到了嫌犯的：`,c:`蛛絲馬跡`,d:[`蛛絲螞跡`,`蛛絲馬蹟`,`株絲馬跡`],h:`馬跡為灶馬昆蟲爬行痕跡。`,e:`「蛛絲馬跡」之馬指灶馬（節肢動物）或馬蹄痕跡，不可作「螞」或「株」。`},r),(t,n,r,i=`medium`)=>e({q:`下列詞語中的字形，何者「有錯字」？`,c:`絡譯不絕`,d:[`克紹箕裘`,`相輔相成`,`滄海一粟`],h:`繹指抽絲連續不斷。`,e:`「絡繹不絕」指往來不斷如抽絲，不可作翻譯之「譯」。`},r),(t,n,r,i=`medium`)=>e({q:`陶淵明筆下遠離塵世喧囂的美好居所，後世稱為：`,c:`世外桃源`,d:[`世外桃園`,`世外源頭`,`世外逃源`],h:`桃花源之溪水水源處。`,e:`出自《桃花源記》，指避世樂土，為「桃源」不可寫作花園之「園」。`},r),(t,n,r,i=`medium`)=>e({q:`下列賀人金榜及第之詞語，何者用字完全正確？`,c:`金榜題名`,d:[`金榜提名`,`金榜提民`,`金榜題目`],h:`題名為在榜單上題寫名字。`,e:`科舉中榜稱為「金榜題名」，題為書寫之意，不可寫作提拔之「提」。`},r),(t,n,r,i=`medium`)=>e({q:`「一聽到放學鐘聲，同學們都＿＿＿＿地衝出教室。」最合適且字形正確的是：`,c:`迫不及待`,d:[`迫不急待`,`魄不及待`,`迫不及代`],h:`急迫得不能等待。`,e:`「迫不及待」形容情況急迫急切，及為趕上之意，不可寫作「急」。`},r),(t,n,r,i=`medium`)=>e({q:`「對於過去無心犯下的過失，我們應採取寬容態度，＿＿＿＿。」空格應填：`,c:`既往不咎`,d:[`既往不糾`,`繼往不咎`,`既往不舅`],h:`咎為責怪處分。`,e:`「既往不咎」指對以往的過錯不再追究責怪，咎不可寫作「糾」。`},r),(t,n,r,i=`medium`)=>e({q:`下列成語用字完全正確的是：`,c:`不脛而走`,d:[`不徑而走`,`不逕而走`,`不勁而走`],h:`脛為小腿。`,e:`「不脛而走」比喻事物不待推廣即迅速傳播，脛為小腿，不可作路徑之「徑」。`},r),(t,n,r,i=`medium`)=>e({q:`「這首動聽的流行歌曲傳唱大街小巷，早已＿＿＿＿。」空格處字形正確的是：`,c:`膾炙人口`,d:[`檜炙人口`,`燴炙人口`,`膾灸人口`],h:`膾為細切肉，炙為烤肉，皆美味為人所喜愛。`,e:`「膾炙人口」膾（肉部）為細切肉，炙為烤肉，不可寫作木部之「檜」、煮菜之「燴」或針灸之「灸」。`},r),(t,n,r,i=`medium`)=>e({q:`下列詞語中，何者「沒有」錯別字？`,c:`出類拔萃`,d:[`出類拔粹`,`出類拔翠`,`出類拔碎`],h:`萃為草木叢聚，引申指同類聚集。`,e:`「出類拔萃」形容才能超出同類之上，萃為聚，不可寫作精粹之「粹」或翡翠之「翠」。`},r),(t,n,r,i=`medium`)=>e({q:`下列關於「相形見絀」的字形與字義，何者正確？`,c:`絀音ㄔㄨˋ，指不足、欠缺`,d:[`應寫作「相形見拙」`,`應寫作「相形見黜」`,`絀音ㄓㄨㄛˊ，指笨拙`],h:`兩相比較下顯得不足。`,e:`「相形見絀」互相比較之下顯得欠缺不足，絀為不足，不可作「拙」或「黜」。`},r),(t,n,r,i=`medium`)=>e({q:`「在國內醫學領域中，他的外科手術技術堪稱＿＿＿＿。」應填入：`,c:`首屈一指`,d:[`手屈一指`,`首曲一指`,`首屈一直`],h:`彎曲手指計數第一。`,e:`「首屈一指」扳動手指計數時先彎下大拇指，指第一名，首不可作「手」。`},r),(t,n,r,i=`medium`)=>e({q:`古代暴君草菅人命，殘害百姓。其中「菅」字正確寫法與部首為：`,c:`草部，「菅」音ㄐㄧㄢ，指茅草`,d:[`竹部，「管」音ㄍㄨㄢˇ`,`木部，「棺」音ㄍㄨㄢ`,`草部，「菅」音ㄍㄨㄢ`],h:`菅為野草，把人命看得像野草一般賤微。`,e:`「草菅人命」草菅皆為茅草，視人命如野草，菅音ㄐㄧㄢ，不可作「管」。`},r),(t,n,r,i=`medium`)=>e({q:`下列哪一個成語用字完全無誤？`,c:`分道揚鑣`,d:[`分道揚標`,`分道揚鏢`,`分道揚驃`],h:`鑣為馬勒口之鐵。`,e:`「分道揚鑣」指各自策馬走不同的道路，鑣為馬具，不可寫作標準之「標」。`},r),(t,n,r,i=`medium`)=>e({q:`「由於長年耳濡目染，他在藝術鑑賞方面展現出過人天賦。」句中「耳濡目染」字形何者正確？`,c:`耳濡目染`,d:[`耳儒目染`,`耳如目染`,`耳濡目冉`],h:`濡為浸潤。`,e:`「耳濡目染」濡為沾濕浸潤，指經常聽見看見因而深受薰陶影響，濡不可寫作「儒」。`},r),(t,n,r,i=`medium`)=>e({q:`下列成語何者字形「錯誤」？`,c:`飲鳩止渴`,d:[`噤若寒蟬`,`杯盤狼藉`,`撲朔迷離`],h:`鴆為毒鳥，毒酒為鴆酒。`,e:`「飲鴆止渴」鴆為傳說中羽毛浸酒能毒死人的毒鳥，不可寫作鳩占鵲巢之「鳩」。`},r),(t,n,r,i=`medium`)=>e({q:`「故人西辭黃鶴樓」這句詩在現代語法句型中屬於下列何者？`,c:`敘事句`,d:[`有無句`,`表態句`,`判斷句`],h:`有動作行為的敘述。`,e:`「故人」（主語）「西辭」（述語動詞）「黃鶴樓」（賓語），為標準敘事句。`},r),(t,n,r,i=`medium`)=>e({q:`「白日依山盡」與「黃河入海流」在句型分類上皆屬於：`,c:`敘事句`,d:[`判斷句`,`表態句`,`有無句`],h:`依山盡、入海流皆為動態行為動作。`,e:`兩句皆含有述語動詞（依、入），說明主語的動態行為，屬敘事句。`},r),(t,n,r,i=`medium`)=>e({q:`下列哪一個句子屬於「判斷句」結構（主語＋繫詞＋斷語）？`,c:`他是本校最優秀的模範生`,d:[`小鳥在枝頭快樂地唱歌`,`湖水非常清澈碧綠`,`花園裡有許多盛開的玫瑰`],h:`含有繫詞「是」或「為」。`,e:`「他」（主語）「是」（繫詞）「模範生」（斷語），為典型的判斷句。`},r),(t,n,r,i=`medium`)=>e({q:`「環滁皆山也」句中的「也」字具有斷定語氣，其句型結構屬於：`,c:`判斷句`,d:[`敘事句`,`表態句`,`有無句`],h:`古代文言以「...者...也」表示判斷。`,e:`《醉翁亭記》「環滁皆山也」省略繫詞，透過句末「也」表示判斷，是古文標準判斷句。`},r),(t,n,r,i=`medium`)=>e({q:`「宅邊有五柳樹」在句型上屬於下列何者？`,c:`有無句`,d:[`敘事句`,`判斷句`,`表態句`],h:`述語為「有」或「無」。`,e:`以「有」或「無」為述語動詞表示存在與否的句子，稱為有無句。`},r),(t,n,r,i=`medium`)=>e({q:`下列句子中，何者屬於「表態句」（主語＋表語）？`,c:`夜色真美`,d:[`明月照亮了大地`,`這是我的家鄉`,`樹上有幾隻小鳥`],h:`表語為形容詞，描繪人事物之性質或狀態。`,e:`「夜色」（主語）「真美」（表語，形容詞），不含繫詞與動作，為標準表態句。`},r),(t,n,r,i=`medium`)=>e({q:`「菊，花之隱逸者也」在句型結構上屬於：`,c:`判斷句`,d:[`敘事句`,`表態句`,`有無句`],h:`文言文標準的「...者也」判斷句型。`,e:`周敦頤《愛蓮說》中斷定菊花為隱逸之花，為判斷句。`},r),(t,n,r,i=`medium`)=>e({q:`「屋頂上有幾隻小貓」屬於何種句型？`,c:`有無句`,d:[`敘事句`,`判斷句`,`表態句`],h:`以「有」為述語。`,e:`此句說明小貓在屋頂上的客觀存在狀態，述語為「有」，故為有無句。`},r),(t,n,r,i=`medium`)=>e({q:`「月落烏啼霜滿天」中的「霜滿天」結構屬於：`,c:`表態句`,d:[`敘事句`,`判斷句`,`有無句`],h:`霜為名詞主語，滿天為形容狀態。`,e:`「霜滿天」描摹寒霜瀰漫天際之狀態，為表態句。`},r),(t,n,r,i=`medium`)=>e({q:`「天生我材必有用」中的「天生我材」屬於下列何種結構？`,c:`敘事句`,d:[`判斷句`,`表態句`,`有無句`],h:`天（主語）生（動詞）我材（賓語）。`,e:`「天」（主語）「生」（述語動詞）「我材」（賓語），屬敘事句。`},r),(t,n,r,i=`medium`)=>e({q:`下列何者為「無」字開頭的「有無句」？`,c:`天下無不散的筵席`,d:[`無私的愛最偉大`,`無意中的發現改變了一切`,`無聲無息地走進屋內`],h:`述語必須為表示存在之「無」。`,e:`「天下」（主語）「無」（述語）「不散的筵席」（賓語），為標準有無句。`},r),(t,n,r,i=`medium`)=>e({q:`「良藥苦口」在句子結構上屬於下列何者？`,c:`表態句`,d:[`敘事句`,`判斷句`,`有無句`],h:`苦口為形容詞片語，描寫藥的滋味狀態。`,e:`「良藥」（主語）「苦口」（表語形容詞），說明其特性，屬表態句。`},r),(t,n,r,i=`medium`)=>e({q:`下列文句中，何者為「敘事句」？`,c:`微風輕輕拂過水面`,d:[`水面宛如一面鏡子`,`這座湖泊十分寧靜`,`湖底有游動的魚群`],h:`含有具體動態述語動詞。`,e:`「拂過」為具體動作之述語動詞，微風為主語，水面為賓語，為敘事句。`},r),(t,n,r,i=`medium`)=>e({q:`「天下事有難易乎？為之，則難者亦易矣」句中「天下事有難易」為：`,c:`有無句`,d:[`判斷句`,`敘事句`,`表態句`],h:`核心述語為「有」。`,e:`以「有」表示難易之存在，屬有無句。`},r),(t,n,r,i=`medium`)=>e({q:`「落霞與孤鶩齊飛，秋水共長天一色」中，「秋水共長天一色」屬於：`,c:`表態句`,d:[`判斷句`,`敘事句`,`有無句`],h:`一色描繪秋水與長天渾然一體之色彩景象。`,e:`「一色」為表語形容詞，描寫景觀狀態，屬表態句。`},r),(t,n,r,i=`medium`)=>e({q:`「這本書是我在舊書店買的」句中主幹「這本書是...」屬於：`,c:`判斷句`,d:[`敘事句`,`表態句`,`有無句`],h:`以「是」為核心繫詞判定主體身分。`,e:`主語加繫詞「是」加斷語，為標準判斷句。`},r),(t,n,r,i=`medium`)=>e({q:`下列文句哪一句屬於「表態句」？`,c:`綠樹村邊合，青山郭外斜之「青山郭外斜」`,d:[`孟浩然拜訪故人`,`故人家中備有美味佳餚`,`故人具雞黍`],h:`斜形容青山橫亙遠方之姿態。`,e:`「青山」（主語）「郭外斜」（表語形容姿態），為表態句。`},r),(t,n,r,i=`medium`)=>e({q:`「風平浪靜」由兩個對稱結構組成，在句型上皆屬於：`,c:`表態句`,d:[`敘事句`,`判斷句`,`有無句`],h:`平與靜皆為形容狀態之形容詞。`,e:`風（主）平（表），浪（主）靜（表），皆為描摹狀態之表態句。`},r),(t,n,r,i=`medium`)=>e({q:`「失敗為成功之母」中的「為」字相當於現代漢語的「是」，此句型為：`,c:`判斷句`,d:[`敘事句`,`表態句`,`有無句`],h:`「為」作繫詞「是」解。`,e:`「失敗」（主語）「為」（繫詞）「成功之母」（斷語），為標準判斷句。`},r),(t,n,r,i=`medium`)=>e({q:`下列哪一個句子「不是」敘事句？`,c:`桃花流水鱖魚肥之「鱖魚肥」`,d:[`西塞山前白鷺飛`,`青箬笠，綠蓑衣，斜風細雨不須歸`,`漁翁在江上垂釣`],h:`魚肥描摹魚之豐美肥碩狀態，為表態句。`,e:`「鱖魚肥」為主語加形容詞表語，屬表態句，非動作敘事句。`},r),(t,n,r,i=`medium`)=>e({q:`「江山如此多嬌」在句型結構上屬於：`,c:`表態句`,d:[`判斷句`,`敘事句`,`有無句`],h:`多嬌為形容江山美麗多姿之表語。`,e:`主語「江山」加表語「如此多嬌」，屬表態句。`},r),(t,n,r,i=`medium`)=>e({q:`「室內雅靜無比」屬於何種句型？`,c:`表態句`,d:[`敘事句`,`判斷句`,`有無句`],h:`雅靜無比描繪室內氛圍狀態。`,e:`主語「室內」加形容詞性表語「雅靜無比」，為表態句。`},r),(t,n,r,i=`medium`)=>e({q:`「貧者語於富者曰」在句型上屬於：`,c:`敘事句`,d:[`判斷句`,`表態句`,`有無句`],h:`語（告訴）為述語動詞。`,e:`「貧者」（主語）「語」（述語）「富者」（賓語），為敘事句。`},r),(t,n,r,i=`medium`)=>e({q:`下列哪一句屬於「有無句」？`,c:`車到山前必有路`,d:[`山路非常崎嶇陡峭`,`這是一輛老舊的腳踏車`,`司機平穩地開著車`],h:`關鍵在於「有路」的存在陳述。`,e:`「必有路」是以「有」為述語陳述出路之存在，屬有無句。`},r),(t,n,r,i=`medium`)=>e({q:`「知之為知之，不知為不知，是知也」中末句「是知也」屬於：`,c:`判斷句`,d:[`敘事句`,`表態句`,`有無句`],h:`是為指示代詞這，也表示斷定語氣。`,e:`「是知也」意即「這就是智慧」，為古漢語典型判斷句。`},r),(t,n,r,i=`medium`)=>e({q:`「孤帆遠影碧空盡」在語法分析上，主要的述語動作是：`,c:`盡`,d:[`孤帆`,`碧空`,`遠影`],h:`說明孤帆的最終動態消失於天際。`,e:`「盡」在此處作述語動詞，表示消失不見之動作過程。`},r),(t,n,r,i=`medium`)=>e({q:`下列文句中，哪一句屬於「判斷句」？`,c:`知恩圖報是做人的根本美德`,d:[`他默默回報了當年的恩情`,`這份恩情重如泰山`,`世界上有許多感人肺腑的故事`],h:`以「是」連結做人根本美德之定義。`,e:`主語「知恩圖報」＋繫詞「是」＋斷語「美德」，為標準判斷句。`},r),(t,n,r,i=`medium`)=>e({q:`「路不拾遺，夜不閉戶」描繪社會治安良好，兩句結構皆為：`,c:`敘事句`,d:[`表態句`,`判斷句`,`有無句`],h:`拾遺、閉戶皆為動賓結構之行為。`,e:`「拾」（動詞）「遺」（失物）、「閉」（動詞）「戶」（大門），為省略主語之敘事句。`},r),(t,n,r,i=`medium`)=>e({q:`「天下英雄唯使君與操耳」在曹操與劉備煮酒論英雄時所言，此句型為：`,c:`判斷句`,d:[`敘事句`,`表態句`,`有無句`],h:`斷定天下英雄唯有二人。`,e:`曹操斷定天下真正的英雄只有劉備與自己，為古文判斷句。`},r),(t,n,r,i=`medium`)=>e({q:`下列四個句子中，何者為「表態句」？`,c:`秋高氣爽`,d:[`秋天來到了人間`,`秋天是收穫的季節`,`農夫在秋天收割稻穀`],h:`高與爽皆為描繪天候狀態之形容詞。`,e:`「秋高氣爽」由「秋（主）高（表）」與「氣（主）爽（表）」兩個表態句並列而成。`},r),(t,n,r,i=`medium`)=>e({q:`「光陰好比奔流不息的江水，一去不復返。」這句話使用的修辭手法為：`,c:`明喻`,d:[`隱喻`,`略喻`,`借喻`],h:`出現了喻詞「好比」。`,e:`含有本體（光陰）、喻詞（好比）、喻依（江水），為最標準的明喻。`},r),(t,n,r,i=`medium`)=>e({q:`「那座翠綠的山巒，是一具橫臥在大地上的綠色巨人。」此句之譬喻類型屬於：`,c:`隱喻`,d:[`明喻`,`略喻`,`借喻`],h:`喻詞為繫詞「是」。`,e:`本體與喻依之間以繫詞「是」相連，省去「像、如」等明喻詞，稱為隱喻（暗喻）。`},r),(t,n,r,i=`medium`)=>e({q:`「菊，花之隱逸者也；牡丹，花之富貴者也。」此處將花朵賦予人格特質，屬於：`,c:`擬人修辭`,d:[`借代修辭`,`映襯修辭`,`雙關修辭`],h:`將菊花比擬為具有隱逸情操之高士。`,e:`將物賦予人的品格與身分（隱逸者、富貴者），屬於轉化修辭中的擬人法。`},r),(t,n,r,i=`medium`)=>e({q:`「墨藍天幕上點亮萬顆碎鑽，枝頭正懸著一盞冰冷的白玉盤。」全句不出現星辰與明月，此種譬喻稱為：`,c:`借喻`,d:[`明喻`,`隱喻`,`略喻`],h:`只見喻依（碎鑽、白玉盤），不見本體（星辰、明月）。`,e:`借喻不出現本體與喻詞，直接以喻依代指本體（碎鑽喻星、白玉盤喻月）。`},r),(t,n,r,i=`medium`)=>e({q:`「松柏後凋於歲寒，雞鳴不已於風雨。」古人常藉松柏經霜雪而不凋比擬君子操守，此修辭思維為：`,c:`象徵與擬物轉化`,d:[`誇飾修辭`,`雙關修辭`,`設問修辭`],h:`藉堅毅物象寄託高尚德性。`,e:`藉松柏在嚴寒中長青象徵君子處亂世不改節操，兼具象徵與擬物思維。`},r),(t,n,r,i=`medium`)=>e({q:`「春風又綠江南岸」句中「綠」字將形容詞轉化為動詞使動用法，兼具生動的：`,c:`擬物轉化與動態生動美感`,d:[`諧音雙關`,`互文修辭`,`倒裝修辭`],h:`春風吹拂使江岸變綠。`,e:`「綠」字化靜態為動態，生動描寫春風吹醒大地草木之生機轉化。`},r),(t,n,r,i=`medium`)=>e({q:`「人面桃花相映紅」中的「相映紅」透過臉龐與桃花互相輝映，主要修辭技巧為：`,c:`映襯與色彩襯托`,d:[`倒裝修辭`,`頂真修辭`,`借喻修辭`],h:`桃花之粉嫩與少女紅潤臉龐交相輝映。`,e:`利用兩種美麗色彩物象互相襯托對照，凸顯春光中少女之嬌艷。`},r),(t,n,r,i=`medium`)=>e({q:`「看見母親那雙長滿厚繭的手，我不禁潸然淚下。」此句中的「手」借代指涉：`,c:`母親一生辛勤操勞的偉大付出`,d:[`母親的手工編織技藝`,`母親的手部疾病`,`家庭貧困無法購買手套`],h:`長滿厚繭的手象徵長年勞動奉獻。`,e:`以粗糙長繭的手這一局部具體特徵，借代母親終身為家庭辛勞付出的崇高母愛。`},r),(t,n,r,i=`medium`)=>e({q:`「那隻淘氣的風，偷偷掀翻了路人的帽子，又在樹梢間咯咯地笑。」這段文字使用了：`,c:`擬人法`,d:[`誇飾法`,`借代法`,`排比法`],h:`風會淘氣、掀帽子、在樹梢笑。`,e:`賦予無生命的「風」以淘氣的性格與咯咯笑的人類行為，為擬人轉化。`},r),(t,n,r,i=`medium`)=>e({q:`「問君能有幾多愁？恰似一江春水向東流。」這兩句詞主要運用的修辭手法為：`,c:`設問與明喻`,d:[`借代與誇飾`,`排比與對偶`,`頂真與層遞`],h:`先提問「能有幾多愁」，再以「恰似一江春水」為喻作答。`,e:`李煜先發自問，接著以洶湧奔騰的春水比喻無邊無際之愁思，結合設問與明喻。`},r),(t,n,r,i=`medium`)=>e({q:`「她的歌聲宛如天籟，清脆得像山澗中的泉水叮咚作響。」此句運用了：`,c:`明喻修辭`,d:[`暗喻修辭`,`借代修辭`,`擬人修辭`],h:`出現喻詞「宛如」、「像」。`,e:`歌聲為本體，以天籟、泉水叮咚為喻依，透過明喻生動表現其音色之優美。`},r),(t,n,r,i=`medium`)=>e({q:`「落紅不是無情物，化作春泥更護花。」龔自珍將落花擬人化，表達了何種情懷？`,c:`即使自身退隱凋零，依然願意培育奉獻給後起之秀的博大胸襟`,d:[`對生命短暫消逝的無奈悲嘆`,`對花開花落自然規律的憤恨`,`對世俗追名逐利者的鄙視`],h:`落花化泥滋養新花成長。`,e:`將落花賦予有情有義的人格特質，象徵雖去官退隱仍心繫國家未來之奉獻精神。`},r),(t,n,r,i=`medium`)=>e({q:`「孤獨是一匹奔馳在荒野上的狼。」這句話的修辭手法屬於：`,c:`隱喻`,d:[`明喻`,`借喻`,`轉化`],h:`喻詞為「是」。`,e:`以「孤獨」（本體）配上繫詞「是」與「狼」（喻依），省去比喻詞，為隱喻。`},r),(t,n,r,i=`medium`)=>e({q:`「月光如水銀瀉地般灑滿整個庭院。」此句之本體與喻依分別為何？`,c:`本體為「月光」，喻依為「水銀」`,d:[`本體為「水銀」，喻依為「月光」`,`本體為「庭院」，喻依為「水銀」`,`本體為「月光」，喻依為「庭院」`],h:`月光像傾瀉的水銀流淌。`,e:`描寫的對象是月光（本體），用來形容的比方是水銀瀉地（喻依）。`},r),(t,n,r,i=`medium`)=>e({q:`「太陽害羞地躲進了厚厚的雲層後面，露出一抹淡淡的紅暈。」此句修辭為：`,c:`擬人化轉化`,d:[`擬物化轉化`,`誇飾修辭`,`借喻修辭`],h:`太陽會害羞、躲藏、露出紅暈。`,e:`將太陽比擬為害羞的少女，賦予人類羞怯的情態，屬擬人轉化。`},r),(t,n,r,i=`medium`)=>e({q:`「那一條蜿蜒於群山之間的巨龍，就是名揚天下的萬里長城。」此句屬於：`,c:`隱喻`,d:[`明喻`,`借喻`,`略喻`],h:`以「巨龍」為喻依，以「是」連接長城。`,e:`將萬里長城比作巨龍，以繫詞相連，為生動之隱喻。`},r),(t,n,r,i=`medium`)=>e({q:`「風聲鶴唳，草木皆兵」形容秦軍在淝水之戰失敗後極度恐懼，其中含有何種轉化心理？`,c:`擬物化與心理移情轉化`,d:[`明喻修辭`,`對偶修辭`,`設問修辭`],h:`將風聲草木誤判為敵軍士兵。`,e:`極度驚恐下將大自然的風聲鶴鳴誤認作追兵喊殺，草木皆化為士兵，為生動之情境轉化。`},r),(t,n,r,i=`medium`)=>e({q:`「我是一早晨的露水，短暫卻晶瑩地映照過整個世界。」句中使用的譬喻為：`,c:`隱喻`,d:[`借喻`,`明喻`,`略喻`],h:`本體「我」，繫詞「是」，喻依「露水」。`,e:`以「是」連結自我與晨露，省去明喻詞，屬隱喻修辭。`},r),(t,n,r,i=`medium`)=>e({q:`下列各句中，何者「沒有」使用轉化修辭？`,c:`窗外的雨滴滴答答下個不停`,d:[`花兒在微風中向我們點頭微笑`,`時間老人步履蹣跚地向前邁進`,`飢餓的胃正向大腦發出抗議的怒吼`],h:`純粹摹寫雨聲，未將雨人格化。`,e:`「滴滴答答」為聲音之摹寫（擬聲詞），未將無生命之物人格化或形象化。`},r),(t,n,r,i=`medium`)=>e({q:`「那張考卷彷彿一張無法逾越的冰山，橫亙在眼前。」此句之修辭法為：`,c:`明喻修辭`,d:[`借喻修辭`,`排比修辭`,`頂真修辭`],h:`含有喻詞「彷彿」。`,e:`考卷（本體）彷彿（喻詞）冰山（喻依），為典型明喻。`},r),(t,n,r,i=`medium`)=>e({q:`「狂風咆哮著撕扯著大樹的枝幹，暴雨如注傾盆而下。」句中「狂風咆哮撕扯」運用的修辭是：`,c:`擬人法轉化`,d:[`借代法`,`對偶法`,`回文法`],h:`賦予風咆哮、撕扯之人獸兇猛動作。`,e:`將自然風暴擬人擬獸化，展現強烈震撼之動態張力。`},r),(t,n,r,i=`medium`)=>e({q:`「忽如一夜春風來，千樹萬樹梨花開。」岑參以梨花盛開比喻邊塞雪景，此譬喻屬於：`,c:`借喻`,d:[`明喻`,`略喻`,`暗喻`],h:`全句未出現本體「雪花」，直接以梨花代之。`,e:`不寫雪花（本體），直接以千樹萬樹梨花（喻依）盛開描摹塞外大雪，為借喻經典。`},r),(t,n,r,i=`medium`)=>e({q:`「他的沉默，就像暴風雨來臨前夕那片壓抑窒息的死寂。」此句屬於：`,c:`明喻修辭`,d:[`隱喻修辭`,`轉化修辭`,`借代修辭`],h:`出現了喻詞「就像」。`,e:`以沉默（本體）就像（喻詞）死寂（喻依），為明喻。`},r),(t,n,r,i=`medium`)=>e({q:`「海浪像一群不知疲倦的孩子，一次次奔向金黃的沙灘。」這句話結合了：`,c:`明喻與擬人轉化`,d:[`暗喻與誇飾`,`借喻與對偶`,`排比與映襯`],h:`「像不知疲倦的孩子」為明喻，且孩子奔跑為擬人動作。`,e:`既使用明喻（像孩子），又賦予海浪奔向沙灘的童趣行為（擬人）。`},r),(t,n,r,i=`medium`)=>e({q:`「歲月是一部未曾校稿的書，我們邊走邊讀，回頭才看懂註腳。」這句話主要運用的譬喻類型屬於：`,c:`隱喻`,d:[`明喻`,`借喻`,`略喻`],h:`歲月（本體）是（繫詞）書（喻依）。`,e:`以繫詞「是」連接歲月與書，省去「好像、宛如」等喻詞，屬於隱喻（暗喻）。`},r),(t,n,r,i=`medium`)=>e({q:`「大自然伸出溫暖的雙手，撫慰著遊子疲憊的心靈。」此句運用的修辭為：`,c:`擬人法轉化`,d:[`誇飾修辭`,`借代修辭`,`雙關修辭`],h:`大自然具有溫暖雙手與撫慰動作。`,e:`將抽象的大自然人格化，賦予雙手與撫慰行為，屬擬人轉化。`},r),(t,n,r,i=`medium`)=>e({q:`「他那堅毅的心，是任憑風吹雨打也絕不動搖的金石。」此句為：`,c:`隱喻修辭`,d:[`借喻修辭`,`明喻修辭`,`略喻修辭`],h:`以「是」相連。`,e:`堅毅的心是金石，省去明喻詞，為隱喻。`},r),(t,n,r,i=`medium`)=>e({q:`「愁緒像一團理不清的亂麻，緊緊纏繞在心頭。」此處喻依為：`,c:`亂麻`,d:[`愁緒`,`心頭`,`纏繞`],h:`拿來比方愁緒的具體物象是亂麻。`,e:`愁緒是本體，亂麻是喻依，像為喻詞。`},r),(t,n,r,i=`medium`)=>e({q:`「小溪在山谷間歡快地奔跑跳躍，唱著清脆悠揚的歌謠。」此段文字運用了：`,c:`擬人化轉化`,d:[`擬物化轉化`,`排比修辭`,`映襯修辭`],h:`溪水會奔跑、跳躍、唱歌。`,e:`賦予流水人類幼童之生動舉止，為典型擬人法。`},r),(t,n,r,i=`medium`)=>e({q:`下列關於「譬喻」與「借代」之本質差別，說明最精確的是：`,c:`譬喻基於兩事物間的『相似性』；借代基於兩事物間的『相關性或特徵依附』`,d:[`譬喻只能用於詩歌，借代只能用於散文`,`譬喻一定有喻詞，借代一定沒有喻詞`,`借代兩者完全相同，譬喻兩者毫無關聯`],h:`相似性為喻，相關特徵為代。`,e:`譬喻核心在於兩者本質不同但具某種相似點；借代則是取該事物密切相關之特徵代指全體。`},r),(t,n,r,i=`medium`)=>e({q:`「朱門酒肉臭，路有凍死骨。」杜甫這兩句詩所運用的主要修辭手法為：`,c:`映襯修辭`,d:[`借代修辭`,`層遞修辭`,`誇飾修辭`],h:`豪門富貴酒肉腐臭對比路邊窮民凍死骨骸。`,e:`將貧富極端懸殊之殘酷現實置於同列對照，形成震撼之強烈映襯。`},r),(t,n,r,i=`medium`)=>e({q:`「烽火連三月，家書抵萬金。」杜甫在此運用的修辭手法包含：`,c:`對偶與誇飾`,d:[`雙關與排比`,`借喻與頂真`,`反詰與設問`],h:`字數詞性對仗，且以萬金極言家書之難得。`,e:`上下句平仄對仗工整為對偶，將一封家信形容為價值萬金為誇飾。`},r),(t,n,r,i=`medium`)=>e({q:`「東邊日出西邊雨，道是無晴卻有晴。」劉禹錫此處「晴」字雙關指涉：`,c:`天氣晴朗與男女私情`,d:[`眼睛明亮與心情豁達`,`白晝光明與黑夜清澄`,`情深意重與絕情寡義`],h:`晴字與感情之情諧音。`,e:`表面寫天氣晴雨不定，實則借「晴」諧「情」，寫少女揣度對方心思。`},r),(t,n,r,i=`medium`)=>e({q:`「臣本布衣，躬耕於南陽。」諸葛亮《出師表》中以「布衣」借代：`,c:`平民百姓`,d:[`貧困乞丐`,`布匹商人`,`隱士道士`],h:`古代平民穿麻布衣服，貴族穿絲綢。`,e:`古代官宦著綾羅綢緞，平民穿麻布，故以「布衣」借代平民百姓。`},r),(t,n,r,i=`medium`)=>e({q:`「忽如一夜春風來，千樹萬樹梨花開。」若從寫景規模來看，全句包含：`,c:`誇飾修辭與借喻修辭`,d:[`頂真修辭與排比修辭`,`映襯修辭與雙關修辭`,`回文修辭與倒裝修辭`],h:`一夜之間千樹萬樹全開滿，極言雪勢之大。`,e:`將雪花借喻為梨花，並以千樹萬樹一夕全開極言塞外雪勢之盛大神奇，屬誇飾與借喻。`},r),(t,n,r,i=`medium`)=>e({q:`「白髮三千丈，緣愁似個長。」李白這兩句詩運用的主要修辭手法是：`,c:`誇飾修辭`,d:[`對偶修辭`,`借代修辭`,`頂真修辭`],h:`頭髮長達三千丈，顯非客觀事實。`,e:`白髮三千丈為典型誇大誇飾法，藉由驚人的長度視覺象徵內心無邊無際之愁緒。`},r),(t,n,r,i=`medium`)=>e({q:`下列文句中，哪一項屬於三個以上結構相同分句並列的「排比修辭」？`,c:`富貴不能淫，貧賤不能移，威武不能屈`,d:[`學而時習之，不亦說乎`,`知者樂水，仁者樂山`,`海納百川，有容乃大`],h:`三個句型結構相同的排比排句。`,e:`孟子連續以三個「...不能...」句式並列鋪排，語氣磅礴，為標準排比。`},r),(t,n,r,i=`medium`)=>e({q:`「何以解憂？唯有杜康。」曹操《短歌行》中以「杜康」借代指稱：`,c:`美酒`,d:[`朋友`,`音樂`,`金錢`],h:`傳說杜康為古代最早造酒之人。`,e:`古代相傳杜康發明釀酒之法，後世遂以「杜康」借代為酒。`},r),(t,n,r,i=`medium`)=>e({q:`「蟬噪林逾靜，鳥鳴山更幽。」王籍這兩句詩所展現的藝術手法為：`,c:`以動襯靜的相反映襯手法`,d:[`借代與雙關`,`誇飾與排比`,`設問與擬人`],h:`藉由蟬噪與鳥鳴的聲響，反而襯托出山林格外幽靜。`,e:`以聲音之動對照環境之幽靜，動中顯靜，為古典映襯極致範例。`},r),(t,n,r,i=`medium`)=>e({q:`「過盡千帆皆不是，斜暉脈脈水悠悠。」句中「千帆」是以局部特徵借代：`,c:`船隻`,d:[`風帆布匹`,`水手船員`,`渡口碼頭`],h:`以船上的帆借代整艘渡船。`,e:`以船帆這一最顯眼之局部構造，借代整艘舟船，屬借代修辭。`},r),(t,n,r,i=`medium`)=>e({q:`「春蠶到死絲方盡，蠟炬成灰淚始乾。」句中「絲」字運用的修辭為：`,c:`諧音雙關`,d:[`誇飾修辭`,`倒裝修辭`,`互文修辭`],h:`春蠶吐絲雙關情人相思之思。`,e:`李商隱以蠶絲之「絲」諧音男女眷戀之「思」，語意雙關深厚。`},r),(t,n,r,i=`medium`)=>e({q:`「有緣千里來相會，無緣對面不相逢。」這兩句在結構與意境上屬於：`,c:`對偶與對稱映襯`,d:[`層遞修辭`,`借代修辭`,`頂真修辭`],h:`字數詞性相對，且有緣千里與無緣對面形成對立對照。`,e:`上下一聯對仗工整，且以千里相會與對面不逢形成強烈對照映襯。`},r),(t,n,r,i=`medium`)=>e({q:`「借問酒家何處有？牧童遙指杏花村。」杜牧此詩句運用的修辭手法為：`,c:`提問`,d:[`激問`,`懸問`,`排比`],h:`先發問酒家何在，接著回答牧童遙指之處。`,e:`先問後答，答案就在下文，為設問修辭中標準的「提問」。`},r),(t,n,r,i=`medium`)=>e({q:`「黃髮垂髫，並怡然自樂。」陶淵明《桃花源記》中以「黃髮垂髫」借代：`,c:`老人與小孩`,d:[`農夫與商賈`,`隱士與遊俠`,`官員與百姓`],h:`老人頭髮由白轉黃，小孩頭髮下垂未束髮。`,e:`黃髮形容高壽老人，垂髫指幼童髮式，兩者合用借代老人與小孩。`},r),(t,n,r,i=`medium`)=>e({q:`「燕雀安知鴻鵠之志哉！」陳涉起義時所言，在修辭上結合了：`,c:`激問與借喻`,d:[`排比與對偶`,`映襯與頂真`,`層遞與雙關`],h:`心中早有否定答案：燕雀根本不可能知道！`,e:`表面發問實則肯定無疑，答案在反面（激問），並以燕雀鴻鵠為喻（借喻）。`},r),(t,n,r,i=`medium`)=>e({q:`「無絲竹之亂耳，無案牘之勞形。」劉禹錫《陋室銘》中「絲竹」與「案牘」借代：`,c:`世俗嘈雜的音樂 與 繁瑣沉重的官府公文`,d:[`竹林樂器 與 書房桌椅`,`彈琴演奏 與 讀書寫字`,`貴族宴飲 與 讀書人試卷`],h:`絲絃竹管為樂器，案桌牘簡為官文書。`,e:`以絲竹借代世俗音樂，以案牘借代繁忙之官署公務公文。`},r),(t,n,r,i=`medium`)=>e({q:`「怒髮衝冠，憑欄處、瀟瀟雨歇。」岳飛在《滿江紅》開篇使用的誇飾為：`,c:`以頭髮憤怒直豎將帽子頂起，極言內心極度憤慨`,d:[`形容天候降雨極為猛烈`,`形容自己武功蓋世無人能敵`,`形容戰場刀槍碰撞聲音震撼`],h:`憤怒到頭髮豎立頂起帽子。`,e:`憤怒到了極點，頭髮直豎頂起頭冠，為經典情態誇飾法。`},r),(t,n,r,i=`medium`)=>e({q:`「天長地久有時盡，此恨綿綿無絕期。」白居易《長恨歌》結尾運用的手法為：`,c:`映襯與誇飾`,d:[`頂真與層遞`,`借代與雙關`,`互文與倒裝`],h:`天地縱然長久亦有盡頭，此恨卻永無休止。`,e:`以天地之終結襯托情感之永恆長存，形成強烈對比與極度情感誇飾。`},r),(t,n,r,i=`medium`)=>e({q:`下列文句中，哪一項屬於「層遞修辭」（由小到大、由淺入深、由輕到重）？`,c:`古之欲明明德於天下者，先治其國；欲治其國者，先齊其家；欲齊其家者，先修其身`,d:[`野火燒不盡，春風吹又生`,`人生自古誰無死，留取丹心照汗青`,`君子坦蕩蕩，小人長戚戚`],h:`天下 -> 國家 -> 家族 -> 個人修身，層層遞進。`,e:`《大學》條目依序由天下、治國、齊家推展至修身，為經典層遞結構。`},r),(t,n,r,i=`medium`)=>e({q:`「青青子衿，悠悠我心。」曹操借用《詩經》文句，其中以「子衿」（青色衣領）借代：`,c:`賢良有才華的求仕讀書人`,d:[`青少年的童年回憶`,`軍隊中披掛青甲的戰士`,`家中的親生骨肉`],h:`周代學士皆穿著青色領子之青衿長袍。`,e:`古代學子穿青衿，故以子衿借代渴望招攬延請之天下賢才。`},r),(t,n,r,i=`medium`)=>e({q:`「白日放歌須縱酒，青春作伴好還鄉。」杜甫這首詩中「青春」意指：`,c:`明媚蔥綠的春天景致`,d:[`青年男女的黃金年華`,`少年時期的同窗好友`,`軍隊勝利時的青春朝氣`],h:`春天草木青翠蔥蘢，故稱青春。`,e:`「青春」在此指春日融融之美好季節，並非指現代意義之少年年齡。`},r),(t,n,r,i=`medium`)=>e({q:`「楊柳青青江水平，聞郎江上踏歌聲。東邊日出西邊雨，道是無晴卻有晴。」全詩的詩眼在於：`,c:`藉由自然氣候之「晴」雙關人間相思之「情」`,d:[`描摹江水之遼闊平靜`,`刻畫踏歌聲之節奏歡快`,`展現江南春日雨景之變幻`],h:`「晴」即是「情」。`,e:`藉「晴」與「情」之諧音雙關，將少女心中既羞澀期待又忐忑不安之微妙情思表現得淋漓盡致。`},r),(t,n,r,i=`medium`)=>e({q:`「青山有幸埋忠骨，白鐵無辜鑄佞臣。」這副杭州岳飛墓前的名聯，在修辭上主要結合了下列何者？`,c:`對偶與映襯`,d:[`層遞與頂真`,`誇飾與設問`,`雙關與倒裝`],h:`「青山有幸」對「白鐵無辜」，以忠骨反襯佞臣。`,e:`上下聯詞性與字數對仗工整（對偶），並將岳飛忠魂與奸臣形成善惡鮮明對照（映襯）。`},r),(t,n,r,i=`medium`)=>e({q:`「一言既出，駟馬難追。」這句話在修辭手法上屬於：`,c:`誇飾修辭`,d:[`借喻修辭`,`設問修辭`,`排比修辭`],h:`四匹馬拉的快車也追趕不上說出口的一句話。`,e:`以駟馬快車也追不上講出之話，極言誠信與謹言慎行之重要，為誇飾法。`},r),(t,n,r,i=`medium`)=>e({q:`下列文句中，哪一句屬於「頂真修辭」（前句結尾詞語作為後句開頭）？`,c:`歸來見天子，天子坐明堂`,d:[`不患人之不己知，患不知人也`,`少壯不努力，老大徒傷悲`,`生於憂患，死於安樂`],h:`上一句以「天子」收尾，下一句以「天子」起頭。`,e:`「...見天子，天子坐...」首尾相接環環相扣，為典型頂真（聯珠）格。`},r),(t,n,r,i=`medium`)=>e({q:`「大漠孤煙直，長河落日圓。」王維這兩句塞外寫景詩堪稱千古名句，其對偶特色為：`,c:`大漠對長河，孤煙對落日，直對圓，意境雄渾精確對稱`,d:[`上下句皆為動詞開頭`,`採用流水對之因果銜接`,`以虛字對襯實字`],h:`名詞對名詞、形容詞對形容詞，空間構圖極其對稱。`,e:`空間由廣袤沙漠對長河奔流，孤煙垂直向上對落日圓融沈墜，對偶工整雄渾。`},r),(t,n,r,i=`medium`)=>e({q:`「寄蜉蝣於天地，渺滄海之一粟。」蘇軾《赤壁賦》在此運用的修辭手法為：`,c:`對偶、譬喻與極致之微渺誇飾映襯`,d:[`頂真與借代`,`設問與雙關`,`層遞與回文`],h:`蜉蝣比生命之短暫，一粟比身軀之渺小，與天地滄海形成強烈對照。`,e:`以蜉蝣與米粒為喻，將個人之渺小短暫與天地自然之無窮浩瀚形成深刻映襯。`},r),(t,n,r,i=`medium`)=>e({q:`「沉舟側畔千帆過，病樹前頭萬木春。」劉禹錫此聯詩句展現之意境為：`,c:`以翻覆沉舟與枯萎病樹映襯千帆競發與萬木爭春，寓意新事物終將取代舊事物`,d:[`抒發遭逢貶謫後意志消沉怨天尤人之悲傷情懷`,`警告後人航船必須謹慎切莫翻覆之航海須知`,`純粹描摹江邊春天樹木茂密花草盛開之寫實自然風貌`],h:`沉舟對千帆，病樹對萬木春。`,e:`以枯敗反襯新生，展示歷史新陳代謝與個人自強不息之豁達哲思。`},r),(t,n,r,i=`medium`)=>e({q:`「三個臭皮匠，勝過一個諸葛亮。」這句俗諺在修辭結構上屬於：`,c:`映襯與借代`,d:[`頂真與排比`,`雙關與倒裝`,`互文與設問`],h:`臭皮匠對比諸葛亮，且諸葛亮借代智囊謀士。`,e:`以三個平凡人對照絕世智者，並以歷史名人諸葛亮借代智慧之化身。`},r),(t,n,r,i=`medium`)=>e({q:`下列關於修辭判斷，何者敘述「完全正確」？`,c:`「感時花濺淚，恨別鳥驚心」結合了擬人與對偶修辭`,d:[`「三人行，必有我師焉」是標準的明喻修辭`,`「問君能有幾多愁」是激問修辭`,`「千里之行，始於足下」是頂真修辭`],h:`花濺淚、鳥驚心將花鳥人格化，且兩句工整對偶。`,e:`杜甫將山河動盪之憂傷投射於自然萬物，花能流淚、鳥亦驚心，屬擬人，且律詩頷聯嚴謹對偶。`},r),(t,n,r,i=`medium`)=>e({q:`「這場突如其來的強烈颱風登陸，首當其衝的東部沿海地區遭受重創。」句中「首當其衝」意指：`,c:`最先受到攻擊或遭遇災難的要衝位置`,d:[`第一個獲得救援與補助的地區`,`最勇猛主動向前衝鋒的隊伍`,`帶頭引發災難事件的核心禍首`],h:`當為承受，衝為交通要道。`,e:`「首當其衝」比喻最先受到攻擊、災難或蒙受衝擊，並非指帶頭衝鋒。`},r),(t,n,r,i=`medium`)=>e({q:`下列文句中成語的使用，何者「最恰當」？`,c:`這份報告雖然稱不上完美，但結構完整，表現尚屬「差強人意」`,d:[`他仗著家裡有錢，在學校橫行霸道，真是「差強人意」`,`這部電影劇情無聊至極，簡直「差強人意」，令人想離席`,`他的數學成績不及格，真是「差強人意」`],h:`差強人意為勉強令人滿意，非極差之意。`,e:`「差強人意」原指尚能振奮人心，後引申為大體上還能使人滿意，不可用來形容極差。`},r),(t,n,r,i=`medium`)=>e({q:`「炙手可熱」一詞常用於形容：`,c:`氣焰極盛、權勢顯赫或事物極受歡迎`,d:[`天氣酷熱令人難以忍受`,`雙手被沸水燙傷疼痛`,`市場商品滯銷乏人問津`],h:`手一摸就覺得熱，形容氣焰高盛。`,e:`杜甫《麗人行》：「炙手可熱勢絕倫，慎莫近前丞相嗔。」形容權勢烜赫氣焰囂張。`},r),(t,n,r,i=`medium`)=>e({q:`下列各句關於「美輪美奐」之使用，何者完全正確？`,c:`這座新建的國家歌劇院建築宏偉，室內裝潢「美輪美奐」`,d:[`她今天穿著一襲「美輪美奐」的晚禮服出席晚宴`,`他的文章辭藻華麗，意境深遠，真是「美輪美奐」`,`這幅水墨畫筆觸細膩，可謂「美輪美奐」之作`],h:`美輪美奐專門用於形容房屋建築高大華美。`,e:`「美輪美奐」輪為高大，奐為眾多華麗，形容房屋高大華美，不可用於服裝、文章或繪畫。`},r),(t,n,r,i=`medium`)=>e({q:`「這件微雕藝術品在米粒大小的象牙上刻出整部詩經，真是＿＿＿＿。」應填入：`,c:`巧奪天工`,d:[`鬼斧神差`,`回天乏術`,`空前絕後`],h:`人工技藝巧妙勝過天然造化。`,e:`「巧奪天工」形容人工手藝極其精巧勝過天然，專用於人工製品，不可形容自然景觀。`},r),(t,n,r,i=`medium`)=>e({q:`「在科技發達的今天，使用智慧型手機視訊通話已經是＿＿＿＿的事了。」空格應填：`,c:`司空見慣`,d:[`無獨有偶`,`首屈一指`,`炙手可熱`],h:`看慣了就不覺得奇怪。`,e:`「司空見慣」形容看慣了的事物不足為奇。`},r),(t,n,r,i=`medium`)=>e({q:`「空穴來風」在成語典故之原義與現代語境中，最精確的理解為：`,c:`有孔穴才會引來微風，比喻傳聞事出有因、並非完全無據`,d:[`指毫無任何事實依據憑空捏造的謠言`,`形容微風穿過窗戶讓人感到涼爽`,`形容室內通風良好空間寬敞`],h:`出自宋玉《風賦》：「臣聞於師：枳句來巢，空穴來風。」`,e:`「空穴來風」古義指事出有因；現代亦常借用比喻流言傳播必有其起因。`},r),(t,n,r,i=`medium`)=>e({q:`「他研讀古典文獻數十年，如今在訓詁學的造詣已達＿＿＿＿的境界。」應填入：`,c:`登堂入室`,d:[`不求甚解`,`步步為營`,`引狼入室`],h:`登上廳堂進入內室，比喻學問深奧精湛。`,e:`孔子評子路：「由也升堂矣，未入於室也。」後以「登堂入室」比喻學問技藝達到精深境界。`},r),(t,n,r,i=`medium`)=>e({q:`《莊子·養生主》中「庖丁解牛」的故事中，庖丁「目無全牛」之境界是指：`,c:`技藝極其純熟神妙，對牛隻身體內部結構了然於胸`,d:[`眼力衰退視力模糊，看不清楚整頭牛的形貌`,`眼中只有局部牛肉，缺乏整體大局觀`,`宰殺牛隻過多而感到厭煩`],h:`技藝高超，神遇而不以目視。`,e:`「目無全牛」形容技藝精湛純熟到了神化境界，並非指目光狹隘短淺。`},r),(t,n,r,i=`medium`)=>e({q:`「汗牛充棟」一詞用來形容：`,c:`藏書極其豐富繁多`,d:[`牛隻耕田極其辛勞汗流浹背`,`房屋建築極為宏偉廣闊`,`農夫耕作十分忙碌`],h:`搬運時牛累得出汗，存放時堆滿屋棟。`,e:`唐代柳宗元形容書籍極多：「處則充棟宇，出則汗牛馬。」後以「汗牛充棟」形容藏書極富。`},r),(t,n,r,i=`medium`)=>e({q:`「胸有成竹」這則成語源自北宋畫家文同畫竹之典故，其核心意涵為：`,c:`在做事之前心中已有完整周密的謀劃與把握`,d:[`在胸口刺青畫上竹子圖樣`,`喜愛在竹林中散步沉思`,`性格如竹子般堅毅正直`],h:`蘇軾記文同畫竹：「畫竹必先得成竹於胸中。」`,e:`「胸有成竹」比喻行事之前已胸有定見、籌劃周密。`},r),(t,n,r,i=`medium`)=>e({q:`春秋時期越王勾踐戰敗後「臥薪嚐膽」，其行為展現的意志情操是：`,c:`刻苦自勵，奮發圖強，誓雪國恥`,d:[`追求簡樸清苦的隱居生活`,`品嚐苦膽以治療身體頑疾`,`自我虐待以博取敵國同情`],h:`睡在柴草上，吃飯前嚐苦膽。`,e:`勾踐臥薪嚐膽比喻刻苦自勵、雪恥復仇之堅忍毅力。`},r),(t,n,r,i=`medium`)=>e({q:`藺相如奉命攜和氏璧出使強秦，面對秦王傲慢巧取，最終「完璧歸趙」，展現了：`,c:`臨危不懼的大智大勇與堅守國格之忠誠信義`,d:[`強大的軍事武力威懾對手`,`善於經商討價還價之商人本色`,`暗中勾結秦國大臣的權術手腕`],h:`完璧歸趙展現卓越外交智慧與浩然正氣。`,e:`藺相如以身相許護衛國寶，展現出不畏強暴、維護國家尊嚴之崇高氣節。`},r),(t,n,r,i=`medium`)=>e({q:`廉頗明白自己器量狹小後，袒露上身背負荊條親赴藺相如府上謝罪，此典故稱為：`,c:`負荊請罪`,d:[`倒屣相迎`,`程門立雪`,`三顧茅廬`],h:`背負荊杖請求責罰。`,e:`「負荊請罪」形容主動向對方承認過失並誠懇請求責罰寬恕。`},r),(t,n,r,i=`medium`)=>e({q:`楚漢相爭垓下之戰中，項羽軍隊被漢軍重重包圍，夜聞「四面楚歌」，其意境為：`,c:`四面受敵，孤立無援，陷入絕境`,d:[`楚國音樂優美動聽震撼人心`,`楚地將士思念家鄉引吭高歌`,`漢軍邀請楚軍和平聯歡談判`],h:`漢軍夜唱楚歌以瓦解楚軍鬥志。`,e:`「四面楚歌」比喻四面受敵、孤立無援、陷入徹底困境。`},r),(t,n,r,i=`medium`)=>e({q:`「杯弓蛇影」這則成語告誡人們：`,c:`切勿因疑心生暗鬼而自相驚擾恐懼`,d:[`飲酒時必須仔細檢查杯中有無毒蛇`,`射箭打獵必須具備良好視力`,`牆壁上掛弓箭容易引起意外傷害`],h:`酒杯映照牆上弓影誤以為蛇。`,e:`「杯弓蛇影」比喻因無端猜疑妄想而引起虛驚恐慌。`},r),(t,n,r,i=`medium`)=>e({q:`「掩耳盜鈴」的故事諷刺了何種愚蠢心態？`,c:`自欺欺人，以為自己聽不見別人也就不知道`,d:[`盜竊寺廟鐘鈴的貪婪小偷`,`耳根太軟容易聽信謠言者`,`保護聽力切莫靠近喧鬧鐘聲`],h:`摀住自己的耳朵去偷銅鐘。`,e:`「掩耳盜鈴」比喻自欺欺人，瞞得過自己卻瞞不過天下人。`},r),(t,n,r,i=`medium`)=>e({q:`曹操率軍行軍途中士兵乾渴難耐，乃傳令「前方有大片梅林」，此舉稱為：`,c:`望梅止渴`,d:[`緣木求魚`,`畫餅充飢`,`投桃報李`],h:`想到酸梅口中生津以解渴。`,e:`「望梅止渴」比喻藉由空想或虛妄的願景來安慰自己解除困頓。`},r),(t,n,r,i=`medium`)=>e({q:`「守株待兔」的寓言故事主要批判何種行為？`,c:`不知變通，妄想不勞而獲或死守偶然經驗`,d:[`獵捕野生動物破壞自然生態`,`農夫辛勤耕作值得同情讚賞`,`兔子奔跑速度過快容易撞樹`],h:`宋國農夫守在樹樁旁等待兔子撞死。`,e:`韓非子以此寓言批判墨守陳規、妄圖僥倖不勞而獲的保守思想。`},r),(t,n,r,i=`medium`)=>e({q:`「畫蛇添足」這則成語警惕人們在處事時應：`,c:`恰到好處，切忌節外生枝反而弄巧成拙`,d:[`注重細節追求十全十美`,`繪畫動物必須符合解剖構造`,`多展現才藝爭取更多美酒獎賞`],h:`給蛇畫上腳反而失去原先贏得的美酒。`,e:`「畫蛇添足」比喻多此一舉，不僅無益反而敗事。`},r),(t,n,r,i=`medium`)=>e({q:`戰國時燕國壽陵少年盲目模仿邯鄲人走路，結果「邯鄲學步」導致：`,c:`未學成新本領，反而忘記了自己原有的步法，爬著回去`,d:[`成為名滿天下的舞蹈大家`,`開創了全新的行进步調引領風潮`,`被邯鄲百姓推舉為領袖`],h:`未得其術，又忘其故態。`,e:`「邯鄲學步」比喻模仿他人不成，反而喪失自己原有的本領或特色。`},r),(t,n,r,i=`medium`)=>e({q:`西施心痛捧心而顰，村中醜女東施見而效之，其結果「東施效顰」比喻：`,c:`盲目模仿他人長處反而顯得醜陋可笑`,d:[`同情弱者共同承擔病痛`,`古代女子愛好追求流行妝容`,`長相醜陋者不宜在公眾場合出現`],h:`醜女模仿美女皺眉，鄰里閉門不納。`,e:`「東施效顰」比喻不顧自身條件而盲目胡亂模仿，適得其反。`},r),(t,n,r,i=`medium`)=>e({q:`楚人過江掉劍於水，遂於船舷刻記「刻舟求劍」，此舉荒謬之處在於：`,c:`船已行進而劍落水底未動，忽視客觀情況早已隨時間改變`,d:[`寶劍掉入水中無法被撈起`,`刻劃船舷損壞了渡船木質結構`,`雕刻記號太小容易辨識不清`],h:`舟已行矣，而劍不行。`,e:`「刻舟求劍」比喻死守僵化教條，不曉得形勢變化而不知變通。`},r),(t,n,r,i=`medium`)=>e({q:`楚人持珠寶至鄭國販賣，以名貴木盒裝飾寶珠，鄭人買下木盒卻退還珠寶，此為：`,c:`買櫝還珠`,d:[`畫蛇添足`,`削足適履`,`南轅北轍`],h:`櫝為精美木匣，珠為核心珍寶。`,e:`「買櫝還珠」比喻取捨不當，抓住了次要表象卻拋棄了核心根本。`},r),(t,n,r,i=`medium`)=>e({q:`「杞人憂天」這則列子寓言諷刺的是：`,c:`缺乏根據、毫無必要的庸人自擾與過度擔憂`,d:[`古代天文學家具有前瞻視野`,`關注大自然環境變遷的高尚情操`,`缺乏避難掩體設施的無奈感嘆`],h:`杞國人擔心天塌下來地陷下去。`,e:`「杞人憂天」比喻缺乏事實依據、毫無必要的無端憂慮。`},r),(t,n,r,i=`medium`)=>e({q:`狐狸走在老虎前面，野獸見皆奔逃，此「狐假虎威」的寓意是：`,c:`倚仗別人的權勢名望來作威作福、恐嚇欺壓他人`,d:[`動物界弱肉強食生態平衡法則`,`聰明智慧往往能戰勝強大蠻力`,`野生動物互助合作共同生存`],h:`狐借老虎的威風震懾百獸。`,e:`「狐假虎威」比喻憑藉強大有勢力者的權威來逞威風欺壓弱小。`},r),(t,n,r,i=`medium`)=>e({q:`「愚公移山」的典故主要頌揚何種精神品格？`,c:`堅持不懈、持之以恆、不畏艱難險阻的鋼鐵毅力`,d:[`破壞自然山林地貌以謀發展`,`盲目行事缺乏科學規劃工期`,`依靠神仙奇蹟降臨解決困難`],h:`子子孫孫無窮匱也，而山不加增。`,e:`「愚公移山」比喻只要立定志向、持之以恆不懈努力，終能克服萬難達成目標。`},r),(t,n,r,i=`medium`)=>e({q:`「精衛填海」中炎帝少女化為精衛鳥，常銜西山木石填塞東海，展現了：`,c:`不屈不撓、寧死不屈、與命運抗爭到底之悲壯意志`,d:[`熱愛鳥類飛翔生活的純真童趣`,`古代水利工程圍海造陸之宏偉構想`,`無知妄動浪費生命之愚昧行徑`],h:`銜木石以填東海。`,e:`「精衛填海」象徵面對浩大災難依然堅持不屈抗爭、矢志不移的偉大意志。`},r),(t,n,r,i=`medium`)=>e({q:`「塞翁失馬，焉知非福」這則淮南子故事所闡述的人生哲理為：`,c:`世事禍福相倚、吉凶相生，處順境切莫驕縱，逢逆境不必沮喪`,d:[`遺失良馬必然能換來更多財富回報`,`邊境地區騎馬打仗危險性極高`,`養馬技術精湛者必然能逢凶化吉`],h:`失馬得駿馬，墮馬斷髀免兵役。`,e:`「塞翁失馬」說明禍福互為轉化之辯證哲理，勸勉人們保持豁達超然心態。`},r),(t,n,r,i=`medium`)=>e({q:`春秋時管仲與鮑叔牙經商共事，鮑叔牙深知管仲才能而處處包容禮讓，後世以＿＿＿＿稱頌知心摯友：`,c:`管鮑之交`,d:[`桃園結義`,`莫逆之交`,`刎頸之交`],h:`生我者父母，知我者鮑子也。`,e:`「管鮑之交」比喻彼此互相理解信任、歷久不衰、深厚純真之崇高友誼。`},r),(t,n,r,i=`medium`)=>e({q:`在傳統書信稱謂中，對他人謙稱「自己的父親」應使用下列何者？`,c:`家父`,d:[`令尊`,`尊翁`,`先考`],h:`家大舍小令他人，謙稱自己長輩用「家」。`,e:`對他人稱自己的長輩用「家」（家父、家母）；稱對方的父親則用敬稱「令尊」。`},r),(t,n,r,i=`medium`)=>e({q:`對他人尊稱「對方的父親」，最適宜的書信敬詞為：`,c:`令尊`,d:[`家嚴`,`舍尊`,`先君`],h:`令為美好之意，用於稱呼他人親屬。`,e:`「令」為敬稱，用於對方親屬（令尊、令堂、令郎、令媛）。`},r),(t,n,r,i=`medium`)=>e({q:`書信中對他人謙稱「自己的母親」，應使用：`,c:`家母`,d:[`令堂`,`尊堂`,`先妣`],h:`父嚴母慈，謙稱自家長輩用家。`,e:`稱自己母親為家母、家慈；稱對方母親為令堂、尊堂；去世的母親為先妣。`},r),(t,n,r,i=`medium`)=>e({q:`書信中尊稱「對方的母親」，應使用下列何者？`,c:`令堂`,d:[`家慈`,`舍堂`,`太夫人`],h:`稱人母為令堂。`,e:`稱對方母親用敬語「令堂」或「令慈」。`},r),(t,n,r,i=`medium`)=>e({q:`對他人謙稱「自己的弟弟」，依據傳統禮儀應稱：`,c:`舍弟`,d:[`令弟`,`小弟`,`賢弟`],h:`舍用於輩分或年齡小於自己的平輩幼輩親屬。`,e:`「家大舍小」：稱己方平輩幼輩親屬用「舍」（舍弟、舍妹、舍姪）。`},r),(t,n,r,i=`medium`)=>e({q:`對他人稱呼「對方的兒子」，最適宜的尊稱用語為：`,c:`令郎`,d:[`小兒`,`犬子`,`豚兒`],h:`稱人子為令郎，稱己子為犬子。`,e:`稱對方兒子用敬語「令郎」；稱自己的兒子用謙詞「小兒」、「犬子」。`},r),(t,n,r,i=`medium`)=>e({q:`向他人介紹「自己的兒子」時，合乎傳統謙遜美德的稱呼為：`,c:`小兒`,d:[`令郎`,`貴公子`,`令胤`],h:`謙稱自己兒子用犬子或小兒。`,e:`古人謙稱自己兒子為「小兒」、「犬子」、「犬子愚鈍」。`},r),(t,n,r,i=`medium`)=>e({q:`稱呼「對方的女兒」，最適當的書信敬詞為：`,c:`令媛`,d:[`小女`,`息女`,`敝女`],h:`令媛、令千金為稱對方愛女之尊稱。`,e:`稱他人女兒為「令媛」、「令千金」；謙稱自己女兒為「小女」。`},r),(t,n,r,i=`medium`)=>e({q:`書信中晚輩寫給祖父母或父母親時，信首「提稱語」最適宜使用：`,c:`膝下`,d:[`道鑒`,`大鑒`,`鈞鑒`],h:`幼年時常在父母膝下承歡。`,e:`給父母、祖父母之書信提稱語專用「膝下」或「膝前」。`},r),(t,n,r,i=`medium`)=>e({q:`寫信給老師或長輩（如師長、長官），提稱語應使用下列何者？`,c:`函丈`,d:[`順誦`,`客氣`,`如晤`],h:`函丈為向老師請教距離丈餘以示尊崇。`,e:`給老師、長輩用「函丈」、「尊前」、「道席」；平輩朋友用「大鑒」、「道鑒」。`},r),(t,n,r,i=`medium`)=>e({q:`寫信給「平輩朋友」，最適當的書信提稱語為：`,c:`大鑒`,d:[`膝下`,`函丈`,`如晤`],h:`鑒為審閱之意，平輩互尊用大鑒、道鑒。`,e:`平輩朋友間書信提稱語通用「大鑒」、「道鑒」、「台鑒」。`},r),(t,n,r,i=`medium`)=>e({q:`長輩寫給「晚輩」的書信，提稱語應使用下列何者？`,c:`如晤`,d:[`膝下`,`大鑒`,`尊鑒`],h:`如晤意為如同當面會晤交談。`,e:`對晚輩書信提稱語用「如晤」、「青覽」、「知悉」。`},r),(t,n,r,i=`medium`)=>e({q:`在信封「啟封詞」中，絕對「不可」使用下列何者？`,c:`敬啟`,d:[`福啟`,`安啟`,`道啟`],h:`啟為開啟，不可命令收信人敬啟。`,e:`「啟」是請收信人開啟，若寫「敬啟」等於要求對方恭敬開啟，極為失禮；應用「賜啟」、「福啟」、「大啟」。`},r),(t,n,r,i=`medium`)=>e({q:`寫給「父母親或祖父母」之信封外表啟封詞，最適宜填寫：`,c:`福啟`,d:[`敬啟`,`台啟`,`收啟`],h:`為長輩祈求福祉安康。`,e:`給父母尊長信封啟封詞用「福啟」或「安啟」。`},r),(t,n,r,i=`medium`)=>e({q:`寫信給「平輩朋友」之信封啟封詞，最適宜使用的是：`,c:`大啟`,d:[`敬啟`,`福啟`,`賜啟`],h:`大啟表示對平輩之尊重展覽。`,e:`給平輩之啟封詞用「大啟」、「台啟」、「惠啟」。`},r),(t,n,r,i=`medium`)=>e({q:`寫信給「老師或文教界人士」，信封啟封詞最適宜使用：`,c:`道啟`,d:[`敬啟`,`福啟`,`收啟`],h:`道啟尊重對方傳道授業之尊嚴。`,e:`給教育界師長信封啟封詞專用「道啟」。`},r),(t,n,r,i=`medium`)=>e({q:`寫信給「晚輩」之信封啟封詞，最適宜填寫：`,c:`收啟`,d:[`大啟`,`福啟`,`道啟`],h:`長輩對晚輩直言拆收即可。`,e:`長輩對晚輩直接用「收啟」或「啟」。`},r),(t,n,r,i=`medium`)=>e({q:`晚輩在寫給父母的信末署名結尾敬語，最適宜使用：`,c:`叩上`,d:[`謹啟`,`頓首`,`手書`],h:`叩為叩拜，表達極致孝敬。`,e:`給父母祖父母信末自署應寫「兒某某 叩上」或「叩稟」。`},r),(t,n,r,i=`medium`)=>e({q:`寫信給「老師」時，信末結尾祝候語最適宜使用下列何者？`,c:`敬請 道安`,d:[`順祝 商祺`,`恭請 金安`,`順問 近好`],h:`祝福老師傳道授業安康。`,e:`祝老師用「道安」、「教安」；商界人士用「商祺」；長輩健康用「金安」。`},r),(t,n,r,i=`medium`)=>e({q:`商業往來書信之信末祝候敬語，最適宜使用：`,c:`順祝 商祺`,d:[`恭請 福安`,`敬請 道安`,`順祝 旅安`],h:`祺為吉祥，商祺祝生意興隆。`,e:`商業文書信件祝候語專用「商祺」、「籌安」、「商安」。`},r),(t,n,r,i=`medium`)=>e({q:`寫信給生病住院休養的親友時，最適當的慰問祝候語為：`,c:`敬祝 早日康安`,d:[`順祝 商祺`,`敬請 教安`,`恭賀 新禧`],h:`祝賀身體早日康復健康。`,e:`探病慰問書信用「早日康安」、「病體早癒」。`},r),(t,n,r,i=`medium`)=>e({q:`信封上的收件人稱謂（如「某某某 先生」），是寫給誰看的？`,c:`寫給郵差送信員看的，指明送信對象的社會身分`,d:[`寫給收信人看的，表示對收信人的極度崇敬`,`寫給收信人家屬看的，避免其他人拆閱`,`純粹裝飾字句，無實質功能`],h:`信封是外表公文傳遞媒介，稱謂指涉的是收件人在社會上的身分。`,e:`信封收件人名下的稱謂（如先生、教授、經理）是給郵政投遞人員看的，故不可寫「家父收」或「某某叔叔收」。`},r),(t,n,r,i=`medium`)=>e({q:`寄信給自己的老師「李明德」，信封正中央收件人姓名書寫何者最正確？`,c:`李明德 老師 道啟`,d:[`李老師明德 敬啟`,`恩師李明德 膝下福啟`,`李明德 吾師收啟`],h:`不可在信封寫恩師、敬啟。`,e:`信封為郵務公開資訊，應寫姓名加社會通稱加啟封詞（如「李明德 老師 道啟」）。`},r),(t,n,r,i=`medium`)=>e({q:`書信中提及「已故的父親」，依禮節應稱呼為：`,c:`先父`,d:[`家父`,`尊翁`,`先妣`],h:`先表示已逝世長輩，考為父。`,e:`稱已故父親為「先父」、「先嚴」、「先考」；「家父」為健在之稱呼。`},r),(t,n,r,i=`medium`)=>e({q:`書信中提及「已故的母親」，依禮節應稱呼為：`,c:`先母`,d:[`家慈`,`令堂`,`先考`],h:`妣為已故母親。`,e:`稱已逝母親為「先母」、「先慈」、「先妣」。`},r),(t,n,r,i=`medium`)=>e({q:`在柬帖（請帖）中，新郎父親具名邀請賓客參加婚宴，婚禮稱謂應寫：`,c:`長男結婚，小女出閣`,d:[`小女結婚，長男出閣`,`長男于歸，小女于歸`,`小兒完聚，長女迎娶`],h:`男婚稱娶婦完聚，女婚稱出閣、于歸。`,e:`男方娶媳婦為長男完婚、成婚；女方嫁女兒稱為出閣、于歸。`},r),(t,n,r,i=`medium`)=>e({q:`「謹訂於民國某年某月某日...敬備薄酒，恭請 闔第光臨。」此種傳統請帖稱為：`,c:`柬帖`,d:[`便條`,`公文宣導表`,`訃聞通知書`],h:`光臨為邀請闔家到訪之喜帖用語。`,e:`傳統禮儀中宴客聚會所發出的正式書面邀請文件統稱為柬帖。`},r),(t,n,r,i=`medium`)=>e({q:`在正式書信中，當提到對方尊長或自身長輩時換行抬頭書寫，此格式稱為：`,c:`挪抬或平抬`,d:[`段首縮排兩字`,`下移一格降低行首`,`全文加註雙底線`],h:`抬頭為古代書信展現敬意之重要規範。`,e:`書信中提及受信人尊稱時，平抬（另起新行頂格）或挪抬（空一格）為古典敬語禮節。`},r),(t,n,r,i=`medium`)=>e({q:`下列哪一種書信信末署名用語屬於「平輩之間」通用？`,c:`某某 手書`,d:[`某某 叩稟`,`某某 侍讀`,`某某 俯首`],h:`頓首、手書為平輩交往禮節。`,e:`平輩朋友間簽名可用「某某 敬啟」、「某某 頓首」、「某某 手書」。`},r),(t,n,r,i=`medium`)=>e({q:`便條是書信的簡化形式，下列關於便條的敘述何者「錯誤」？`,c:`便條可用於向長官或德高望重之師長正式請託大事`,d:[`便條字數簡明扼要，無須繁瑣抬頭敬語`,`便條通常不加信封，直接折疊留置於案頭`,`便條適用於平輩或晚輩之間傳遞日常簡便訊息`],h:`正式大事不可使用隨意便條，極失莊重禮貌。`,e:`便條適用於平輩好友或家人晚輩留言，不宜用於正式嚴肅場合或向長輩尊長請託要事。`},r),(t,n,r,i=`medium`)=>e({q:`慶祝新婚大喜的祝賀題辭，下列何者「最為恰當」？`,c:`百年好合、宜室宜家`,d:[`齒德俱增`,`妙手回春`,`駕鶴西歸`],h:`祝賀夫妻新婚美滿。`,e:`「百年好合」、「宜室宜家」、「鳳凰于飛」皆為慶賀男女新婚之標準題辭。`},r),(t,n,r,i=`medium`)=>e({q:`下列哪一題辭專門用於祝賀「女性長者做壽」？`,c:`萱堂日永`,d:[`椿萱並茂`,`南山之壽`,`弄璋誌喜`],h:`古代以萱草代指母親。`,e:`「萱堂日永」、「懿德長昭」專祝女壽；「松柏長青」、「福如東海」祝男壽；「椿萱並茂」父母雙全。`},r),(t,n,r,i=`medium`)=>e({q:`朋友喜獲「千金」（生女兒），送上牌匾或紅包題辭應書寫：`,c:`弄瓦誌喜`,d:[`弄璋之喜`,`德業長昭`,`近悅遠來`],h:`古代紡織磚瓦瓦紡錘象徵女子紡織勤勞。`,e:`生女稱為「弄瓦之喜」、「明珠入掌」；生男稱為「弄璋之喜」。`},r),(t,n,r,i=`medium`)=>e({q:`親友喜迎「麟兒」（生兒子），祝賀題辭最適宜使用：`,c:`弄璋誌喜`,d:[`弄瓦誌喜`,`宜室宜家`,`美輪美奐`],h:`璋為玉器，象徵男兒如玉品德高潔。`,e:`古人祝賀生男孩用「弄璋之喜」、「熊夢徵祥」、「麟趾呈祥」。`},r),(t,n,r,i=`medium`)=>e({q:`恭賀新店開幕、公司開張營業，最適宜的題辭為：`,c:`近悅遠來、駿業宏發`,d:[`造福桑梓`,`桃李滿門`,`椿萱並茂`],h:`形容商業繁榮顧客自遠方慕名而來。`,e:`賀開店經商用「近悅遠來」、「駿業宏發」、「大展鴻圖」、「生財有道」。`},r),(t,n,r,i=`medium`)=>e({q:`祝賀親友「新居落成、喬遷之喜」，最適宜的題辭為：`,c:`美輪美奐、良禽擇木`,d:[`杏林春暖`,`懸壺濟世`,`駕鶴西歸`],h:`形容新屋高大壯麗裝潢精美。`,e:`賀新居落成喬遷用「美輪美奐」、「喬遷之喜」、「堂構增輝」。`},r),(t,n,r,i=`medium`)=>e({q:`送給「醫術精湛、仁心仁術之醫師」的祝賀感謝題辭為：`,c:`妙手回春、懸壺濟世`,d:[`桃李滿天下`,`木鐸長鳴`,`德厚流光`],h:`古代醫師行醫懸掛葫蘆裝藥。`,e:`醫界專用題辭：「懸壺濟世」、「杏林春暖」、「妙手回春」、「仁心仁術」。`},r),(t,n,r,i=`medium`)=>e({q:`學生感謝「恩師多年辛勤培育教導」，贈送牌匾最適宜書寫：`,c:`桃李滿門、立德樹人`,d:[`近悅遠來`,`百年好合`,`壽比南山`],h:`桃李象徵優秀門生學子。`,e:`教育界專用題辭：「桃李滿天下」、「木鐸長鳴」、「師恩浩蕩」、「化育英才」。`},r),(t,n,r,i=`medium`)=>e({q:`祝賀朋友在「演講比賽或辯論大賽中榮獲冠軍」，題辭應寫：`,c:`舌燦蓮花、滔滔不絕`,d:[`步步高升`,`積善餘慶`,`福壽全歸`],h:`形容口才極佳雄辯滔滔。`,e:`演講辯論比賽賀辭：「舌燦蓮花」、「辯才無礙」、「妙語連珠」。`},r),(t,n,r,i=`medium`)=>e({q:`祝賀「歌唱比賽奪冠或音樂演奏會成功」，最適當之題辭為：`,c:`響遏行雲、天籟之音`,d:[`鐵畫銀鉤`,`妙筆生花`,`杏林春暖`],h:`歌聲嘹亮使行雲駐足。`,e:`音樂歌唱專用題辭：「天籟之音」、「響遏行雲」、「繞樑三日」、「聲動梁塵」。`},r),(t,n,r,i=`medium`)=>e({q:`祝賀「書法比賽榮獲特優首獎」，最適宜之題辭為：`,c:`鐵畫銀鉤、龍飛鳳舞`,d:[`舌燦蓮花`,`近悅遠來`,`宜室宜家`],h:`形容毛筆字筆力遒勁姿態靈動。`,e:`書法專用題辭：「鐵畫銀鉤」、「字字珠璣」、「筆走龍蛇」、「入木三分」。`},r),(t,n,r,i=`medium`)=>e({q:`恭賀「當選民意代表（立法委員、市議員）」之祝賀題辭為：`,c:`民意喉舌、造福桑梓`,d:[`杏林春滿`,`弄璋誌喜`,`作育英才`],h:`為人民權益發聲代民立言。`,e:`政界當選題辭：「造福桑梓」、「民意喉舌」、「眾望所歸」、「造福民群」。`},r),(t,n,r,i=`medium`)=>e({q:`參加「德高望重之高齡男性長者」喪禮，哀輓題辭最適宜使用：`,c:`德望常昭、福壽全歸`,d:[`母儀足式`,`音容宛在`,`萱草長青`],h:`男子高壽逝世福壽雙全。`,e:`輓男喪用「福壽全歸」、「德業長昭」、「南極星沉」；輓女喪用「母儀足式」、「懿德長昭」。`},r),(t,n,r,i=`medium`)=>e({q:`參加「年長慈祥母親」之喪禮，靈堂橫匾輓聯題辭應書寫：`,c:`母儀足式、懿德長昭`,d:[`福壽全歸`,`痛失知音`,`大德必壽`],h:`母儀為做母親的崇高榜樣規範。`,e:`女喪哀輓專用詞：「母儀足式」、「懿德永昭」、「慈範長存」。`},r),(t,n,r,i=`medium`)=>e({q:`輓「年輕未婚女性或青年早逝」，哀悼題辭最適宜使用：`,c:`蘭摧玉折、香消玉殞`,d:[`齒德俱尊`,`老成凋謝`,`大德必壽`],h:`形容年輕才女早逝令人痛惜。`,e:`哀輓年輕女性早夭用「香消玉殞」、「蘭摧玉折」；老年長者用「老成凋謝」。`},r),(t,n,r,i=`medium`)=>e({q:`「一聯名聯千古傳：天增歲月人增壽，春滿乾坤福滿門。」此聯屬於：`,c:`春聯`,d:[`行業聯`,`婚喜聯`,`輓聯`],h:`迎接新歲除舊布新。`,e:`描寫春臨大地、萬象更新、家門納福，為經典民間春聯。`},r),(t,n,r,i=`medium`)=>e({q:`「藏古今學術，聚天地精華。」這副行業對聯最適宜張貼於：`,c:`圖書館或書店`,d:[`藥局醫院`,`中式餐館`,`理髮店`],h:`典藏古今學術書籍。`,e:`蒐藏古今書籍與學術精華，專屬於圖書館、書店之行業聯。`},r),(t,n,r,i=`medium`)=>e({q:`「雖是毫髮微小事，卻關體面大文章。」這副妙趣橫生的行業聯形容的是：`,c:`理髮店`,d:[`服飾店`,`文具店`,`眼鏡行`],h:`毫髮即頭髮，修整頭髮關乎儀容體面。`,e:`巧用「毫髮」與「體面」，為理髮業最膾炙人口的經典妙聯。`},r),(t,n,r,i=`medium`)=>e({q:`「問天下頭顱幾許？看老夫手段如何！」此副豪氣干雲的對聯描寫的行業是：`,c:`理髮師`,d:[`劊子手`,`鐵匠鋪`,`當鋪`],h:`打理天下人之頭頂髮型。`,e:`古代傳統理髮匠之招牌對聯，展現剃頭理容之超絕手藝。`},r),(t,n,r,i=`medium`)=>e({q:`「但願世間人常健，何妨架上藥生塵。」這副對聯懸掛於中藥房，展現的胸襟是：`,c:`醫者仁心，寧願無人買藥也不願百姓受病痛折磨的崇高醫德`,d:[`藥鋪生意蕭條面臨倒閉之無奈自嘲`,`藥材質量優良保存長久不怕積塵`,`宣傳藥物療效顯著吃一劑即痊癒`],h:`期盼人人健康無病痛。`,e:`以「藥生塵」反襯世間百姓皆健康長壽，展現大醫精誠仁民愛物之崇高醫德。`},r),(t,n,r,i=`medium`)=>e({q:`「到來盡是彈冠客，去後皆成振衣人。」這副對聯最適合懸掛於：`,c:`浴室澡堂`,d:[`戲院劇場`,`公車站亭`,`咖啡館`],h:`彈冠振衣本義為洗浴整潔塵埃。`,e:`洗去一身塵埃清爽離去，為公共澡堂浴室之專屬對聯。`},r),(t,n,r,i=`medium`)=>e({q:`「小住為佳，且波波劫劫，做甚麼事？歇足且坐，喝一盞茶，莫慌莫忙。」最適宜貼在：`,c:`路旁茶亭或休息驛站`,d:[`學校圖書館`,`警察局報案室`,`急診室門口`],h:`勸遊人停下腳步喝茶休憩。`,e:`勸行路之人放慢步調歇息喝茶，為驛站路亭茶歇之專用楹聯。`},r),(t,n,r,i=`medium`)=>e({q:`傳統對聯在形式律法上，要求「上聯末字」與「下聯末字」之平仄規律應為：`,c:`上聯末字必為仄聲，下聯末字必為平聲`,d:[`上聯末字必為平聲，下聯末字必為仄聲`,`上下聯末字皆可任意使用平聲`,`上下聯末字皆必須為仄聲押韻`],h:`仄起平收為傳統對聯千古鐵律。`,e:`對聯最嚴謹之格律：上聯末字必須收仄聲（上、去、入聲），下聯末字必須收平聲（陰平、陽平）。`},r),(t,n,r,i=`medium`)=>e({q:`「水淡水濃全是水，山高山下總是山。」這副對聯運用的修辭手法為：`,c:`頂真與反覆修辭`,d:[`層遞修辭`,`借代修辭`,`誇飾修辭`],h:`水與山字一再出現反覆詠唱。`,e:`透過同字反覆重疊，形成悠揚迴旋之語音音韻美感。`},r),(t,n,r,i=`medium`)=>e({q:`「大肚能容，容天下難容之事；開口便笑，笑世間可笑之人。」此聯題詠的佛門人物為：`,c:`彌勒佛`,d:[`觀世音菩薩`,`地藏王菩薩`,`文殊菩薩`],h:`大肚能容、笑口常開。`,e:`描摹彌勒菩薩大肚能容與笑看人間百態之豁達慈悲。`},r),(t,n,r,i=`medium`)=>e({q:`「世味釀成杜康酒，天機參透落霞篇。」這副對聯最適宜送給：`,c:`釀酒作坊或文人書房`,d:[`西式烘焙麵包店`,`現代牙醫診所`,`二手汽車拍賣場`],h:`杜康代酒，落霞篇代文章。`,e:`杜康指美酒，落霞出王勃滕王閣序，兼具酒香與文采之意境。`},r),(t,n,r,i=`medium`)=>e({q:`「有容德乃大，無欲心自剛。」林則徐書房懸掛之自勉聯，展現的修養為：`,c:`寬廣包容之胸懷與廉潔正直之浩然氣節`,d:[`追求道家避世歸隱田園無欲無求`,`經商致富善於累積財富資本`,`文武全才領軍打仗開疆闢土`],h:`寬宏包容與克制私欲清正自重。`,e:`以寬大胸懷包容天下，以清正無私抵禦誘惑，為林則徐名震天下之座右銘。`},r),(t,n,r,i=`medium`)=>e({q:`「剛正不阿，留得正氣衝霄漢；幽愁發憤，著成信史照塵寰。」題詠的歷史人物為：`,c:`司馬遷`,d:[`屈原`,`文天祥`,`岳飛`],h:`發憤著信史，照耀塵世人間。`,e:`「幽愁發憤，著成信史」指司馬遷遭宮刑後發憤著述千古絕唱《史記》。`},r),(t,n,r,i=`medium`)=>e({q:`「鐵板銅琶，繼東坡高唱大江東去；美芹悲黍，冀南宋莫隨鴻雁南飛。」題詠的文學家為：`,c:`辛棄疾`,d:[`李清照`,`陸游`,`柳永`],h:`大江東去繼東坡豪放，美芹十論獻抗金大計。`,e:`東坡之後豪放詞宗辛棄疾，曾獻《美芹十論》力主抗金北伐收復中原。`},r),(t,n,r,i=`medium`)=>e({q:`「世上瘡痍，詩中聖哲；民間疾苦，筆底波瀾。」郭沫若題於成都草堂，讚頌的是：`,c:`杜甫`,d:[`李白`,`王維`,`白居易`],h:`詩中聖哲即詩聖。`,e:`杜甫詩作被譽為「詩史」，以筆底波瀾記錄世間瘡痍疾苦，為千古詩聖。`},r),(t,n,r,i=`medium`)=>e({q:`古代稱男子滿「二十歲」舉行加冠成年禮，稱為：`,c:`弱冠之年`,d:[`而立之年`,`及笄之年`,`志學之年`],h:`二十歲體猶未壯，故稱弱，戴冠成年稱冠。`,e:`《禮記》：「二十曰弱，冠。」古代男子滿二十歲行加冠之禮，稱弱冠。`},r),(t,n,r,i=`medium`)=>e({q:`女子滿「十五歲」束髮插簪象徵成年許嫁，稱為：`,c:`及笄之年`,d:[`豆蔻年華`,`破瓜之年`,`花信之年`],h:`笄為盤髮固定髮型的簪子。`,e:`古代女子滿十五歲行笄禮，結髮插簪，稱為「及笄之年」。`},r),(t,n,r,i=`medium`)=>e({q:`孔子《論語·為政》自述其人生修養歷程：「三十而＿＿，四十而＿＿。」空格依序應填：`,c:`立 ／ 不惑`,d:[`惑 ／ 立`,`志 ／ 順`,`知命 ／ 耳順`],h:`三十歲自立立定志向，四十歲通達不被迷惑。`,e:`孔子曰：「吾十有五而志於學，三十而立，四十而不惑，五十而知天命，六十而耳順，七十而從心所欲不踰矩。」`},r),(t,n,r,i=`medium`)=>e({q:`古代稱男子「五十歲」為：`,c:`知天命之年`,d:[`花甲之年`,`耳順之年`,`古稀之年`],h:`知道上天賦予自己的使命與命運規律。`,e:`源自《論語》「五十而知天命」，故稱五十歲為知天命之年。`},r),(t,n,r,i=`medium`)=>e({q:`「六十歲」老人滿一甲子循環，在古代雅稱為：`,c:`花甲之年`,d:[`古稀之年`,`期頤之年`,`知命之年`],h:`天干地支相配六十載為一甲子。`,e:`天干地支組合滿六十年稱為一甲子，亦稱「花甲」，孔子六十而耳順。`},r),(t,n,r,i=`medium`)=>e({q:`杜甫《曲江二首》「人生七十古來稀」，後世遂以何者代指「七十歲」？`,c:`古稀之年`,d:[`花甲之年`,`期頤之年`,`杖朝之年`],h:`七十歲自古以來稀少長壽。`,e:`源自杜甫名句「人生七十古來稀」，故稱七十歲為古稀。`},r),(t,n,r,i=`medium`)=>e({q:`古代稱「一百歲」高齡之長壽老人為：`,c:`期頤之年`,d:[`古稀之年`,`花甲之年`,`耄耋之年`],h:`百年曰期，需要人奉養頤養。`,e:`《禮記》：「百年曰期，頤。」指百歲老人飲食起居需人侍奉頤養。`},r),(t,n,r,i=`medium`)=>e({q:`形容幼童「童年天真爛漫」時期，常以其頭髮自然下垂未束髮之特徵稱為：`,c:`垂髫之年`,d:[`束髮之年`,`弱冠之年`,`而立之年`],h:`幼兒頭髮下垂飄拂。`,e:`古代幼童不束髮，頭髮下垂稱為「垂髫」，亦扎兩角為「總角」，借代童年。`},r),(t,n,r,i=`medium`)=>e({q:`杜牧詩句「娉娉嫋嫋十三餘，豆蔻梢頭二月初」，後世以「豆蔻年華」形容女子：`,c:`十三、十四歲之少女時期`,d:[`十七、十八歲之新婚少婦`,`二十歲之盛裝女子`,`初生滿月之女嬰`],h:`豆蔻花初綻，比喻十三四歲稚嫩少女。`,e:`「豆蔻年華」專指女子十三、十四歲含苞待放之青春少女時代。`},r),(t,n,r,i=`medium`)=>e({q:`古代稱女子「十六歲」青春時期，常拆「二八十六」或拆「破瓜」字形稱為：`,c:`二八年華`,d:[`及笄之年`,`花信之年`,`知命之年`],h:`二乘以八等於十六。`,e:`二八十六，故稱女子十六歲為「二八年華」；「瓜」字可拆為兩個八，亦稱破瓜。`},r),(t,n,r,i=`medium`)=>e({q:`天干共有十個符號，地支共有十二個符號，其組合紀年「一甲子」共有幾年？`,c:`60 年`,d:[`12 年`,`100 年`,`120 年`],h:`10 與 12 之最小公倍數。`,e:`十天干與十二地支順序兩兩相配，最小公倍數為 60，故一輪為 60 年。`},r),(t,n,r,i=`medium`)=>e({q:`古代一日劃分為十二個時辰，每個時辰相當於現代的：`,c:`2 個小時`,d:[`1 個小時`,`4 個小時`,`30 分鐘`],h:`一天 24 小時除以 12 時辰。`,e:`古代十二時辰（子丑寅卯辰巳午未申酉戌亥），每一時辰對應現代 2 小時。`},r),(t,n,r,i=`medium`)=>e({q:`十二時辰中，「子時」所對應的現代精確時間為：`,c:`夜間 11:00 至 凌晨 1:00`,d:[`正午 11:00 至 下午 1:00`,`凌晨 1:00 至 凌晨 3:00`,`傍晚 5:00 至 晚間 7:00`],h:`子時為午夜交界之時。`,e:`子時對應 23:00 ~ 01:00，為一日之始；正午 11:00 ~ 13:00 則為「午時」。`},r),(t,n,r,i=`medium`)=>e({q:`十二時辰中的「午時」對應現代時間為何？`,c:`上午 11:00 至 下午 1:00`,d:[`夜間 11:00 至 凌晨 1:00`,`清晨 5:00 至 早上 7:00`,`下午 3:00 至 傍晚 5:00`],h:`日正當中為正午。`,e:`午時即 11:00 ~ 13:00，其中 12:00 整稱為「正午」。`},r),(t,n,r,i=`medium`)=>e({q:`古代打更報時，所謂「三更半夜」的「三更」相當於十二時辰中的：`,c:`子時`,d:[`戌時`,`亥時`,`丑時`],h:`一更戌、二更亥、三更子。`,e:`古代一夜分五更，一更戌（19-21），二更亥（21-23），三更子（23-01），故三更即子時。`},r),(t,n,r,i=`medium`)=>e({q:`天干地支與十二生肖相配，下列配對何者「完全正確」？`,c:`子鼠、丑牛、寅虎、卯兔`,d:[`辰蛇、巳龍、午羊、未馬`,`申雞、酉猴、戌豬、亥狗`,`子牛、丑鼠、寅兔、卯虎`],h:`子鼠丑牛寅虎卯兔辰龍巳蛇午馬未羊申猴酉雞戌狗亥豬。`,e:`十二地支與生肖順序：子鼠、丑牛、寅虎、卯兔、辰龍、巳蛇、午馬、未羊、申猴、酉雞、戌狗、亥豬。`},r),(t,n,r,i=`medium`)=>e({q:`農曆正月初一「春節」又稱元日、新正，傳統習俗不包括下列何者？`,c:`登高插茱萸`,d:[`燃放爆竹迎新春`,`晚輩向長輩拜年發壓歲錢`,`貼春聯換新桃符`],h:`九九重陽節才登高插茱萸。`,e:`九月九日重陽節習俗才是登高望遠、佩戴茱萸、飲菊花酒。`},r),(t,n,r,i=`medium`)=>e({q:`「清明時節雨紛紛，路上行人欲斷魂。」清明節的核心傳統習俗為：`,c:`掃墓祭祖、緬懷先人與踏青`,d:[`吃粽子賽龍舟`,`賞月吃月餅`,`猜燈謎鬧元宵`],h:`慎終追遠掃墓祭祀。`,e:`清明節是中華民族慎終追遠掃墓祭祖、春季踏青之重要傳統節日。`},r),(t,n,r,i=`medium`)=>e({q:`農曆五月初五「端午節」是為了紀念哪一位偉大歷史人物？`,c:`屈原`,d:[`介子推`,`伍子胥`,`曹娥`],h:`吃粽子、賽龍舟以紀念屈原。`,e:`端午節源於戰國楚國愛國詩人屈原忠而被讒、悲憤投汨羅江，百姓賽舟包粽以祭之。`},r),(t,n,r,i=`medium`)=>e({q:`農曆八月十五「中秋節」最具代表性的文化意象為：`,c:`月圓人團圓，家人相聚賞月吃月餅`,d:[`點天燈求平安`,`插柳枝驅邪除疫`,`戴香包驅逐五毒`],h:`八月十五夜月圓象徵人間美滿團聚。`,e:`中秋節以滿月象徵人間親情美滿團圓，主要習俗為賞月、吃月餅、話團聚。`},r),(t,n,r,i=`medium`)=>e({q:`「獨在異鄉為異客，每逢佳節倍思親。遙知兄弟登高處，遍插茱萸少一人。」王維此詩描寫的傳統節慶是：`,c:`重陽節`,d:[`中秋節`,`清明節`,`元宵節`],h:`登高、遍插茱萸為重陽節代表習俗。`,e:`農曆九月初九為重陽節，古人有登高避災、插茱萸、飲菊花酒之傳統習俗。`},r),(t,n,r,i=`medium`)=>e({q:`農曆正月十五日為「元宵節」，又稱為上元節，主要應景節慶活動為：`,c:`吃元宵、賞花燈、猜燈謎`,d:[`泛舟採蓮`,`龍舟競渡`,`登高飲酒`],h:`提燈籠賞花燈猜燈謎。`,e:`元宵節為新年第一個滿月之夜，傳統習俗吃湯圓元宵、張燈結綵、觀燈猜謎。`},r),(t,n,r,i=`medium`)=>e({q:`農曆七月初七夜「七夕節」，源自古代何種美麗神話傳說？`,c:`牛郎與織女鵲橋相會`,d:[`后羿射日與嫦娥奔月`,`白蛇傳水漫金山`,`梁山伯與祝英台化蝶`],h:`牛郎織女銀河相會之乞巧節。`,e:`七夕又名乞巧節，源於牽牛星與織女星一年一度由喜鵲搭橋相會之浪漫神話。`},r),(t,n,r,i=`medium`)=>e({q:`二十四節氣中，北半球「白天時間最長、夜晚最短」的一天是：`,c:`夏至`,d:[`冬至`,`春分`,`秋分`],h:`太陽直射北回歸線。`,e:`夏至當天太陽直射北回歸線，北半球白晝時間最長，正午太陽高度最高。`},r),(t,n,r,i=`medium`)=>e({q:`二十四節氣中，晝夜平分（白天與夜晚時間等長）的兩個節氣是：`,c:`春分 與 秋分`,d:[`立春 與 立秋`,`夏至 與 冬至`,`大寒 與 大暑`],h:`太陽直射赤道，全球晝夜均分。`,e:`春分與秋分太陽直射地球赤道，全球各地日夜各十二小時，晝夜均分。`},r),(t,n,r,i=`medium`)=>e({q:`民間傳統習俗在「冬至」這一天，家家戶戶習慣進食何種應景食物象徵添歲團圓？`,c:`吃湯圓`,d:[`吃潤餅割包`,`吃粽子`,`吃月餅`],h:`冬至吃湯圓長一歲。`,e:`民間有「冬至大如年，吃了湯圓長一歲」之習俗，吃冬至圓象徵圓滿添壽。`},r),(t,n,r,i=`medium`)=>e({q:`「千門萬戶曈曈日，總把新桃換舊符。」王安石《元日》詩描寫的時序節令是：`,c:`農曆新年除夕與春節大年初一`,d:[`端午節`,`中秋節`,`清明節`],h:`新桃換舊符為貼新春聯迎新年。`,e:`詩中元日即農曆大年初一，描繪百姓燃放爆竹、旭日普照、貼新桃符迎新歲之喜慶景象。`},r),(t,n,r,i=`medium`)=>e({q:`農曆除夕夜一家人齊聚守歲，吃年夜飯長年菜，其「長年菜」在臺灣民間通常採用：`,c:`芥菜`,d:[`小白菜`,`菠菜`,`苦瓜`],h:`菜葉長且微苦回甘象徵長壽。`,e:`除夕圍爐長年菜多用芥菜，整葉入口象徵長命百歲、延年益壽。`},r),(t,n,r,i=`medium`)=>e({q:`古人以二十四節氣指導農耕生活，春季的第一個節氣為：`,c:`立春`,d:[`雨水`,`驚蟄`,`春分`],h:`立代表季節開始。`,e:`二十四節氣以「立春」為首，代表冰雪融化、大地回春、新耕農事之開端。`},r),(t,n,r,i=`medium`)=>e({q:`下列古代年齡稱謂由「年輕到年長」的正確排列順序為：`,c:`垂髫 -> 及笄 -> 弱冠 -> 而立 -> 不惑 -> 知命 -> 花甲 -> 古稀 -> 期頤`,d:[`及笄 -> 垂髫 -> 而立 -> 弱冠 -> 知命 -> 不惑 -> 花甲 -> 期頤 -> 古稀`,`弱冠 -> 垂髫 -> 及笄 -> 不惑 -> 而立 -> 花甲 -> 知命 -> 古稀 -> 期頤`,`垂髫 -> 弱冠 -> 及笄 -> 而立 -> 不惑 -> 花甲 -> 知命 -> 古稀 -> 期頤`],h:`幼童(垂髫) -> 15女(及笄) -> 20男(弱冠) -> 30(而立) -> 40(不惑) -> 50(知命) -> 60(花甲) -> 70(古稀) -> 100(期頤)。`,e:`正確順序：垂髫（童年）-> 及笄（15女）-> 弱冠（20男）-> 而立（30）-> 不惑（40）-> 知命（50）-> 花甲（60）-> 古稀（70）-> 期頤（100）。`},r),(t,n,r,i=`medium`)=>e({q:`「送孟浩然之廣陵」句中的「之」字，其詞性與字義為：`,c:`動詞，前往、到...去`,d:[`代詞，他`,`助詞，的`,`助詞，無義`],h:`之字後接目的地廣陵。`,e:`「之廣陵」之「之」為動詞，作「前往、到」解。`},r),(t,n,r,i=`medium`)=>e({q:`「學而時習之」句中的「之」字，其語法功能為：`,c:`代名詞，指代學習過的知識或道理`,d:[`動詞，前往`,`介詞，在`,`助詞，取消句子獨立性`],h:`時習之：時常溫習「它」。`,e:`代指前述學習的學問或技能，作代名詞用。`},r),(t,n,r,i=`medium`)=>e({q:`「水陸草木之花」中的「之」字，其詞性與字義為：`,c:`結構助詞，相當於現代漢語的「的」`,d:[`動詞，往`,`代詞，它們`,`副詞，很`],h:`連接草木與花，表示領屬關係。`,e:`「...之花」之「之」為定語標記助詞，作「的」解。`},r),(t,n,r,i=`medium`)=>e({q:`「何陋之有？」句中的「之」字，其語法作用為：`,c:`賓語前置的結構助詞，無實質意義`,d:[`代詞，指陋室`,`動詞，擁有`,`介詞，由`],h:`原本語序為「有何陋」。`,e:`「何陋之有」為倒裝句（有何陋），「之」為提賓助詞，無義。`},r),(t,n,r,i=`medium`)=>e({q:`「菊之愛，陶後鮮有聞」句中的「之」字作用為：`,c:`賓語前置的結構助詞（愛菊）`,d:[`介詞，向`,`動詞，喜愛`,`代詞，菊花`],h:`原意為「愛菊」。`,e:`將賓語「菊」提到動詞「愛」之前，以「之」作為前置標記。`},r),(t,n,r,i=`medium`)=>e({q:`「其恕乎！己所不欲，勿施於人。」句中的「其」字語氣為：`,c:`副詞，表示委婉推測或期許語氣（大概、或許）`,d:[`代詞，他的`,`連詞，如果`,`疑問副詞，難道`],h:`推測大概就是恕道吧。`,e:`「其」在此處為語氣副詞，表示推測、估量之語氣，作「大概」解。`},r),(t,n,r,i=`medium`)=>e({q:`「其真無馬邪？其真不知馬也！」韓愈《馬說》中前一個「其」表示：`,c:`疑問反詰副詞（難道）`,d:[`指示代詞（那種）`,`代詞（牠們的）`,`連詞（或者）`],h:`難道真的沒有千里馬嗎？`,e:`前一個「其」表示激問反詰語氣，作「難道」解；後一個「其」表推測「恐怕」。`},r),(t,n,r,i=`medium`)=>e({q:`「余嘉其能行古道，作《師說》以貽之。」句中「其」字指代的是：`,c:`代名詞，指代李氏子蟠（李蟠）`,d:[`代名詞，韓愈自己`,`代名詞，天下所有學子`,`指示代詞，古人的道德`],h:`讚許他能實行古人從師之道。`,e:`「其」為第三人稱代名詞，指李蟠。`},r),(t,n,r,i=`medium`)=>e({q:`「學而不思則罔，思而不學則殆。」句中的「而」字用法為：`,c:`轉折連詞，相當於「卻」、「然而」`,d:[`順接連詞，相當於「而且」`,`修飾連詞，相當於「地」`,`時間介詞，相當於「在」`],h:`學習了「卻」不去思考。`,e:`連接學習與不思考之相反語義，表轉折關係，作「卻」解。`},r),(t,n,r,i=`medium`)=>e({q:`「敏而好學，不恥下問。」句中的「而」字語法作用為：`,c:`並列順接連詞，相當於「而且」、「又」`,d:[`轉折連詞，相當於「但是」`,`因果連詞，相當於「所以」`,`假設連詞，相當於「如果」`],h:`聰敏「而且」勤勉好學。`,e:`連接「敏」與「好學」兩種並列之優良特質，作「而且」解。`},r),(t,n,r,i=`medium`)=>e({q:`「溪深而魚肥」句中的「而」字，其功能為：`,c:`並列順接連詞，表示兩種情況同時存在`,d:[`轉折連詞`,`讓步連詞`,`時間副詞`],h:`溪水既深，游魚又肥美。`,e:`順接並列兩種豐美之自然景況，為並列連詞。`},r),(t,n,r,i=`medium`)=>e({q:`「苛政猛於虎也」句中的「於」字，其語法功能與字義為：`,c:`比較介詞，相當於「比」`,d:[`處所介詞，相當於「在」`,`對象介詞，相當於「向」`,`被動介詞，相當於「被」`],h:`苛政比老虎還要凶猛殘暴。`,e:`「猛於虎」之「於」為比較介詞，表程度高過老虎，作「比」解。`},r),(t,n,r,i=`medium`)=>e({q:`「不義而富且貴，於我如浮雲。」句中的「於」字用法為：`,c:`引介對象的介詞，相當於「對於」`,d:[`比較介詞，相當於「比」`,`時間介詞，相當於「在」`,`被動介詞，相當於「被」`],h:`對於我來說就像天邊浮雲一般。`,e:`介引感受的主體對象，相當於現代漢語之「對於」。`},r),(t,n,r,i=`medium`)=>e({q:`「青，取之於藍，而青於藍。」句中兩個「於」字用法依序為：`,c:`從（介引來源） ／ 比（比較介詞）`,d:[`在 ／ 對於`,`被 ／ 向`,`比 ／ 從`],h:`從藍草提取，比藍草更青翠。`,e:`前「於」表示來源（自、從），後「於」表示比較（比）。`},r),(t,n,r,i=`medium`)=>e({q:`「生於憂患，死於安樂。」句中的「於」字用法為：`,c:`介引原因的介詞，相當於「由於、在於」`,d:[`比較介詞`,`被動介詞`,`方向介詞`],h:`在於憂患中生存發展。`,e:`「生於憂患」指因處於憂患環境而生存奮發，表原因與處境。`},r),(t,n,r,i=`medium`)=>e({q:`「溫故而知新，可以為師矣。」句中「以」字後省略了賓語，完整語意為：`,c:`憑藉（此項能力）`,d:[`用來（教導別人）`,`以為（自己優秀）`,`因為（時間過去）`],h:`可以「之」為師。`,e:`「以」在此作介詞「憑藉」解，省略代詞賓語「之」（此種德能）。`},r),(t,n,r,i=`medium`)=>e({q:`「不以物喜，不以己悲。」范仲淹此名句中「以」字之義為：`,c:`介引原因，作「因為」解`,d:[`工具介詞，作「拿、用」解`,`動詞，作「認為」解`,`連詞，作「以便」解`],h:`不因為外在環境好壞而喜悅或悲傷。`,e:`以在此為原因介詞，作「因為」解。`},r),(t,n,r,i=`medium`)=>e({q:`「作《師說》以貽之。」句中的「以」字語法作用為：`,c:`目的連詞，相當於「用來、以便」`,d:[`原因介詞，因為`,`時間介詞，在`,`動詞，帶領`],h:`寫作這篇師說「用來」贈送給他。`,e:`表行為動機與目的之連詞，作「用來」解。`},r),(t,n,r,i=`medium`)=>e({q:`「家貧，無從致書以觀。」句中的「以」字用法為：`,c:`連詞，連接前後動作，作「而、來」解`,d:[`介詞，憑藉`,`動詞，以為`,`副詞，已經`],h:`得到書籍「來」閱讀。`,e:`連詞，表示動作承接目的，作「用來、來」解。`},r),(t,n,r,i=`medium`)=>e({q:`「太后曰：『老婦仗輦而行。』曰：『日食飲得無衰乎？』曰：『恃粥耳。』乃引其手。」句中「乃」之義為：`,c:`副詞，於是、就`,d:[`動詞，是`,`副詞，竟然`,`代詞，你的`],h:`時間承接，於是、這才。`,e:`「乃」在此表時間前後緊接，作「於是、才」解。`},r),(t,n,r,i=`medium`)=>e({q:`「問今是何世，乃不知有漢，無論魏晉。」《桃花源記》中「乃」字表示：`,c:`副詞，竟然、居然（出乎意料語氣）`,d:[`動詞，是`,`代詞，他們`,`連詞，所以`],h:`居然連漢朝都不知道！`,e:`表示極度驚詫與出乎意料，作「竟然、居然」解。`},r),(t,n,r,i=`medium`)=>e({q:`「家祭毋忘告乃翁。」陸游《示兒》詩中「乃」字之詞性與字義為：`,c:`第二人稱代詞，你的`,d:[`動詞，是`,`副詞，才`,`連詞，而且`],h:`乃翁即「你的父親」。`,e:`「乃翁」之「乃」為代詞，指「你的」之意。`},r),(t,n,r,i=`medium`)=>e({q:`「學而不思則罔」句中的「則」字用法為：`,c:`承接連詞，相當於「就、便」`,d:[`轉折連詞，然而`,`副詞，原來`,`名詞，法則規矩`],h:`只學習不思考「就」會迷惘。`,e:`「則」在此表假設條件之後果推導，作「就、便」解。`},r),(t,n,r,i=`medium`)=>e({q:`「此則岳陽樓之大觀也。」句中的「則」字作用為：`,c:`副詞，加強判斷肯定語氣，相當於「就是」`,d:[`連詞，如果`,`轉折連詞，但是`,`名詞，榜樣`],h:`這「就是」岳陽樓的雄偉景觀。`,e:`在判斷句中充當副詞以強化肯定語氣，作「就是」解。`},r),(t,n,r,i=`medium`)=>e({q:`「彼且奚適也？」《莊子·逍遙遊》中「且」字之義為：`,c:`副詞，將要`,d:[`連詞，而且`,`連詞，姑且`,`連詞，尚且`],h:`牠將要飛到哪裡去呢？`,e:`「且」在此作時間副詞，作「將要」解。`},r),(t,n,r,i=`medium`)=>e({q:`「且壯士不死即已，死即舉大名耳。」陳涉所言中「且」字功能為：`,c:`連詞，況且、再說`,d:[`副詞，將近`,`動詞，尚且`,`介詞，在`],h:`承上啟下進一步論述，況且壯士不死則已。`,e:`表遞進關係之發語連詞，作「況且、再說」解。`},r),(t,n,r,i=`medium`)=>e({q:`「君子病無能焉，不病人之不己知也。」前句末尾「焉」字之作用為：`,c:`語氣詞，表示陳述肯定語氣`,d:[`代詞，這件事`,`疑問代詞，哪裡`,`兼詞，於此`],h:`放在句末表陳述語氣助詞。`,e:`「焉」在此處作句尾語氣助詞，表確定陳述。`},r),(t,n,r,i=`medium`)=>e({q:`「割雞焉用牛刀？」句中的「焉」字語法功能為：`,c:`疑問代名詞／副詞，相當於「何、哪裡」`,d:[`代名詞，牠`,`語氣詞，啊`,`介詞，在`],h:`殺雞「哪裡」用得著牛刀！`,e:`表疑問反詰，作「何、何必、哪裡」解。`},r),(t,n,r,i=`medium`)=>e({q:`「積土成山，風雨興焉；積水成淵，蛟龍生焉。」兩句中「焉」字為：`,c:`兼詞，相當於「於此」（在那裡）`,d:[`代詞，牠們`,`疑問詞，怎麼`,`語氣詞，罷了`],h:`風雨從這裡興起，蛟龍在這裡生長。`,e:`「焉」在此充當「於此」的合音兼詞，表處所來源。`},r),(t,n,r,i=`medium`)=>e({q:`「微斯人，吾誰與歸？」范仲淹《岳陽樓記》末句中「微」字之義為：`,c:`隱含否定假設的副詞，作「如果沒有」解`,d:[`形容詞，微小細微`,`副詞，稍微略微`,`動詞，暗中隱蔽`],h:`如果沒有這種古代仁人志士。`,e:`「微」在此表假設否定，作「如果沒有、非」解。`},r),(t,n,r,i=`medium`)=>e({q:`「孔子云：『何陋之有？』」依現代漢語語序還原，應為：`,c:`有何陋（賓語前置）`,d:[`何有陋`,`陋何有`,`之有何陋`],h:`提賓結構助詞「之」將「何陋」提前。`,e:`正常動賓語序為「有何陋」，文言文中為強調賓語將其前置，以「之」標示。`},r),(t,n,r,i=`medium`)=>e({q:`「句讀之不知，惑之不解。」韓愈這兩句話還原為正常語序應為：`,c:`不知句讀，不解惑`,d:[`句讀不知之，惑不解之`,`知句讀之，解惑之`,`之不知句讀，之不解惑`],h:`不知與不解之賓語被提前並加「之」。`,e:`「不知句讀」倒裝為「句讀之不知」；「不解惑」倒裝為「惑之不解」。`},r),(t,n,r,i=`medium`)=>e({q:`「宋何罪之有？」還原為現代語序應為：`,c:`宋有何罪？`,d:[`宋之何罪？`,`何罪宋有？`,`有宋何罪？`],h:`何罪為賓語提前。`,e:`此句為典型的疑問代詞賓語前置倒裝句，正常語序為「宋有何罪」。`},r),(t,n,r,i=`medium`)=>e({q:`「唯利是圖」這句成語的正常文言語序為：`,c:`唯圖利（只貪圖利益）`,d:[`唯利圖是`,`是唯圖利`,`圖唯利是`],h:`以「是」作為賓語提前標誌。`,e:`「唯...是...」為文言提賓格式，將「利」提前置於動詞「圖」前，原意為「唯圖利」。`},r),(t,n,r,i=`medium`)=>e({q:`「唯命是從」還原為正常語序應為：`,c:`唯從命（只聽從命令）`,d:[`唯從是命`,`是唯從命`,`從唯命是`],h:`「命」為動詞「從」之賓語提前。`,e:`以「是」提賓，原動賓結構為「唯從命」。`},r),(t,n,r,i=`medium`)=>e({q:`「馬首是瞻」原意為士兵作戰時看著主帥馬頭的方向前進，其語序還原為：`,c:`瞻馬首`,d:[`是瞻馬首`,`馬首瞻是`,`瞻是馬首`],h:`瞻為動詞，馬首為賓語。`,e:`「瞻」為動詞看望，「馬首」為賓語，提賓倒裝為「馬首是瞻」。`},r),(t,n,r,i=`medium`)=>e({q:`「忌不自信」《鄒忌諷齊王納諫》句中「不自信」還原正常語序為：`,c:`不信自（不相信自己）`,d:[`自信不`,`不自能信`,`自不可信`],h:`否定句中代名詞賓語前置。`,e:`在否定句（含不）中，代詞賓語「自」前置於動詞「信」之前，原義為「不信自」。`},r),(t,n,r,i=`medium`)=>e({q:`「古之人不余欺也！」蘇軾《石鐘山記》句中「不余欺」還原為：`,c:`不欺余（沒有欺騙我）`,d:[`余不欺`,`不欺古人`,`欺我不成`],h:`余為代名詞賓語前置。`,e:`否定句中代詞賓語「余」（我）置於動詞「欺」前，正常語序為「不欺余」。`},r),(t,n,r,i=`medium`)=>e({q:`「微斯人，吾誰與歸？」范仲淹名句中「吾誰與歸」之正常語序為：`,c:`吾與誰歸（我同誰一道呢）`,d:[`吾歸誰與`,`誰吾與歸`,`歸吾與誰`],h:`介詞「與」的疑問代詞賓語「誰」前置。`,e:`介賓結構中疑問代詞「誰」前置於介詞「與」之前，正常語序為「吾與誰歸」。`},r),(t,n,r,i=`medium`)=>e({q:`「沛公安在？」《史記·項羽本紀》句中「安在」還原為現代語序應為：`,c:`在安（在哪裡）`,d:[`安安在`,`在何安`,`安居於此`],h:`疑問代詞「安」前置於動詞「在」之前。`,e:`疑問代詞作動詞賓語必須前置，故「在安（在哪裡）」倒裝為「安在」。`},r),(t,n,r,i=`medium`)=>e({q:`「彼且奚適也？」句中「奚適」還原為正常語序為：`,c:`適奚（往哪裡去）`,d:[`適彼`,`奚去適`,`適彼何處`],h:`適為動詞往，奚為疑問代詞哪裡。`,e:`疑問代詞「奚」作動詞「適」（前往）之賓語提前，原義為「適奚」。`},r),(t,n,r,i=`medium`)=>e({q:`「豫州今欲何至？」句中「何至」之正常語序為：`,c:`至何（到哪裡去）`,d:[`何欲至`,`至何處何`,`何所至至`],h:`何為疑問代詞賓語前置於動詞至之前。`,e:`疑問代詞「何」前置於述語動詞「至」之前，正常語序為「欲至何」。`},r),(t,n,r,i=`medium`)=>e({q:`「君何患焉？」還原為現代語序應為：`,c:`君患何焉（您擔憂什麼呢）`,d:[`何君患焉`,`焉患何君`,`何患君焉`],h:`疑問代詞何前置於動詞患之前。`,e:`動詞為「患」（擔憂），賓語為疑問代詞「何」，前置為「何患」。`},r),(t,n,r,i=`medium`)=>e({q:`「求！無乃爾是過與？」孔子責備冉求，其中「爾是過」還原為：`,c:`過爾（責怪你）`,d:[`是過爾`,`爾過是`,`過是爾`],h:`過為動詞責備，爾為代名詞你。`,e:`提賓句式「爾是過」，「過」為動詞責備，「爾」為賓語，原義為「過爾」。`},r),(t,n,r,i=`medium`)=>e({q:`「將子無怒，秋以為期。」《詩經·衛風·氓》句中「秋以為期」正常語序為：`,c:`以秋為期（把秋天作為約定期限）`,d:[`期以秋為`,`為期以秋`,`以期為秋`],h:`介詞「以」之賓語「秋」提前。`,e:`介詞賓語前置，「以秋為期」倒裝為「秋以為期」。`},r),(t,n,r,i=`medium`)=>e({q:`「便要還家，設酒殺雞作食。」《桃花源記》中「要」字通假為：`,c:`「邀」，邀請`,d:[`「要」，重要`,`「腰」，腰部`,`「約」，約定`],h:`邀請漁人到家中做客。`,e:`「要」通「邀」，音ㄧㄠ，作「邀請」解。`},r),(t,n,r,i=`medium`)=>e({q:`「學而時習之，不亦說乎！」句中的「說」字通假為：`,c:`「悅」，喜悅高興`,d:[`「說」，說話說明`,`「稅」，納稅`,`「脫」，解脫`],h:`心中感到歡喜快樂。`,e:`「說」通「悅」，音ㄩㄝˋ，作「喜悅」解。`},r),(t,n,r,i=`medium`)=>e({q:`「旦日不可不蚤自來謝項王。」《鴻門宴》句中的「蚤」字通假為：`,c:`「早」，清晨、及早`,d:[`「跳蚤」之蚤`,`「爪」，手指甲`,`「造」，拜訪`],h:`明早親自前來謝罪。`,e:`「蚤」通「早」，音ㄗㄠˇ，清晨之意。`},r),(t,n,r,i=`medium`)=>e({q:`「具告以事」句中的「具」字通假為：`,c:`「俱」，全部、詳細地`,d:[`「工具」之具`,`「懼」，恐懼`,`「劇」，劇烈`],h:`把事情全部詳細告知。`,e:`「具」通「俱」，音ㄐㄩˋ，副詞，作「全、皆、詳細」解。`},r),(t,n,r,i=`medium`)=>e({q:`「始皇帝幸梁山宮，從山上見丞相車騎眾，弗善也。中人或益告丞相，丞相為損後騎。始皇怒曰：『此中人洩吾語！』案問莫服。」句中「案」通：`,c:`「按」，調查追究`,d:[`「桌案」之案`,`「安」，安放`,`「暗」，暗中`],h:`審查盤問調查。`,e:`「案」通「按」，作「審訊、按察追究」解。`},r),(t,n,r,i=`medium`)=>e({q:`「願伯具言臣之不敢倍德也。」《史記》句中「倍」字通假為：`,c:`「背」，背叛、違背`,d:[`「加倍」之倍`,`「備」，準備`,`「輩」，同輩`],h:`不敢背叛恩德。`,e:`「倍」通「背」，音ㄅㄟˋ，作「違背、背叛」解。`},r),(t,n,r,i=`medium`)=>e({q:`「風吹草低見牛羊」中的「見」字通假為：`,c:`「現」，顯現、看見`,d:[`「看見」之見`,`「建」，建立`,`「鑑」，借鏡`],h:`風吹草低顯露出來。`,e:`「見」通「現」，音ㄒㄧㄢˋ，作「顯現」解。`},r),(t,n,r,i=`medium`)=>e({q:`「食馬者不知其能千里而食也。」後一個「食」字通假為：`,c:`「飼」，餵養飼養`,d:[`「飲食」之食`,`「蝕」，侵蝕`,`「實」，確實`],h:`餵養千里馬的人。`,e:`後一個「食」通「飼」，音ㄙˋ，動詞餵養。`},r),(t,n,r,i=`medium`)=>e({q:`「才美不外見」韓愈《馬說》中的「見」字讀音與通假為：`,c:`音ㄒㄧㄢˋ，通「現」，表現顯露`,d:[`音ㄐㄧㄢˋ，看見遇見`,`音ㄐㄧㄢˋ，引見接見`,`音ㄒㄧㄢˋ，貢獻獻禮`],h:`才能美好無法顯露於外。`,e:`「見」通「現」，音ㄒㄧㄢˋ，表現、顯露於外。`},r),(t,n,r,i=`medium`)=>e({q:`「項伯許諾，謂沛公曰：『旦日不可不蚤自來謝項王。』」句中「謝」字之義為：`,c:`認錯謝罪道歉`,d:[`道謝感謝`,`辭別離去`,`凋謝枯萎`],h:`親自來向項羽賠罪認錯。`,e:`文言文中「謝」常作「道歉、謝罪」解，非單純感謝之意。`},r),(t,n,r,i=`medium`)=>e({q:`「尊君在不？」《世說新語》句中的「不」字讀音與通假為：`,c:`音ㄈㄡˇ，通「否」，相當於「嗎、沒有」`,d:[`音ㄅㄨˋ，否定詞不是`,`音ㄈㄡ，不同意`,`音ㄆㄧ，否卦`],h:`令尊在不在家呢？`,e:`「不」通「否」，音ㄈㄡˇ，句尾疑問助詞，相當於「否、嗎」。`},r),(t,n,r,i=`medium`)=>e({q:`「孰為汝多知乎！」兩小兒笑曰，句中的「知」字通假為：`,c:`「智」，智慧才識`,d:[`「知道」之知`,`「知己」之知`,`「主持」之知`],h:`誰說你孔子見多識廣有大智慧呢？`,e:`「知」通「智」，音ㄓˋ，作「智慧才學」解。`},r),(t,n,r,i=`medium`)=>e({q:`「滿座賓客無不伸頸，側目，微笑，默嘆，以為妙絕也。」《口技》中「座」通假為：`,c:`「坐」，同「座位、在坐的人」`,d:[`「作」，發作`,`「錯」，交錯`,`「昨」，昨日`],h:`全場在座的所有賓客。`,e:`「座」通「坐」，指所有在座聆聽之聽眾。`},r),(t,n,r,i=`medium`)=>e({q:`「寒暑易節，始一反焉。」《愚公移山》句中的「反」字通假為：`,c:`「返」，返回回家`,d:[`「相反」之反`,`「造反」之反`,`「反省」之反`],h:`去了一年才返回一次。`,e:`「反」通「返」，音ㄈㄢˇ，作「返回、回來」解。`},r),(t,n,r,i=`medium`)=>e({q:`「自三峽七百里中，兩岸連山，略無闕處。」酈道元《水經注》中「闕」字通：`,c:`「缺」，中斷殘缺`,d:[`「宮闕」之闕`,`「卻」，退卻`,`「雀」，鳥雀`],h:`毫無中斷中空之處。`,e:`「闕」通「缺」，音ㄑㄩㄝ，作「殘缺、中斷」解。`},r),(t,n,r,i=`medium`)=>e({q:`唐代「近體詩」（格律詩）最主要的體裁形式包括：`,c:`絕句 與 律詩（五言、七言）`,d:[`古體詩 與 樂府詩`,`宋詞 與 元曲`,`楚辭 與 賦體`],h:`唐代成熟的嚴格格律詩歌體系。`,e:`唐代格律詩稱為近體詩，主要分為絕句（四句）與律詩（八句），每首分為五言或七言。`},r),(t,n,r,i=`medium`)=>e({q:`一首標準的「律詩」共有幾句？`,c:`8 句`,d:[`4 句`,`6 句`,`10 句`],h:`八句四聯。`,e:`律詩嚴格規定為八句，分為首聯、頷聯、頸聯、尾聯四聯。`},r),(t,n,r,i=`medium`)=>e({q:`一首標準的「絕句」共有幾句？`,c:`4 句`,d:[`8 句`,`2 句`,`6 句`],h:`截取律詩之一半，共四句。`,e:`絕句由四句組成，分為五言絕句（20字）與七言絕句（28字）。`},r),(t,n,r,i=`medium`)=>e({q:`在八句律詩中，依規定必須嚴格講究「對仗」的兩聯是：`,c:`頷聯（三、四句） 與 頸聯（五、六句）`,d:[`首聯（一、二句） 與 尾聯（七、八句）`,`首聯 與 頷聯`,`頸聯 與 尾聯`],h:`三四句與五六句必須字詞對仗工整。`,e:`律詩格律核心要求：頷聯（第3、4句）與頸聯（第5、6句）必須兩兩對仗。`},r),(t,n,r,i=`medium`)=>e({q:`關於近體詩的「押韻」規則，下列敘述何者完全正確？`,c:`偶數句（二、四、六、八句）必須押韻，且一韻到底不得換韻`,d:[`奇數句（一、三、五、七句）必須押韻`,`可以隨意更換韻腳，平仄韻互換`,`每一句句尾皆必須押韻`],h:`雙數句必押韻，通常押平聲韻，一韻到底。`,e:`近體詩偶數句必押韻，首句可押可不押，奇數句不押韻，且全首一韻到底不得轉韻。`},r),(t,n,r,i=`medium`)=>e({q:`近體詩押韻通常採用何種聲調之韻部？`,c:`平聲韻`,d:[`仄聲韻（上聲或去聲）`,`入聲韻專用`,`任意聲調皆可混合`],h:`近體詩絕大多數押平聲韻。`,e:`唐代近體詩絕大多數嚴格押平聲韻（陰平、陽平），極少押仄聲韻。`},r),(t,n,r,i=`medium`)=>e({q:`「一首詩中，第一句末字不押韻，第三句不押韻，第二、四、六、八句皆押平聲韻。」此體裁為：`,c:`七言律詩（或五言律詩）`,d:[`古體詩`,`排律`,`詞牌曲調`],h:`八句雙數句押韻，為標準律詩。`,e:`此為近體詩律詩最標準經典之押韻規範格式。`},r),(t,n,r,i=`medium`)=>e({q:`古體詩（古風）與近體詩在形式規範上最大的差異在於：`,c:`古體詩字數句數不限、平仄寬鬆、可換韻；近體詩句數字數平仄押韻皆有嚴格限制`,d:[`古體詩只能描寫戰爭，近體詩只能描寫山水`,`古體詩不能抒情，近體詩只能敘事`,`古體詩必須配樂演唱，近體詩完全不配樂`],h:`古體詩自由自由不拘，近體詩格律嚴謹。`,e:`古體詩句數不拘、篇幅長短隨意、押韻平仄自由可換韻；近體詩字數、句數、平仄、對仗、一韻到底皆受嚴格約束。`},r),(t,n,r,i=`medium`)=>e({q:`宋代文學最具代表性的詩歌體裁為「詞」，詞又稱為「長短句」或「詩餘」，主要原因為：`,c:`依詞牌曲調填詞，句子長短參差不齊，由詩歌演化而來配合音樂歌唱`,d:[`詞人懶於修飾字句故字數長短隨意`,`專門用來記載長篇歷史故事小說`,`只有兩句短句與兩句長句組成`],h:`倚聲填詞，按譜填字，句式長短不一。`,e:`詞乃配合燕樂曲調填寫之歌詞，因每首曲調音拍不同故句子長短參差，故稱長短句。`},r),(t,n,r,i=`medium`)=>e({q:`填詞時依據的樂譜格式與名稱（如《水調歌頭》、《念奴嬌》、《破陣子》）稱為：`,c:`詞牌（詞調名稱）`,d:[`曲目`,`詩題`,`標題`],h:`詞牌決定詞的字數、句數、平仄與韻腳。`,e:`詞牌是填詞所依據的曲譜名稱，規定了該詞的總字數、句式結構、平仄與押韻位置。`},r),(t,n,r,i=`medium`)=>e({q:`宋詞在風格流派上，主要分為哪兩大體系？`,c:`豪放派（蘇軾、辛棄疾） 與 婉約派（柳永、李清照、秦觀）`,d:[`浪漫派 與 寫實派`,`田園派 與 邊塞派`,`山水派 與 宮體派`],h:`蘇辛豪邁壯闊，柳李細膩委婉。`,e:`宋詞兩大宗：豪放派以蘇軾、辛棄疾為代表，風格雄渾奔放；婉約派以柳永、李清照為代表，情思婉約細膩。`},r),(t,n,r,i=`medium`)=>e({q:`元代文學代表「元曲」，主要包括哪兩大類別？`,c:`散曲（小令、套數） 與 雜劇（戲曲劇本）`,d:[`詩 與 詞`,`京劇 與 崑曲`,`傳奇 與 變文`],h:`元曲包含個人抒情之散曲與舞台搬演之雜劇。`,e:`元曲分為可獨立演唱之散曲（小令、套數）與舞台演出的戲劇雜劇（關漢卿、白樸等）。`},r),(t,n,r,i=`medium`)=>e({q:`散曲在格律形式上比宋詞更加自由活潑，其最顯著的體裁特徵為允許加入：`,c:`襯字（在規定字數外添加自由字詞使語氣生動）`,d:[`外國文字`,`散文無韻段落`,`隨意插圖`],h:`在曲譜正字之外添加活潑口語襯字。`,e:`散曲最獨特之處在於正字外可隨意加入「襯字」，使語言更加生動口語化。`},r),(t,n,r,i=`medium`)=>e({q:`「枯藤老樹昏鴉，小橋流水人家，古道西風瘦馬。夕陽西下，斷腸人在天涯。」馬致遠這首名作體裁為：`,c:`元散曲中的「小令」（曲牌：天淨沙）`,d:[`五言絕句`,`宋詞詞調`,`七言律詩`],h:`秋思之祖，為散曲小令代表。`,e:`馬致遠《天淨沙·秋思》為元代散曲中小令之極品，被譽為「秋思之祖」。`},r),(t,n,r,i=`medium`)=>e({q:`下列關於律詩「黏對」規則之敘述，何者正確？`,c:`同聯上下句平仄相對，相鄰聯相鄰句（如第二句與第三句）平仄相黏（相同）`,d:[`全詩八句平仄完全一樣`,`每一句末字都必須是平聲`,`上下兩聯首字必須相同`],h:`對指上下句平仄相反，黏指相鄰句平仄相同。`,e:`律詩格律中「對」指同一聯中出句與對句平仄相反；「黏」指上一聯之對句與下一聯之出句平仄相同。`},r),(t,n,r,i=`medium`)=>e({q:`近體詩律詩中，若第一聯（一、二句）就出現對仗，此種格式在修辭上稱為：`,c:`首聯對仗`,d:[`流水對`,`扇面對`,`隔句對`],h:`第一聯也講究對仗。`,e:`律詩嚴格要求頷聯頸聯對仗，若首聯亦對仗，稱首聯對仗（如杜甫《絕句》兩隻黃鸝鳴翠柳）。`},r),(t,n,r,i=`medium`)=>e({q:`「野火燒不盡，春風吹又生。」白居易這兩句詩在律詩結構中屬於：`,c:`頷聯（對仗工整，野火對春風，燒不盡對吹又生）`,d:[`首聯`,`頸聯`,`尾聯`],h:`《賦得古原草送別》第3、4句為頷聯。`,e:`詩出自《草》，第3、4句為頷聯，字詞詞性對仗工整極致。`},r),(t,n,r,i=`medium`)=>e({q:`「海內存知己，天涯若比鄰。」王勃《送杜少府之任蜀州》中這兩句名句屬於律詩的：`,c:`頸聯（第五、六句，對仗極其高超自然）`,d:[`首聯`,`頷聯`,`尾聯`],h:`第5、6句為頸聯。`,e:`王勃此詩第5、6句為頸聯，跨越時空距離以崇高情誼相對仗。`},r),(t,n,r,i=`medium`)=>e({q:`下列哪一首作品「完全屬於七言絕句」？`,c:`朝辭白帝彩雲間，千里江陵一日還。兩岸猿聲啼不住，輕舟已過萬重山。`,d:[`白日依山盡，黃河入海流。欲窮千里目，更上一層樓。`,`國破山河在，城春草木深。感時花濺淚，恨別鳥驚心。`,`明月幾時有？把酒問青天。不知天上宮闕，今夕是何年。`],h:`四句，每句七個字。`,e:`李白《早發白帝城》全詩四句，每句七字，偶句押韻，為典型七言絕句。`},r),(t,n,r,i=`medium`)=>e({q:`下列哪一首詩屬於「五言絕句」體裁？`,c:`床前明月光，疑是地上霜。舉頭望明月，低頭思故鄉。`,d:[`春眠不覺曉，處處聞啼鳥。夜來風雨聲，花落知多少。（亦為五絕，首句押韻）`,`慈母手中線，遊子身上衣。臨行密密縫，意恐遲遲歸。`,`君自故鄉來，應知故鄉事。來日綺窗前，寒梅著花未。`],h:`四句，每句五個字。`,e:`李白《靜夜思》四句，每句五言，為千古傳誦之五言絕句代表。`},r),(t,n,r,i=`medium`)=>e({q:`詞調中句子分為「單調」（一段）與「雙調」（兩段），其中雙調的前段與後段分別稱為：`,c:`上闋（上片） 與 下闋（下片）`,d:[`前引 與 後綴`,`上聯 與 下聯`,`出句 與 對句`],h:`詞的兩段稱為上下片或上下闋。`,e:`詞的一段稱為一闋或一片，雙調詞分為「上闋（上片）」與「下闋（下片）」。`},r),(t,n,r,i=`medium`)=>e({q:`「近鄉情更怯，不敢問來人。」宋之問這兩句詩描繪遊子歸鄉心情，其體裁為：`,c:`五言律詩中的尾聯（抒情作結）`,d:[`七言絕句`,`樂府歌行`,`散曲小令`],h:`《渡漢江》末兩句為尾聯結尾。`,e:`出自五言律詩《渡漢江》第7、8句尾聯，以怯弱不敢發問深刻揭露憂患心理。`},r),(t,n,r,i=`medium`)=>e({q:`「大江東去，浪淘盡，千古風流人物。」蘇軾《念奴嬌·赤壁懷古》展現的詞風為：`,c:`雄渾豪放、氣勢磅礡的豪放派詞風`,d:[`纏綿悱惻、柔腸寸斷之婉約派詞風`,`詼諧幽默之諷刺曲風`,`枯寂空靈之隱逸禪風`],h:`千古風流人物，開創豪放詞風新紀元。`,e:`東坡以雄奇壯麗的大江浪濤起筆，縱論千古英雄，為豪放派之巔峰代表作。`},r),(t,n,r,i=`medium`)=>e({q:`「尋尋覓覓，冷冷清清，淒淒慘慘戚戚。」李清照《聲聲慢》開篇連用十四個疊字，其詞風屬於：`,c:`細膩深沉、婉轉淒切的婉約派巔峰之作`,d:[`慷慨激昂之豪放派詞風`,`通俗熱烈之市民口語風格`,`剛烈勇猛之邊塞軍旅風`],h:`連用十四疊字，將國破家亡夫死之至深悲痛層層鋪展。`,e:`婉約詞宗李清照以連綴疊字開篇，音律如泣如訴，為婉約詞之神來之筆。`},r),(t,n,r,i=`medium`)=>e({q:`在絕句格律中，關於第三句的地位與作用，古人常以「起、承、轉、合」論之，第三句屬於：`,c:`「轉」（文意與視角的關鍵轉折拓寬，全詩波瀾所在）`,d:[`「起」（開篇點題）`,`「承」（承接上文展開）`,`「合」（收束總結全詩）`],h:`轉折引出嶄新意境。`,e:`絕句結構：第一句起，第二句承，第三句轉（關鍵轉折），第四句合（結尾點題）。`},r),(t,n,r,i=`medium`)=>e({q:`「月落烏啼霜滿天，江楓漁火對愁眠。姑蘇城外寒山寺，夜半鐘聲到客船。」第三句「姑蘇城外寒山寺」發揮之功能為：`,c:`空間轉向寺院，由眼見轉為耳聽，為起承轉合中的「轉」`,d:[`全詩總結`,`開篇寫景`,`承接霜天`],h:`由江上轉到遠方寒山寺鐘聲，由視覺轉聽覺。`,e:`第三句將視野拉向空曠幽遠之寒山寺，完成由視覺到聽覺、由近景到遠境之神奇轉折。`},r),(t,n,r,i=`medium`)=>e({q:`杜甫《客至》中「花徑不曾緣客掃，蓬門今始為君開」在律詩結構中屬於：`,c:`頷聯（對仗工整，花徑對蓬門，緣客掃對為君開）`,d:[`首聯`,`頸聯`,`尾聯`],h:`第3、4句為頷聯。`,e:`第3、4句頷聯對仗工整，花徑對蓬門，展現迎客之真誠歡喜。`},r),(t,n,r,i=`medium`)=>e({q:`下列詞牌名稱中，何者「並非」詞牌，而是古代詩歌體裁？`,c:`《遊子吟》（為樂府古詩題）`,d:[`《水調歌頭》`,`《虞美人》`,`《菩薩蠻》`],h:`孟郊遊子吟為五言古詩題目。`,e:`《遊子吟》是孟郊所作樂府古詩題目；其餘三者皆為宋詞常用之固定曲調詞牌。`},r),(t,n,r,i=`medium`)=>e({q:`「一曲新詞酒一杯，去年天氣舊亭台。夕陽西下幾時回？無可奈何花落去，似曾相識燕歸來。小園香徑獨徘徊。」此作品體裁為：`,c:`宋詞（雙調小令，詞牌：浣溪沙）`,d:[`七言律詩`,`元散曲`,`古樂府詩`],h:`晏殊《浣溪沙》小令代表作。`,e:`此為晏殊名篇《浣溪沙》，句式參差，分為上下兩闋，屬宋詞小令。`},r),(t,n,r,i=`medium`)=>e({q:`元曲四大家通常是指下列哪四位卓越劇作家？`,c:`關漢卿、白樸、馬致遠、鄭光祖`,d:[`蘇軾、辛棄疾、李清照、歐陽脩`,`李白、杜甫、王維、白居易`,`韓愈、柳宗元、歐陽脩、蘇洵`],h:`關白馬鄭。`,e:`元曲四大家指元代雜劇奠基代表作家：關漢卿、白樸、馬致遠、鄭光祖。`},r),(t,n,r,i=`medium`)=>e({q:`戰國時期楚國偉大愛國詩人屈原開創了浪漫主義詩歌體裁，其代表作為：`,c:`《離騷》、《九歌》、《天問》`,d:[`《詩經》`,`《史記》`,`《春秋》`],h:`楚辭之代表作家。`,e:`屈原創立楚辭體，長篇抒情詩《離騷》展現宏大壯麗之浪漫主義精神與深摯愛國情懷。`},r),(t,n,r,i=`medium`)=>e({q:`被尊為「隱逸詩人之宗」、「田園詩人鼻祖」的東晉文學家為：`,c:`陶淵明（陶潛）`,d:[`謝靈運`,`嵇康`,`王維`],h:`採菊東籬下，悠然見南山。`,e:`陶淵明辭官歸隱，開創田園詩派，以質樸自然、超凡脫俗之田園詩風聞名千古。`},r),(t,n,r,i=`medium`)=>e({q:`盛唐詩人李白在中國文學史上被尊稱為：`,c:`「詩仙」（豪放飄逸，浪漫主義巔峰）`,d:[`「詩聖」`,`「詩佛」`,`「詩鬼」`],h:`詩仙李白，飄逸若仙。`,e:`李白詩風豪邁奔放、想像奇絕、清新飄逸，人稱「詩仙」。`},r),(t,n,r,i=`medium`)=>e({q:`盛唐詩人杜甫被尊稱為：`,c:`「詩聖」（其詩記錄時代疾苦，被譽為「詩史」）`,d:[`「詩仙」`,`「詩豪」`,`「詩囚」`],h:`沉鬱頓挫，關懷蒼生，為詩中聖哲。`,e:`杜甫憂國憂民，詩風沉鬱頓挫，以高度社會責任感反映安史之亂人間疾苦，尊為「詩聖」。`},r),(t,n,r,i=`medium`)=>e({q:`盛唐山水田園詩派代表詩人王維，其詩歌融入深邃禪意，後世尊稱為：`,c:`「詩佛」（詩中有畫，畫中有詩）`,d:[`「詩魔」`,`「詩仙」`,`「詩豪」`],h:`蘇軾評其：味摩詰之詩，詩中有畫；觀摩詰之畫，畫中有詩。`,e:`王維字摩詰，精通佛理禪機，山水田園詩清冷空靈，後人尊稱為「詩佛」。`},r),(t,n,r,i=`medium`)=>e({q:`唐代倡導「新樂府運動」，主張「文章合為時而著，歌詩合為事而作」的現實主義大詩人為：`,c:`白居易（居易）`,d:[`李商隱`,`杜牧`,`孟浩然`],h:`諷諭詩記錄民間疾苦，語言老嫗能解。`,e:`白居易主張詩歌必須反映社會現實民生疾苦，語言通俗平易，為新樂府運動領袖。`},r),(t,n,r,i=`medium`)=>e({q:`中唐時期發起「古文運動」，主張「文以載道」、「文道合一」，被譽為「文起八代之衰」的文學大家為：`,c:`韓愈（韓昌黎）`,d:[`柳宗元`,`歐陽脩`,`蘇軾`],h:`唐宋八大家之首。`,e:`蘇軾《潮州韓文公廟碑》讚譽韓愈：「文起八代之衰，而道濟天下之溺。」力抗六朝駢儷浮華文風。`},r),(t,n,r,i=`medium`)=>e({q:`與韓愈並稱「韓柳」，同為唐代古文運動領袖，並以《永州八記》開創山水遊記散文巔峰的大文豪為：`,c:`柳宗元（柳河東）`,d:[`歐陽脩`,`王安石`,`蘇轍`],h:`被貶永州，寫下永州八記寓情於景。`,e:`柳宗元山水遊記描摹精微、寓意深遠，並創作深刻寓言散文，為唐宋八大家之一。`},r),(t,n,r,i=`medium`)=>e({q:`「唐宋八大家」中，宋代的六位散文大家包括：`,c:`歐陽脩、蘇洵、蘇軾、蘇轍、王安石、曾鞏`,d:[`范仲淹、司馬光、陸游、辛棄疾、文天祥、朱熹`,`柳宗元、白居易、劉禹錫、李商隱、杜牧、孟郊`,`周敦頤、張載、程顥、程頤、朱熹、陸九淵`],h:`一歐三蘇王曾。`,e:`唐宋八大家：唐代韓愈、柳宗元；宋代歐陽脩、蘇洵、蘇軾、蘇轍（三蘇）、王安石、曾鞏。`},r),(t,n,r,i=`medium`)=>e({q:`北宋文壇領袖歐陽脩字永叔，號醉翁、六一居士，其散文風格特色為：`,c:`從容平易，委婉流暢，開宋代平實清新文風`,d:[`奇詭險怪，生硬艱澀`,`詞藻華麗堆砌，全篇駢儷對偶`,`剛烈暴躁，充滿殺伐之氣`],h:`文風平易近人如話家常。`,e:`歐陽脩領導北宋詩文革新，提拔三蘇、曾鞏、王安石，文風平易流暢，自然條達。`},r),(t,n,r,i=`medium`)=>e({q:`北宋大文豪蘇軾（東坡居士）在文學藝術領域造詣極高，其成就涵蓋：`,c:`詩、詞、散文、書法、繪畫皆達千古極致境界`,d:[`僅專精於宋詞填詞，不擅長散文詩歌`,`僅善於書法，未曾創作文學作品`,`僅為一位政治家，文學成就平庸`],h:`全方位天才文豪。`,e:`蘇軾文列八大家、詩與黃庭堅並稱蘇黃、詞開豪放派、書法列宋四家、畫開文人畫派，為千古全才。`},r),(t,n,r,i=`medium`)=>e({q:`李清照號易安居士，宋代最傑出之女詞人，其詞作前期與後期風格差異主要源於：`,c:`前期生活幸福優裕詞風明麗輕快；後期遭遇靖康之禍國破家亡夫死，詞風淒苦沉痛`,d:[`前期追求榮華富貴，後期看破紅塵出家為尼`,`前期隱居鄉野，後期入朝擔任高官`,`前期專寫邊塞戰爭，後期專寫宮廷宴樂`],h:`靖康之變與丈夫趙明誠病逝帶來巨大人生變故。`,e:`李清照前期寫閨情相思明朗清新；金兵南下國破家亡流離失所後，後期作品滿溢身世之慟與家國之悲。`},r),(t,n,r,i=`medium`)=>e({q:`南宋愛國詞人辛棄疾（稼軒居士）與蘇軾齊名，並稱「蘇辛」，辛詞最顯著的主題特色為：`,c:`強烈的愛國情懷與恢復中原收復失地的壯志難酬之慨`,d:[`描摹男女幽會戀情之柔弱感傷`,`純粹歌詠山林清幽之隱居樂趣`,`描寫市井商賈繁華喧鬧之生活`],h:`醉裡挑燈看劍，夢回吹角連營。`,e:`辛棄疾青年渡江抗金，一生以光復中原為己任，詞作洋溢英雄豪氣與悲壯愛國胸襟。`},r),(t,n,r,i=`medium`)=>e({q:`晚唐詩壇代表詩人「小李杜」是指：`,c:`李商隱 與 杜牧`,d:[`李白 與 杜甫`,`李賀 與 杜荀鶴`,`李益 與 杜審言`],h:`李商隱與杜牧合稱小李杜。`,e:`相對於盛唐大李杜（李白、杜甫），晚唐詩名最盛之李商隱與杜牧合稱「小李杜」。`},r),(t,n,r,i=`medium`)=>e({q:`李商隱詩歌以朦朧深邃、辭藻典雅著稱，其最膾炙人口的詩作系列為：`,c:`《無題》詩系列（抒寫相思隱曲與幽微情思）`,d:[`山水田園詩`,`邊塞軍旅詩`,`政治社論賦`],h:`身無彩鳳雙飛翼，心有靈犀一點通。`,e:`李商隱《無題》詩隱約朦朧、意境幽深、音律諧婉，為中國古典情詩之極致典範。`},r),(t,n,r,i=`medium`)=>e({q:`「一騎紅塵妃子笑，無人知是荔枝來。」晚唐杜牧這首絕句運用諷刺手法題詠歷史，其體裁為：`,c:`詠史懷古詩（《過華清宮絕句》）`,d:[`邊塞征戰詩`,`遊仙悼亡詩`,`送別酬贈詩`],h:`諷刺唐玄宗寵愛楊貴妃荒廢朝政。`,e:`杜牧詠史懷古詩長於借古諷今，以快馬送荔枝諷刺唐玄宗之奢靡亡國。`},r),(t,n,r,i=`medium`)=>e({q:`盛唐「邊塞詩派」以描寫塞外奇異壯麗風光與將士征戰生活見長，其代表詩人為：`,c:`高適、岑參、王昌齡、王之渙`,d:[`王維、孟浩然、儲光羲、常建`,`李白、賀知章、孟郊、賈島`,`韓愈、孟郊、賈島、李賀`],h:`高岑塞外詩豪放雄奇。`,e:`高適、岑參為盛唐邊塞詩派雙壁，王昌齡、王之渙亦以邊塞七絕享譽天下。`},r),(t,n,r,i=`medium`)=>e({q:`「黃沙百戰穿金甲，不破樓蘭終不還。」盛唐七絕聖手王昌齡在此展現的邊塞情懷為：`,c:`保家衛國、奮勇殺敵、不滅敵軍誓不罷休的慷慨英勇豪情`,d:[`厭倦征戰渴望早日解甲歸田的厭戰心理`,`對軍隊統帥指揮失當的嚴厲控訴`,`對大漠邊陲荒涼氣候的恐懼沮喪`],h:`誓破樓蘭之堅定報國決心。`,e:`王昌齡被譽為「七絕聖手」，詩句表現守邊將士浴血奮戰、誓死報國之豪邁氣概。`},r),(t,n,r,i=`medium`)=>e({q:`盛唐「山水田園詩派」繼承陶淵明、謝靈運傳統，其兩位領軍大詩人為：`,c:`王維 與 孟浩然（王孟）`,d:[`李白 與 杜甫`,`高適 與 岑參`,`元稹 與 白居易`],h:`王維孟浩然並稱王孟。`,e:`王維與孟浩然同為盛唐山水田園詩派最傑出代表，合稱「王孟」。`},r),(t,n,r,i=`medium`)=>e({q:`「文章本天成，妙手偶得之。」南宋愛國大詩人陸游這兩句詩闡述的創作境界為：`,c:`詩歌文章的最高境界是自然天成，技巧純熟至極時方能靈感迸發`,d:[`寫文章全憑偶然運氣，平時無須勤學苦練`,`古人文章早已寫盡，後人無法再創新篇`,`文章是神仙賜予的天賦，凡人不可企及`],h:`自然天成，鬼斧神工。`,e:`陸游強調藝術創作應達到超凡脫俗、順應自然、不著人工雕琢痕跡之神化境界。`},r),(t,n,r,i=`medium`)=>e({q:`元代雜劇奠基作家關漢卿被譽為「東方莎士比亞」，其最具代表性的悲劇名作為：`,c:`《竇娥冤》（《感天動地竇娥冤》）`,d:[`《西廂記》`,`《牡丹亭》`,`《長生殿》`],h:`血濺白練、六月飛雪、大旱三年。`,e:`關漢卿代表作《竇娥冤》深刻揭露封建官吏貪贓枉法與底層婦女所受之奇冤酷刑。`},r),(t,n,r,i=`medium`)=>e({q:`明代長篇章回小說四大奇書包括：`,c:`《三國演義》、《水滸傳》、《西遊記》、《金瓶梅》`,d:[`《紅樓夢》、《聊齋誌異》、《儒林外史》、《老殘遊記》`,`《史記》、《漢書》、《後漢書》、《三國志》`,`《封神演義》、《鏡花緣》、《隋唐演義》、《東周列國志》`],h:`三水西金為明代四大奇書。`,e:`明末文人李漁等評定之「四大奇書」為《三國演義》、《水滸傳》、《西遊記》、《金瓶梅》；《紅樓夢》為清代作品。`},r),(t,n,r,i=`medium`)=>e({q:`被公認為中國古代古典長篇章回小說最高峰的巨著為清代曹雪芹創作的：`,c:`《紅樓夢》（原名《石頭記》）`,d:[`《聊齋誌異》`,`《儒林外史》`,`《水滸傳》`],h:`滿紙荒唐言，一把辛酸淚。`,e:`曹雪芹《紅樓夢》以賈史王薛四大家族為背景，深刻展現封建社會由盛轉衰之悲劇史詩，為中國小說極品。`},r),(t,n,r,i=`medium`)=>e({q:`清代吳敬梓創作的諷刺長篇章回小說，深刻揭露科舉制度對讀書人靈魂之毒害與摧殘，此作品為：`,c:`《儒林外史》（如范進中舉）`,d:[`《聊齋誌異》`,`《老殘遊記》`,`《二十年目睹之怪現狀》`],h:`范進中舉喜極發瘋的故事即出自此書。`,e:`吳敬梓《儒林外史》為中國古代最卓越之諷刺長篇小說，生動刻畫八股科舉制度下士人之醜態百出。`},r),(t,n,r,i=`medium`)=>e({q:`清代蒲松齡用文言短篇小說形式寫狐仙鬼怪，借鬼狐故事寄託人間愛憎諷刺黑暗現實，此書為：`,c:`《聊齋誌異》`,d:[`《搜神記》`,`《世說新語》`,`《閱微草堂筆記》`],h:`寫鬼寫妖高人一等，刺貪刺虐入木三分。`,e:`郭沫若評蒲松齡《聊齋誌異》：「寫鬼寫妖高人一等，刺貪刺虐入木三分。」`},r),(t,n,r,i=`medium`)=>e({q:`「五四新文化運動」中發表中國現代文學史上第一篇白話短篇小說《狂人日記》的文豪為：`,c:`魯迅（周樹人）`,d:[`胡適`,`陳獨秀`,`郭沫若`],h:`以狂人視角揭露吃人的禮教。`,e:`1918年魯迅於《新青年》發表《狂人日記》，借狂人日記形式發出對封建禮教「吃人」本質之深刻控訴。`},r),(t,n,r,i=`medium`)=>e({q:`現代散文名篇《背影》描繪父親在浦口火車站穿過鐵道買橘子的感人至深場景，作者為：`,c:`朱自清`,d:[`徐志摩`,`郁達夫`,`老舍`],h:`肥胖的身子蹣跚地走過去買橘子。`,e:`朱自清《背影》以樸素細膩之白描手法刻畫父子深情，感動數代讀者。`},r),(t,n,r,i=`medium`)=>e({q:`「悄悄的我走了，正如我悄悄的來；我揮一揮衣袖，不帶走一片雲彩。」這首現代詩《再別康橋》作者為：`,c:`徐志摩（新月派代表詩人）`,d:[`聞一多`,`戴望舒`,`余光中`],h:`輕輕的我走了，正如我輕輕的來。`,e:`徐志摩為現代新月詩派核心代表，詩作追求音樂美、繪畫美與建築美，《再別康橋》為其巔峰之作。`},r),(t,n,r,i=`medium`)=>e({q:`臺灣當代文學巨擘余光中先生，其詩文創作兼備古典與現代風範，名作《鄉愁》以何種意象象徵兩岸阻隔？`,c:`郵票、船票、墳墓、一灣淺淺的海峽`,d:[`大樹、飛鳥、河流、落日`,`長劍、戰馬、旌旗、烽火`,`信紙、電話、車票、高山`],h:`小小的郵票、窄窄的船票、矮矮的墳墓、淺淺的海峽。`,e:`余光中《鄉愁》連用四個意象，將抽象深厚之故土鄉愁具象化為具體可感之四種載體。`},r),(t,n,r,i=`medium`)=>e({q:`琦君女士的散文以溫厚深情、追憶童年與故鄉風物見長，其著名自傳體散文代表作包括：`,c:`《髻》、《橘子紅了》、《煙愁》`,d:[`《城南舊事》`,`《汪洋中的一條船》`,`《寒夜三部曲》`],h:`描寫母親與姨娘之髮髻恩怨。`,e:`琦君以溫婉誠摯之筆觸描摹浙東故鄉風情與家庭親情，名篇《髻》深刻探討女性命運與歲月寬容。`},r),(t,n,r,i=`medium`)=>e({q:`孔子思想的核心概念是「仁」，下列論語文句中最能體現「仁」的實踐精神的是：`,c:`克己復禮為仁（一日克己復禮，天下歸仁焉）`,d:[`食不厭精，膾不厭細`,`君子不重則不威`,`未知生，焉知死`],h:`克制自己的私欲，回歸禮節規範。`,e:`孔子回答顏淵問仁：「克己復禮為仁」，強調自律克己使言行合乎禮義規範。`},r),(t,n,r,i=`medium`)=>e({q:`孔子提出儒家處理人際關係的黃金法則「推己及人」，即所謂「恕道」，其具體表述為：`,c:`己所不欲，勿施於人`,d:[`人不知而不慍`,`敏而好學，不恥下問`,`三人行，必有我師焉`],h:`自己不喜歡的事情，不要強加在別人身上。`,e:`孔子指出「恕」是一生可以奉行之準則：「其恕乎！己所不欲，勿施於人。」`},r),(t,n,r,i=`medium`)=>e({q:`孟子主張「人性本善」，認為人生來就具備四種先天的善端，其中「惻隱之心」是何種德性的發端？`,c:`仁之端也`,d:[`義之端也`,`禮之端也`,`智之端也`],h:`看見幼童將掉入水井自然產生不忍人之心。`,e:`孟子：「惻隱之心，仁之端也；羞惡之心，義之端也；辭讓之心，禮之端也；是非之心，智之端也。」`},r),(t,n,r,i=`medium`)=>e({q:`孟子提出民本主義政治哲學，其關於國家要素重要性的著名論斷為：`,c:`民為貴，社稷次之，君為輕`,d:[`君為貴，民為輕，社稷次之`,`社稷為貴，君次之，民為輕`,`君權神授，萬民服從`],h:`人民地位最為尊貴崇高。`,e:`孟子《盡心下》提出「民為貴，社稷次之，君為輕」，是中國古代民本思想之最高峰。`},r),(t,n,r,i=`medium`)=>e({q:`「魚，我所欲也；熊掌，亦我所欲也。二者不可得兼，舍魚而取熊掌者也。」孟子以此譬喻引出何種崇高價值抉擇？`,c:`生，亦我所欲也；義，亦我所欲也。二者不可得兼，舍生而取義者也`,d:[`名，亦我所欲也；利，亦我所欲也。舍名而取利`,`富，亦我所欲也；貴，亦我所欲也。舍貴而取富`,`智，亦我所欲也；勇，亦我所欲也。舍智而取勇`],h:`捨生取義。`,e:`孟子以魚與熊掌之取捨比喻生命與道義衝突時，應堅持操守，不惜捨生取義。`},r),(t,n,r,i=`medium`)=>e({q:`老子是道家學派創始人，其哲學核心主張「無為而治」，其所謂「無為」之真意為：`,c:`順應自然規律，不妄作妄為、不以主觀偏見強行干涉萬物生長`,d:[`消極怠惰、徹底放棄任何作為躺平擺爛`,`毀滅一切文明回歸原始野蠻狀態`,`閉門修煉尋求肉體長生不老`],h:`道法自然，不強行妄為。`,e:`老子「無為」乃「無妄為」，即順應客觀自然法則，破除主觀執念與權力妄為。`},r),(t,n,r,i=`medium`)=>e({q:`「上善若水。水善利萬物而不爭，處眾人之所惡，故幾於道。」老子在此盛讚水具備何種崇高品格？`,c:`謙遜柔和、利澤萬物卻不爭名奪利的崇高品德`,d:[`水滴石穿具備巨大破壞衝擊力`,`水能載舟亦能覆舟之無常變化`,`水流奔騰不息追求個人利益`],h:`利萬物而不爭，處卑下之地。`,e:`老子以水喻道，讚揚水滋潤萬物卻甘居下流、謙遜不爭之至善品格。`},r),(t,n,r,i=`medium`)=>e({q:`「禍兮福之所倚，福兮禍之所伏。」老子這句名言深刻揭示了何種哲理？`,c:`事物相互對立又相互依存、在一定條件下互相轉化的辯證法則`,d:[`命運早已註定一切努力皆為徒勞`,`災禍臨頭必然永遠無法翻身消除`,`追求福報必須多燒香祭拜神靈`],h:`禍福相生相轉化。`,e:`老子指出矛盾對立雙方具有動態轉化之規律，居安思危，處逆境莫絕望。`},r),(t,n,r,i=`medium`)=>e({q:`莊子是道家學派集大成者，其哲學追求個體精神的絕對自由，其代表作開篇《逍遙遊》的核心主旨為：`,c:`擺脫外在名韁利鎖與形骸束縛，達到無待於外的純粹精神自由之境`,d:[`修煉高深輕功翱翔於九天之上`,`追求長壽不老成為仙界神人`,`經商致富遊歷天下名山大川`],h:`乘天地之正，而御六氣之辯，以遊無窮者，彼且惡乎待哉！`,e:`莊子《逍遙遊》倡導超越世俗功名利祿之拘牽，達到「無己、無功、無名」之絕對精神自由。`},r),(t,n,r,i=`medium`)=>e({q:`《莊子·齊物論》中著名的「莊周夢蝶」寓言，闡述了何種哲學思考？`,c:`物我合一、萬物齊平、化解主客對立的「物化」哲思境界`,d:[`睡眠品質不佳容易產生幻覺夢境`,`蝴蝶為昆蟲蛻變生物進化範例`,`人生如夢應當及時行樂揮霍生命`],h:`不知周之夢為胡蝶與？胡蝶之夢為周與？`,e:`莊子以夢蝶打破自我與外物之僵化界限，展現超越世俗偏見、萬物齊一之玄妙境界。`},r),(t,n,r,i=`medium`)=>e({q:`荀子是戰國末期儒家大師，與孟子「性善論」相對，荀子提出了著名的：`,c:`「性惡論」（人之性惡，其善者偽也）`,d:[`性無善無惡論`,`性三品說`,`性超善惡論`],h:`偽指人為後天學習教化修養。`,e:`荀子主張人性本有惡的欲望傾向（性惡），必須透過後天禮樂教化（偽，人為努力）來導正行善。`},r),(t,n,r,i=`medium`)=>e({q:`荀子《勸學》開宗明義提出「學不可以已」，並以「青，取之於藍，而青於藍；冰，水為之，而寒於水」說明：`,c:`人只要堅持後天學習與修養，就能不斷超越自我、超越前人`,d:[`大自然的顏色變化豐富多彩`,`物理化學狀態改變的自然規律`,`後代人必然比前代人愚鈍軟弱`],h:`持之以恆學習使道德學問大幅提升。`,e:`荀子以此形象比喻學習與教化能使人性本質發生質的昇華飛躍。`},r),(t,n,r,i=`medium`)=>e({q:`韓非子是先秦法家思想集大成者，他總結了前期法家理論，提出了哪三者合一的統治權術？`,c:`「法」（法令規章）、「術」（操縱駕馭臣下之權術）、「勢」（君王威勢權位）`,d:[`仁、義、禮`,`道、德、無為`,`兼愛、非攻、尚賢`],h:`法術勢三者兼備不可偏廢。`,e:`韓非融合商鞅之「法」、申不害之「術」、慎到之「勢」，構建了法家專制中央集權之完整理論體系。`},r),(t,n,r,i=`medium`)=>e({q:`墨家學派創始人墨子，其哲學核心主張為：`,c:`「兼愛」（無等級差等的博愛） 與 「非攻」（反對侵略戰爭）`,d:[`克己復禮 與 尊尊親親`,`順應自然 與 清靜無為`,`嚴刑峻法 與 專制集權`],h:`兼相愛，交相利，非攻。`,e:`墨子反對儒家有等級的仁愛，主張天下所有人互愛互利（兼愛），並堅決反對不義攻伐（非攻）。`},r),(t,n,r,i=`medium`)=>e({q:`墨家提出「節葬」、「節用」，其背後的思想理念為：`,c:`反對厚葬久喪等繁瑣浪費的虛禮，主張節約資財發展生產以造福百姓`,d:[`不重視長輩孝道倫理`,`追求守財奴式的積累財富`,`認為死後靈魂將灰飛煙滅無須祭祀`],h:`去無用之費，聖王之道也。`,e:`墨子代表底層勞動平民利益，強烈反對貴族統治階層鋪張浪費之奢靡厚葬，倡導儉約務實。`},r),(t,n,r,i=`medium`)=>e({q:`「道可道，非常道；名可名，非常名。」《老子》開篇闡述的「道」是指：`,c:`宇宙萬物最原初、超越語言概念描述的根本總源頭與客觀規律`,d:[`古代帝王行走的御道大道`,`道德禮儀之規範條目`,`道教祈福修仙之法術法門`],h:`可以用言語說清楚的道，就不是永恆常在的大道。`,e:`老子認為「道」是萬物化生運行的終極本體，超乎感官與語言局限，是形而上的永恆存在。`},r),(t,n,r,i=`medium`)=>e({q:`孔子被尊稱為「萬世師表」，其在教育上的兩大劃時代貢獻理念為：`,c:`「有教無類」（打破貴族壟斷，平民皆可受教） 與 「因材施教」`,d:[`嚴格實施階級考試分流淘汰`,`只收貴族王室子弟入學`,`強制學生死記硬背統一教條`],h:`教育對象不分貴賤貧富，教學方法依學生資質靈活調整。`,e:`孔子首開平民私學之風，「有教無類」普及教育，「因材施教」啟發心智，奠定中華教育傳統。`},r),(t,n,r,i=`medium`)=>e({q:`「三人行，必有我師焉。擇其善者而從之，其不善者而改之。」這段話展現的求學態度為：`,c:`謙遜好學，隨時隨地向身邊人學習優點，並以他人過失自我反省戒惕`,d:[`出門必須三人同行結伴以保安全`,`任何三個人之中必然有一個專業教師`,`盲目聽從別人的所有意見指引`],h:`善者從之，不善者改之。`,e:`孔子教導弟子保持虛懷若谷之求學精神，將生活環境化為終身學習與反躬自省之課堂。`},r),(t,n,r,i=`medium`)=>e({q:`孟子論政治得失：「得道者多助，失道者寡助。寡助之至，親戚畔之；多助之至，天下順之。」其核心宗旨為：`,c:`施行仁政爭取民心是國家強盛與政權穩固的根本決定因素`,d:[`軍事要塞與武器裝備是決定戰爭勝負的唯一關鍵`,`國君必須依靠強大外國軍事同盟援助`,`君主必須重用親戚宗室以防叛變`],h:`天時不如地利，地利不如人和。`,e:`孟子強調「人和」高於天時地利，施行仁政合乎正道方能獲得天下萬民之真心擁護。`},r),(t,n,r,i=`medium`)=>e({q:`「吾生也有涯，而知也無涯。以有涯隨無涯，殆已！」莊子在此表達的認知觀點為：`,c:`人的肉體生命有限，若企圖以有限精力盲目窮追無窮外在瑣碎知識，必然疲憊不堪困頓受害`,d:[`因此人應當放棄讀書學習徹底廢棄文化知識`,`知識越淵博壽命必然越短暫`,`鼓勵人們夜以繼日不眠不休死讀書`],h:`知其涯與無涯，追求生命精神之本真而非名利知見之執著。`,e:`莊子警惕人們切勿陷入以有限生命逐求無限外在物欲與枝微知見之泥淖，應回歸生命本真。`},r),(t,n,r,i=`medium`)=>e({q:`荀子《天論》提出「從天而頌之，孰與制天命而用之！」其所展現的卓越哲學思想為：`,c:`人定勝天：與其盲目順從頌揚自然，不如掌握並利用自然客觀規律為人類造福`,d:[`人類必須無休止掠奪開採自然資源`,`天命完全決定了一切人事成敗`,`崇拜祭拜天神以祈求風調雨順`],h:`制天命而用之，掌握客觀規律發揮主觀能動性。`,e:`荀子破除古代天命神學迷信，將自然（天）視為不具意志之客觀存在，提出人類應掌握利用自然規律。`},r),(t,n,r,i=`medium`)=>e({q:`「工欲善其事，必先利其器。」孔子這句名言強調處事原則為：`,c:`要做好一件事，必須先做好充分的準備工作與工具完備`,d:[`工匠只能使用鋒利的鐵器工具`,`只要有良好的工具就無須投入努力`,`技術工人地位高於學者讀書人`],h:`磨好工具做好萬全準備。`,e:`比喻欲成就事業，必須事先具備充實的專業知識、技能與完備工具。`},r),(t,n,r,i=`medium`)=>e({q:`「臨淵羨魚，不如退而結網。」《淮南子》這則名言告誡世人：`,c:`空有美好願望毫無意義，必須落實於腳踏實地的具體行動`,d:[`站在河邊看魚非常危險容易滑落`,`捕魚必須先編織堅韌的漁網`,`不要羨慕富貴人家的悠閒生活`],h:`落實於行動才能達成目標。`,e:`比喻與其只站在河岸邊羨慕水中游魚，不如退回家中認真織好漁網捕捉，強調實幹篤行。`},r),(t,n,r,i=`medium`)=>e({q:`「尺有所短，寸有所長；物有所不足，智有所不明。」這句話闡明的哲理是：`,c:`人事物各有其長處與短處，切莫以偏概全盲目自大或自輕`,d:[`測量長度時尺子必定比寸準確`,`聰明人的智慧永遠無法被理解`,`短處永遠無法轉化為優勢`],h:`寸長尺短，各有所宜。`,e:`楚辭名言指出萬物各具特長與局限，強調知人善任、揚長避短之謙遜包容智慧。`},r),(t,n,r,i=`medium`)=>e({q:`「滿招損，謙受益。」《尚書》中這句名言所闡述的道德戒律為：`,c:`自滿驕傲必然招致禍患損失，謙遜虛懷必然獲得福澤助益`,d:[`水杯裝滿水容易溢出來造成浪費`,`過度謙虛等同於虛偽矯飾`,`利益面前人人應當爭先恐後`],h:`驕者必敗，謙卑獲益。`,e:`中華傳統文化核心訓誡，警惕人戒驕戒躁，唯有謙遜自持方能長久安泰進步。`},r),(t,n,r,i=`medium`)=>e({q:`孟子曰：「窮則獨善其身，達則兼善天下。」這句話展現的儒家士人擔當為：`,c:`不得志時修身立德保持操守，得志掌權時推行仁政造福普天下百姓`,d:[`貧窮時只能考慮自己溫飽不顧他人`,`發財致富後才可以兼營天下商業`,`只要個人生活富足即可退隱不問世事`],h:`無論逆境順境皆堅守道義擔當。`,e:`士人在不得志時退修德行，在位達濟時推展大同，為古代知識分子之處世準則。`},r),(t,n,r,i=`medium`)=>e({q:`「塞翁失馬，安知非福」出自先秦兩漢哪一部著名道家典籍？`,c:`《淮南子·人間訓》`,d:[`《論語》`,`《孟子》`,`《韓非子》`],h:`淮南王劉安門客編撰之淮南子。`,e:`「塞翁失馬」之典故出自西漢淮南王劉安主持編纂之道家巨著《淮南子·人間訓》。`},r),(t,n,r,i=`medium`)=>e({q:`孔子論君子與小人之辨別：「君子坦蕩蕩，小人長戚戚。」其中「長戚戚」是指：`,c:`心胸狹隘、斤斤計較名利得失而經常憂懼不安`,d:[`身材矮小長相猥瑣`,`說話聲音微弱哭泣不停`,`長相凶惡令人望而生畏`],h:`常憂名利得失戚戚不安。`,e:`孔子指出君子光明磊落內心泰然，小人患得患失心胸局促，終日陷於焦慮患失之中。`},r),(t,n,r,i=`medium`)=>e({q:`「騏驥一躍，不能十步；駑馬十駕，功在不舍。」荀子《勸學》強調的成功關鍵為：`,c:`持之以恆、堅持不懈的恆心毅力，勝過單純依賴過人天賦`,d:[`千里馬奔馳速度不如老弱馬匹`,`十步之內的距離無法展現奔跑技巧`,`騎馬打仗必須選擇劣馬以策安全`],h:`功在不舍，貴在堅持。`,e:`荀子以此形象比喻資質平庸者只要堅持不懈努力奮發，終能超越天才取得卓越成就。`},r),(t,n,r,i=`medium`)=>e({q:`老子曰：「天下難事，必作於易；天下大事，必作於細。」這句話給現代人的啟示為：`,c:`要成就宏偉目標，必須從最容易、最微細的基礎環節做起，注重細節累積`,d:[`困難的事情往往很容易解決`,`只要注重瑣碎小事無須立定遠大志向`,`大事由大人物做，小事留給普通人`],h:`合抱之木生於毫末，九層之台起於累土。`,e:`老子告誡人們處事切莫好高騖遠，天下宏大偉業皆由無數微小細節與基礎步驟踏實累積而成。`},r),(t,n,r,i=`medium`)=>e({q:`范仲淹《岳陽樓記》貫穿全文的核心政治抱負與人生境界為：`,c:`「先天下之憂而憂，後天下之樂而樂」`,d:[`「登斯樓也，則有心曠神怡，寵辱偕忘」`,`「居廟堂之高則憂其民，處江湖之遠則憂其君」`,`「微斯人，吾誰與歸」`],h:`憂在天下人之前，樂在天下人之後。`,e:`范仲淹超越個人悲喜榮辱，將家國天下百姓福祉置於個人得失之上，展現儒家崇高擔當。`},r),(t,n,r,i=`medium`)=>e({q:`歐陽脩《醉翁亭記》結尾揭示作者與民同樂之旨趣，其思想最高層次在於：`,c:`「醉能同其樂，醒能述以文者，太守也。」（太守樂其樂）`,d:[`「山水之樂，得之心而寓之酒也」`,`「禽鳥知山林之樂，而不知人之樂」`,`「負者歌於途，行者休於樹」`],h:`太守不僅陶醉於山水，更因百姓安居樂業而自得其樂。`,e:`歐陽脩治理滁州政通人和，在與民同遊中體會「民樂即我樂」之與民同樂境界。`},r),(t,n,r,i=`medium`)=>e({q:`韓愈《師說》開宗明義界定教師的核心職責為：`,c:`「師者，所以傳道、受業、解惑也。」`,d:[`「生乎吾前，其聞道也固先乎吾，吾從而師之」`,`「巫醫樂師百工之人，不恥相師」`,`「弟子不必不如師，師不必賢於弟子」`],h:`傳授大道、教授學業、排解困惑。`,e:`韓愈首度精準定義教師的三大本質使命：傳承倫理道統、傳授文化專業、解答人生學業疑難。`},r),(t,n,r,i=`medium`)=>e({q:`韓愈《師說》中提出「道之所存，師之所存也」的擇師標準，其革新意義在於：`,c:`打破封建門第世俗等級觀念，唯以「是否掌握真理道義」為拜師依歸`,d:[`只有年齡比自己大者才可以當老師`,`只有官爵高於自己者才有資格受教`,`富貴之家的子弟無須向貧窮讀書人求教`],h:`無貴無賤，無長無少，道之所存，師之所存也。`,e:`韓愈力斥士大夫階層恥於從師之惡習，主張在真理與道義面前人人平等，達者為師。`},r),(t,n,r,i=`medium`)=>e({q:`蘇軾《前赤壁賦》中，蘇子向客闡述「變與不變」的宇宙辯證哲理，指出：`,c:`「自其變者而觀之，則天地曾不能以一瞬；自其不變者而觀之，則物與我皆無盡也」`,d:[`「寄蜉蝣於天地，渺滄海之一粟」`,`「哀吾生之須臾，羨長江之無窮」`,`「挾飛仙以遨遊，抱明月而長終」`],h:`從變化角度看天地瞬息萬變，從不變角度看萬物與我生命永恆延續。`,e:`蘇軾借月圓月缺與江水流逝之現象，闡釋超脫生死得失、順應自然規律之豁達宇宙觀。`},r),(t,n,r,i=`medium`)=>e({q:`諸葛亮在《出師表》中向後主劉禪提出的三條治國核心建議為：`,c:`廣開言路（開張聖聽）、嚴明賞罰（陟罰臧否，不宜異同）、親賢遠佞（親賢臣，遠小人）`,d:[`增收賦稅、厲兵秣馬、閉關自守`,`聯吳抗魏、討伐東吳、獨攬大權`,`大興土木、興建宮室、求神問卜`],h:`開張聖聽、賞罰分明、親賢遠佞。`,e:`諸葛亮北伐前夕懇切叮嚀後主內政修明，此三策為蜀漢興亡存續之關鍵綱領。`},r),(t,n,r,i=`medium`)=>e({q:`陶淵明《桃花源記》中描繪的理想桃花源社會，其核心生活圖景為：`,c:`「阡陌交通，雞犬相聞。其中往來種作，男女衣著，悉如外人。黃髮垂髫，並怡然自樂。」`,d:[`宮殿金碧輝煌，軍隊威武嚴整，君主統治森嚴`,`商賈雲集市場喧囂，人人爭相追求巨額利潤`,`隱士各自辟穀修仙，長生不老騰雲駕霧`],h:`沒有賦稅戰亂、自給自足、純樸安樂的世外桃源。`,e:`陶淵明藉桃花源寄託反對戰亂壓迫、嚮往人人平等自由、與世無爭和諧共處之社會理想。`},r),(t,n,r,i=`medium`)=>e({q:`周敦頤《愛蓮說》中「出淤泥而不染，濯清漣而不妖」盛讚蓮花象徵：`,c:`君子處於污濁世俗環境中，仍能潔身自好、堅守高潔純真之品德操守`,d:[`蓮花具有強大淨化水質之生物學特性`,`追求名利富貴卻不招搖過市之處世之道`,`出世避世徹底脫離人類社會`],h:`身處污泥卻保持純潔潔白。`,e:`以蓮花自況，象徵士人不隨波逐流、出污泥而不染之獨立高潔人格。`},r),(t,n,r,i=`medium`)=>e({q:`劉禹錫《陋室銘》以「斯是陋室，惟吾德馨」總領全篇，其表達的人生追求為：`,c:`不注重居室物質條件之簡陋，唯以高尚品德修養與高雅志趣自得其樂`,d:[`抱怨朝廷俸祿微薄居住條件惡劣`,`炫耀自己結交高官貴族名流`,`提倡刻意自虐過貧苦生活`],h:`陋室不陋，因德馨而名。`,e:`劉禹錫遭貶謫仍傲骨嶙峋，以安貧樂道、高潔孤傲之品格展現超拔的精神力量。`},r),(t,n,r,i=`medium`)=>e({q:`歸有光《項脊軒志》以「百年老屋，塵泥滲漉，雨澤下注」開篇，全篇動人深情在於：`,c:`借項脊軒之修葺興廢，細膩追憶祖母、母親與亡妻之深摯親情與讀書志向`,d:[`描寫江南園林建築設計工法與修繕技術`,`記錄家族爭奪財產興訟對簿公堂之醜惡`,`抒發科舉考場連年高中狀元之志得意滿`],h:`庭有枇杷樹，吾妻死之年所手植也，今已亭亭如蓋矣。`,e:`明代歸有光抒情散文以白描筆法寫日常家庭瑣事，借老屋枇杷寄託生死不渝之悼亡深情。`},r),(t,n,r,i=`medium`)=>e({q:`《世說新語·德行》中「管寧割席」的故事，表現了管寧何種人格特質：`,c:`絕不與貪圖富貴名利、心浮氣躁之人同流合汙之堅定原則操守`,d:[`小氣吝嗇不願與同窗分享坐席草席`,`自私自利缺乏團結互助精神`,`性格孤僻無法與他人正常溝通`],h:`子非吾友也，割席分坐。`,e:`見公卿軒冕過門，華歆廢書出觀而管寧讀書自若，管寧割席斷交，展現高尚之志向抉擇。`},r),(t,n,r,i=`medium`)=>e({q:`司馬遷《史記·項羽本紀》「鴻門宴」中，劉邦得以絕處逢生化險為夷的關鍵因素在於：`,c:`張良卓越機智謀劃、樊噲勇猛護衛，加上項羽優柔寡斷、不聽范增殺敵良言`,d:[`劉邦軍隊武力遠遠壓倒項羽大軍`,`項羽在酒宴上突然心臟病發作昏迷`,`秦朝殘餘勢力突襲鴻門軍營解圍`],h:`項羽項王為人仁而優柔寡斷，范增數目項王舉所佩玉玦以示之者三，項王默然不應。`,e:`鴻門宴生動刻畫劉邦君臣之機智謹慎善變，與項羽自矜功伐、優柔寡斷之悲劇性格反差。`},r),(t,n,r,i=`medium`)=>e({q:`《左傳·曹劌論戰》中曹劌指出長勺之戰取勝的軍事心理規律為：`,c:`「夫戰，勇氣也。一鼓作氣，再而衰，三而竭。彼竭我盈，故克之。」`,d:[`兵者詭道也，兵貴神速不貴久`,`知己知彼，百戰不殆`,`窮寇勿追，背水一戰`],h:`一鼓作氣，掌握士氣衰竭之反攻時機。`,e:`曹劌精闢分析戰場士氣變化動態，利用齊軍士氣三通戰鼓後衰竭，一舉反擊制勝。`},r),(t,n,r,i=`medium`)=>e({q:`李密《陳情表》中打動晉武帝解除其仕官徵召的至情名句為：`,c:`「臣無祖母，無以至今日；祖母無臣，無以終餘年。母孫二人，更相為命。」`,d:[`「臣欲奉詔奔馳，則劉病日篤；欲苟順私情，則告訴不許」`,`「生當隕首，死當結草」`,`「外無期功強近之親，內無應門五尺之童」`],h:`祖孫相依為命，盡孝於祖母之後再盡忠於朝廷。`,e:`李密以至誠至孝之血淚文字化解政治猜忌，展現孝老敬親感人肺腑之孝道光輝。`},r),(t,n,r,i=`medium`)=>e({q:`王羲之《蘭亭集序》由「群賢畢至，少長咸集」之遊目騁懷，轉向對生命之深沉思考：`,c:`「死生亦大矣，豈不痛哉！...後之視今，亦猶今之視昔。」`,d:[`「天朗氣清，惠風和暢」`,`「仰觀宇宙之大，俯察品類之盛」`,`「一死生為虛誕，齊彭殤為妄作」`],h:`生死亦大，批判莊子齊彭殤為虛誕，珍惜有限生命。`,e:`王羲之批判老莊虛無思想，直面生命的短暫與消逝，以筆墨寄託千古相通之生死悲歡。`},r),(t,n,r,i=`medium`)=>e({q:`柳宗元《始得西山宴遊記》中「始得」二字的深層寓意在於：`,c:`唯有登臨西山浩蕩高聳之絕頂，方始真正體會心凝形釋、與天地大自然合而為一之超然解脫`,d:[`第一次找到通往西山的秘密捷徑`,`首次在西山購買到美味之美酒佳餚`,`終於獲得朝廷赦免得以返回京城`],h:`自此始，心凝形釋，與萬化冥合。`,e:`柳宗元遭貶永州，登西山而感悟自身傲世獨立之氣節，借西山之奇特高峻抒發不與世俗同流之精神境界。`},r),(t,n,r,i=`medium`)=>e({q:`蘇轍在《上樞密韓太尉書》中闡述寫作之道的核心觀點為：`,c:`「文者，氣之所形。然文不可以學而能，氣可以養而致。」主張壯遊開拓胸襟以養浩然之氣`,d:[`文章全靠在家閉門苦讀默寫先賢古籍`,`寫文章必須追求華麗辭藻與駢偶對仗`,`文章寫作只能依靠天生稟賦，後天毫無作用`],h:`養氣以成文，遊歷名山大川以充實浩然之氣。`,e:`蘇轍繼承孟子養氣說與司馬遷壯遊傳統，提出文學創作應深入廣闊現實以涵養胸襟氣度。`},r),(t,n,r,i=`medium`)=>e({q:`《戰國策·馮諼客孟嘗君》中馮諼為孟嘗君營造的「三窟」不包括下列何者？`,c:`暗中招募刺客奪取齊王王位`,d:[`在薛地燒毀債券市義收買民心`,`遊說魏惠王重金延攬孟嘗君提高身價`,`在薛地建立齊國宗廟確保薛地安全永固`],h:`狡兔三窟：市義於薛、挾魏自重、立宗廟於薛。`,e:`馮諼以遠見卓識為孟嘗君營造市義收民心、引魏自重、建宗廟於封地三條退路，展現戰國策士之戰略眼光。`},r),(t,n,r,i=`medium`)=>e({q:`司馬光主持編纂《資治通鑑》的名垂千古之主旨意圖，宋神宗命名之深意為：`,c:`「鑑於往事，有資於治道」（以歷史經驗興衰成敗作為治國理政之借鏡參考）`,d:[`專門記載帝王後宮生活秘史供人消遣`,`編排歷史事件神仙鬼怪奇聞異事`,`純粹考證古代官服制度與度量衡標準`],h:`資助治理國政之歷史鏡子。`,e:`《資治通鑑》為中國最大之編年體通史，旨在總結歷代治亂興衰得失，為統治者提供治國借鏡。`},r),(t,n,r,i=`medium`)=>e({q:`歐陽脩在《縱囚論》中大膽質疑唐太宗「縱囚歸家約期自來就死」之舉，其核心論點為：`,c:`斥責此舉違背常情，乃「上下交相賊」之沽名釣譽政治作秀，治國應合乎人情常道`,d:[`盛讚唐太宗仁德感動天地使死囚洗心革面`,`主張廢除死刑全面釋放監獄犯人`,`認為死囚皆為冤獄應予平反昭雪`],h:`違背人情常理以求虛名，非聖人之法。`,e:`歐陽脩展現宋代理性批判精神，指出治國應本於常情常理與嚴明法度，不應依靠極端偶發之造作名聲。`},r),(t,n,r,i=`medium`)=>e({q:`方孝孺在明成祖篡位時寧死不屈，其所作散文《指病》藉一隻手指的潰爛小疾告誡天下：`,c:`天下之患莫大於思慮不及與輕視微疾，大禍常發酵於忽視微小細節之盲目樂觀`,d:[`醫生手術技術不精容易導致截肢`,`天氣寒冷注意手部保暖預防凍瘡`,`指甲修剪過深容易引發細菌感染`],h:`天下之病，常起於微而至於不可救。`,e:`方孝孺借治指疾之醫理，深刻剖析政治危機往往肇始於君王對微小弊端之漠視縱容。`},r),(t,n,r,i=`medium`)=>e({q:`柳宗元《種樹郭橐駝傳》借橐駝種樹之理「順木之天，以致其性」諷刺：`,c:`官吏好大喜功、政令繁苛、朝令夕改擾亂百姓生計之「長人者好煩其令」`,d:[`林業部門未按規定栽植樹木造成森林退化`,`駝背身障人士在社會遭受不公歧視對待`,`農民耕作技巧不足無法提高糧食產量`],h:`順應自然規律，切莫愛之太殷憂之太勤。`,e:`柳宗元借種樹寓言深刻揭露苛政害民本質，主張治國養民應順應民情自然發展、輕徭薄賦。`},r),(t,n,r,i=`medium`)=>e({q:`《古文觀止》評韓愈《祭十二郎文》與諸葛亮《出師表》、李密《陳情表》並稱為中國古代：`,c:`抒情散文之千古至情三大名篇（不哭者不忠、不孝、不慈愛）`,d:[`軍事作戰之三大兵書戰略綱要`,`科舉考試之三大標準八股範文`,`駁斥異端之三大論辯檄文`],h:`出師表涕泣言忠，陳情表泣血言孝，祭十二郎文至情言哀。`,e:`古人評：「讀出師表不墮淚者不忠，讀陳情表不墮淚者不孝，讀祭十二郎文不墮淚者不慈愛。」`},r),(t,n,r,i=`medium`)=>e({q:`杜牧《阿房宮賦》結尾發出振聾發聵的歷史警鐘：「秦人不暇自哀，而後人哀之；後人哀之而不鑑之，亦使後人而復哀後人也！」其創作宗旨為：`,c:`借秦朝奢靡殘暴迅速亡國之歷史慘痛教訓，諷諫唐朝統治者切莫重蹈覆轍`,d:[`讚揚阿房宮建築工程規模空前絕後極盡奢華`,`哀嘆項羽焚燒阿房宮毀滅古代建築文化瑰寶`,`純粹考證秦代宮廷建築佈局與風水特徵`],h:`借古諷今，警告唐朝統治者戒奢從儉。`,e:`杜牧鋪敘阿房宮之極度奢華與百姓之塗炭，終結於興亡歷史反思，為借古諷今賦體巔峰。`},r),(t,n,r,i=`medium`)=>e({q:`黃宗羲在《明夷待訪錄·原君》中猛烈批判君主專制制度，提出劃時代之震撼思想：`,c:`「為天下之大害者，君而已矣！」指出君主以天下之利盡歸於己，視天下為私產`,d:[`君主乃上天之子，其權力神聖不可侵犯質疑`,`人民應當無條件服從君主一切殘暴指令統治`,`應當全面廢除法律回歸無政府狀態`],h:`天下為主，君為客。`,e:`黃宗羲被譽為「中國思想啟蒙之父」，深刻揭露二千年封建君主專制視天下為個人私產之腐朽本質。`},r),(t,n,r,i=`medium`)=>e({q:`顧炎武在《日知錄》中精準區分「亡國」與「亡天下」之本質差別，其名言為：`,c:`「易姓改號，謂之亡國；仁義充塞，而至於率獸食人，人將相食，謂之亡天下。天下興亡，匹夫有責！」`,d:[`國破山河在，城春草木深`,`寧為玉碎，不為瓦全`,`得道多助，失道寡助`],h:`保國是朝廷肉食者之事，保天下道德文化文明則是全體匹夫之責。`,e:`顧炎武指出政權更替為亡國，道德文明斷絕為亡天下，提出知識分子與全體國民守護文明道統之崇高使命。`},r),(t,n,r,i=`medium`)=>e({q:`姚鼐為清代「桐城派」散文集大成者，其名篇《登泰山記》展現了桐城派何種文風特色：`,c:`義理、考證、辭章三者兼備，語言雅潔精煉、記事生動自然`,d:[`生搬硬套西方現代語言修辭`,`堆砌難懂奇僻字句標榜學問`,`純粹議論政治不涉自然山水描摹`],h:`泰山日出壯麗雪景，雅潔純粹。`,e:`姚鼐主張散文應融合義理、考據、辭章，《登泰山記》以洗鍊雅健之筆墨描繪日出冰雪奇景，為山水小品典範。`},r),(t,n,r,i=`medium`)=>e({q:`宋代大儒張載提出被譽為「橫渠四句」之士人終極使命擔當，名垂千古之名句為：`,c:`「為天地立心，為生民立命，為往聖繼絕學，為萬世開太平！」`,d:[`「修身、齊家、治國、平天下」`,`「正心、誠意、格物、致知」`,`「格物致知，知行合一」`],h:`天地立心、生民立命、往聖繼絕學、萬世開太平。`,e:`張載橫渠四句以浩蕩宏博之氣魄，構建了中華儒家知識分子對天人、社會、歷史道統與未來和平之終極責任綱領。`},r),(t,n,r,i=`medium`)=>e({q:`王安石在《傷仲永》中記載神童方仲永「自是指物作詩立就」最終卻「泯然眾人矣」，其深刻教訓在於：`,c:`即使具備過人先天稟賦，若缺乏後天持續刻苦學習受教，終將才能枯竭歸於平庸`,d:[`神童天賦受天神詛咒無法長久維持`,`作詩寫作技能毫無實質用處不可提倡`,`家庭貧困是壓制天才發展的唯一原因`],h:`受於人者不至也，後天教育是成才關鍵。`,e:`王安石以此警惕世人：後天教育與勤學深造是決定個人才能品格之根本，切莫自恃聰穎荒廢學業。`},r),(t,n,r,i=`medium`)=>e({q:`劉基（劉伯溫）在明初創作《賣柑者言》，藉杭州賣柑者售賣「金玉其外，敗絮其中」之爛柑，深刻諷刺：`,c:`當時朝廷文武官吏高冠博帶外表道貌岸然，內裡卻尸位素餐、毫無真才實學之虛偽腐敗`,d:[`水果商販以次充好欺騙消費大眾之商業詐欺`,`南方柑橘保存技術落後容易腐爛變質`,`人民酷愛追求昂貴高檔水果之虛榮心理`],h:`金玉其外，敗絮其中，諷刺文武官僚無能。`,e:`劉基借賣柑者滔滔雄辯，直斥當朝將相坐擁高位卻無治國安邦抗敵安民之能，辛辣犀利入木三分。`},r),(t,n,r,i=`medium`)=>e({q:`朱自清在現代散文名篇《背影》中，反覆描寫父親買橘子時「穿過鐵道、爬上月台」的背影，此意象凝聚的核心情感為：`,c:`含蓄深沉、笨拙艱辛卻無比偉大崇高的父愛`,d:[`父親體弱多病缺乏運動的衰老體態`,`火車站人潮擁擠秩序混亂之社會寫實`,`父親經商失敗落魄窮困之自暴自棄`],h:`笨拙爬月台的肥胖背影。`,e:`朱自清透過細節白描，將父親在逆境中對兒子的傾心關愛定格於攀爬月台之艱難背影中，成為中國父愛之永恆圖騰。`},r),(t,n,r,i=`medium`)=>e({q:`朱自清在另一篇抒情散文《荷塘月色》中寫道：「微風過處，送來縷縷清香，彷彿遠處高樓上渺茫的歌聲似的。」此句運用的特殊藝術手法為：`,c:`通感（移覺修辭：將嗅覺之清香轉化為聽覺之歌聲）`,d:[`誇飾修辭`,`借代修辭`,`回文修辭`],h:`花香（嗅覺）轉化為歌聲（聽覺）。`,e:`「通感」打破感官界限，將嗅覺嗅到的微弱香氣以聽覺中渺茫隱約之遠處歌聲傳達，極富朦朧詩意美感。`},r),(t,n,r,i=`medium`)=>e({q:`余光中先生在著名現代詩《聽聽那冷雨》中，以淋漓盡致的文字音韻描摹雨聲，其所寄託的深層意象為：`,c:`對中華傳統故土文化難以割捨的深邃鄉愁與歷史文化沉思`,d:[`對熱帶季風氣候潮濕多雨環境的厭煩反感`,`現代都市排水系統落後容易淹水的抱怨`,`熱愛戶外淋雨漫步的浪漫生活情趣`],h:`聽聽那冷雨，滿溢故國文化情思。`,e:`余光中以古典兼現代之中文魔力，借二十四番花信冷雨融貫歷史滄桑、故園鄉愁與漢字神韻於一體。`},r),(t,n,r,i=`medium`)=>e({q:`若一首現代抒情詩描寫江南春暮久候良人的女子，因遠處清脆馬蹄聲接近而重新燃起團圓盼望，最終卻發現騎馬而過的僅是一位陌生過客。作者將此際心境稱為「美麗的錯誤」，其修辭效果為何？`,c:`藉「美麗」與「錯誤」的矛盾張力，凝鍊希望瞬間點燃卻隨即落空的淒美悵惘`,d:[`以倒裝句型誇飾騎士策馬速度極快，凸顯遊子歸心似箭的急迫感`,`借景抒情批判三月柳絮紛飛造成視線受阻，暗指旅人誤入歧途`,`透過疊字擬聲模擬城門關閉聲響，反映民間苦於兵役離亂的怒氣`],h:`「美麗」在於點燃盼望，而「錯誤」在於真相終究非歸人。`,e:`矛盾修辭（映襯）常把兩組看似衝突的評價並置，使等待從希望升騰到瞬間幻滅的戲劇張力高度濃縮。`},r),(t,n,r,i=`medium`)=>e({q:`現代抒情詩中若以「一棵佇立在行人必經路旁、歷經歲月祈願終於開滿繁花之樹」為核心意象，描繪花開期待見知心人駐足卻目睹對方無視走過、落英散地的情節，此「開花之樹」主要象徵：`,c:`對理想相遇最虔誠無悔、傾盡生命的純潔期盼與奉獻`,d:[`森林生態保護區內罕見原生種植物隨四季遞嬗的自然生命週期`,`隱逸者長年避居佛寺修行參禪後，終至看破紅塵執念的超脫心境`,`藉植物向光生長的物理習性，讚頌園藝職人培育觀賞花卉之技巧`],h:`傾盡所有盛放只為一次駐足與回眸。`,e:`將內心虔誠熱烈的守候外化為一樹慎重的繁花，即便面對無言的錯過，落瓣依舊映照出毫不保留的情感純度。`},r),(t,n,r,i=`medium`)=>e({q:`琦君散文名篇《髻》中，貫穿母親一生命運變遷的核心線索與意象物為：`,c:`母親與姨娘頭上髮髻的樣式變化（象徵家庭權力轉移與女性命運哀愁）`,d:[`父親佩戴的金錶與銀煙斗`,`家中老宅客廳懸掛的牌匾家訓`,`花園中栽種的四季蘭花`],h:`鮑魚頭、水鑽髮簪、橫愛司髻。`,e:`琦君以母親傳統純樸之螺髻與姨娘時髦華貴之愛司髻作對比，在時光流轉中看盡爭寵執怨最終化為白髮蒼蒼之寬恕悲憫。`},r),(t,n,r,i=`medium`)=>e({q:`魯迅散文詩《秋夜》開篇：「在我的後園，可以看見牆外有兩株樹，一株是棗樹，還有一株也是棗樹。」這句看似重複的特殊語法，其藝術意圖在於：`,c:`營造單調、孤獨、冷峻、沉滯的深秋氛圍，奠定頑強挺立抗爭的肅穆基調`,d:[`魯迅寫作時精神恍惚筆誤忘記已寫過棗樹`,`諷刺農夫缺乏植物學常識栽種單一樹種`,`湊足文章稿酬字數的隨性之筆`],h:`重疊強調孤絕淒清之氛圍與傲骨氣勢。`,e:`魯迅故意使用孤立冷峻之句式，在空間凝視中將兩株獨立挺拔之棗樹定格為抵抗漫漫寒夜之孤獨戰士形象。`},r),(t,n,r,i=`medium`)=>e({q:`林海音小說《城南舊事》結尾名篇《爸爸的花兒落了》，篇末「爸爸的花兒落了，我也就不再是小孩子了」象徵：`,c:`慈父病逝宣告童年無憂歲月的終結，主人公英子必須承擔起家庭責任被迫瞬間長大成熟`,d:[`庭院花卉缺乏灌溉枯萎死亡造成遺憾`,`春天過去夏季來臨自然季節之正常交替`,`父親決定搬離北京城南宅院告別舊居`],h:`落花象徵父親離世與童年結束。`,e:`雙重象徵：父親生前心愛之夾竹桃凋落象徵生命之謝幕，更象徵少女告別庇護、邁入獨立承擔成人世界之轉捩點。`},r),(t,n,r,i=`medium`)=>e({q:`楊牧散文名篇《壯游》或現代詩創作中，常以大海、太平洋黑潮與鯨魚為宏大意象，其象徵的精神氣質為：`,c:`開闊浩瀚的海洋視野、尋求生命本質探索與崇高哲思維度`,d:[`捕鯨商業捕撈所獲取之豐厚經濟產值`,`厭倦陸地文明逃避現實社會之孤獨心態`,`宣傳海洋水上運動休閒運動之樂趣`],h:`浩蕩太平洋與鯨群遨遊之壯麗哲思。`,e:`楊牧植根於臺灣花蓮東海岸，將太平洋黑潮巨浪轉化為生命追尋、知識探索與文明反思之宏偉美學空間。`},r),(t,n,r,i=`medium`)=>e({q:`簡媜在經典散文集《水問》中以細膩空靈筆觸書寫大學青春生命，被譽為：`,c:`「文字精靈」（以繁複瑰麗、清雅脫俗之散文語言著稱）`,d:[`「諷刺小說巨匠」`,`「硬漢軍旅作家」`,`「寫實報導文學領袖」`],h:`散文語言瑰麗靈動如行雲流水。`,e:`簡媜早期散文文字奇崛典雅、靈動多姿，將校園歲月、自然風物與哲理沉思熔於一爐，風格獨步當代華語文壇。`},r),(t,n,r,i=`medium`)=>e({q:`徐志摩現代詩《沙揚娜拉》（贈日本女郎）：「最是那一低頭的溫柔／像一朵水蓮花不勝涼風的嬌羞」此句之譬喻藝術在於：`,c:`以水蓮花經受不住微涼晚風之柔弱羞澀，極其傳神地捕捉東方女性低頭告別時的極致溫柔神韻`,d:[`形容日本氣候寒冷吹襲蓮花池塘`,`描寫水生植物在風中搖曳的植物學外觀`,`批判東方女性封建保守缺乏自信表現`],h:`低頭之溫柔如水蓮花嬌羞。`,e:`徐志摩以極致純淨之意象將女子辭別時欲語還休、純真羞怯之瞬間神態凝固為永恆藝術美景。`},r),(t,n,r,i=`medium`)=>e({q:`戴望舒現代象徵派名詩《雨巷》中：「撐著油紙傘，獨自／徬徨在悠長，悠長／又寂寥的雨巷／我希望逢著／一個丁香一樣地／結著愁怨的姑娘。」詩中「丁香」姑娘象徵：`,c:`詩人心中追求卻不可企及的美好理想、精神寄託或迷惘惆悵之時代情緒`,d:[`路邊叫賣丁香花束的底層貧苦小女孩`,`江南多雨氣候導致的呼吸道感染病症`,`油紙傘製造工廠之品牌商標圖案`],h:`戴望舒因此詩獲得「雨巷詩人」稱號。`,e:`戴望舒借細雨幽巷與丁香之高潔芬芳卻易凋結怨特質，象徵大革命失敗後青年知識分子迷茫苦悶卻執著追尋之幽微心境。`},r),(t,n,r,i=`medium`)=>e({q:`余光中先生悼念現代詩人徐志摩時曾寫下名句，以何種形象比喻徐志摩燦爛而短暫的生命：`,c:`「一顆高速劃破夜空、璀璨耀眼卻驟然隕落的流星」`,d:[`「千年挺立在峭壁上不動的古松」`,`「深埋在地底千百年的堅硬煤炭」`,`「常年積雪覆蓋冰冷刺骨的冰川」`],h:`短暫卻燃燒至極的浪漫流星。`,e:`徐志摩三十五歲因飛機失事罹難，文壇常以劃破天際、極致浪漫卻短暫隕落之流星象徵其一生才華。`},r),(t,n,r,i=`medium`)=>e({q:`聞一多現代詩名篇《死水》：「這是一溝絕望的死水，清風吹不起半點漪淪。不如多扔些破銅爛鐵，爽性淘些剩菜殘羹。」詩中「死水」意象象徵：`,c:`北洋軍閥統治下黑暗腐敗、停滯窒息、毫無生氣之舊中國社會現實`,d:[`城市下水道排污系統設計不良產生異味`,`化學工廠違規排放重金屬污染河川生態`,`乾旱氣候導致水庫蓄水量不足發出臭味`],h:`以極致醜惡反襯渴望破壞催生新生的憤激愛國情懷。`,e:`聞一多運用「反諷美學」，以死水之腐爛惡臭極寫舊社會體制之令人絕望，表達徹底打破腐朽渴望革命新生之強烈愛國赤忱。`},r),(t,n,r,i=`medium`)=>e({q:`白先勇著名小說集《台北人》以劉禹錫「舊時王謝堂前燕，飛入尋常百姓家」開篇，全書核心貫穿之主旨為：`,c:`大陸撤守來台兩代人的今昔對比，滄海桑田之歷史滄桑感與生命幻滅悲涼`,d:[`記錄台北市捷運工程建設發展史實`,`讚美工商發達帶來富裕繁華物質文明`,`探討現代醫學治療老年癡呆症之臨床案例`],h:`昔日大陸奢華與今日台灣流寓現實之強烈對比。`,e:`白先勇借尹雪艷、金大班等人物命運，深刻勾勒一個歷史階層由繁華盛極跌入寂滅飄零之千古輓歌。`},r),(t,n,r,i=`medium`)=>e({q:`三毛散文名篇《撒哈拉的故事》風靡無數讀者，其作品展現出最迷人的精神特質為：`,c:`追求心靈絕對自由、熱愛生命異國探險、樂觀真誠擁抱多元文化之博大情懷`,d:[`宣導沙漠極限越野賽車改裝技術指南`,`批判非洲各部落落後迷信應予現代化淘汰`,`記錄黃金礦產開採地質勘探之商業報告`],h:`在最荒涼的撒哈拉沙漠中開出最美麗的生命繁花。`,e:`三毛以真摯純粹之生命熱情在乾旱殘酷之沙漠中營造溫馨家園，展現對自由與不同族群生命尊嚴之無比熱愛。`},r),(t,n,r,i=`medium`)=>e({q:`張曉風散文《常常，我想起那座山》中，對大山充滿崇敬仰望，山在此處所蘊含的文化象徵為：`,c:`永恆堅毅、包容萬物、沉靜博大、可供現代人滌蕩心靈塵囂之精神原鄉`,d:[`蘊藏豐富稀有金屬礦脈等待商業開採`,`阻礙交通運輸必須鑿穿隧道的地理障礙`,`攀登極限運動測試個人體能極限之試煉場`],h:`大山如父，沉靜包容亙古長存。`,e:`張曉風賦予自然大山以神聖包容之精神品格，成為洗滌塵世浮躁、回歸生命沉靜之寧靜港灣。`},r),(t,n,r,i=`medium`)=>e({q:`阿盛散文名篇《火車與稻田》以火車貫穿臺灣中南部農村風景，火車與稻田兩大意象對比表現了：`,c:`現代工業文明列車高速侵入純樸傳統農業鄉村帶來的衝擊、失落與時代變遷之悵惘`,d:[`鐵路運輸大幅提升稻米外銷出口產量利潤`,`倡導全面廢除農田改建大型高科技工業園區`,`描繪火車火花容易引燃稻田麥草之火災危險`],h:`現代化機械文明 vs 傳統鄉土土地情感。`,e:`阿盛以敏銳鄉土觀察，藉鐵軌與稻浪之交錯，記錄臺灣由農業社會轉型工業社會過程中農村人文生態之深刻流變。`},r),(t,n,r,i=`medium`)=>e({q:`蕭紅在自傳體小說《呼蘭河傳》中描寫北方偏遠小鎮呼蘭河的風土人情與大泥坑，其藝術基調為：`,c:`以天真純稚的童年視角，透視傳統鄉民蒙昧冷漠、封閉麻木卻又認命生存之悲涼眾生相`,d:[`讚揚封建大家族宗法禮教規矩之嚴明整齊`,`倡導北方冰雪旅遊休閒產業之開發建設`,`宣傳古代薩滿教巫醫驅邪治病之靈驗奇蹟`],h:`小團圓媳婦之死深刻揭露愚昧禮教吃人悲劇。`,e:`蕭紅以詩意而蒼涼之筆觸，在回憶祖父花園溫暖之同時，深刻剖析底層平民在愚昧習俗下麻木吞噬同類之歷史悲劇。`},r),(t,n,r,i=`medium`)=>e({q:`老舍長篇名作《駱駝祥子》中，主角祥子歷經「買車、丟車、再買車、再賣車」的三起三落，其最終命運悲劇深刻揭示：`,c:`在殘酷黑暗、弱肉強食的舊社會體系下，底層個體純憑個人勤奮苦幹絕無可能改變自身被吞噬命運`,d:[`祥子拉洋車駕駛技巧不佳容易發生交通意外`,`祥子不善理財投資缺乏商業保險防範意識`,`老舍告誡年輕人切莫以體力勞動為謀生手段`],h:`體面的、要強的、健壯的祥子最終淪為個人主義的末路鬼。`,e:`老舍深刻揭示個人奮鬥在病態殘酷社會結構前之徹底無能為力，祥子的墮落是對不義社會之最沉痛控訴。`},r),(t,n,r,i=`medium`)=>e({q:`沈從文小說代表作《邊城》以湘西茶峒小鎮為背景，小說創造的美麗純淨世界展現了：`,c:`遠離現代商業文明污染、保留人性質樸善良、互助忠誠、優美健康之「人性之純美與悲憫」`,d:[`描寫邊防軍隊駐守國界征戰殺敵之英雄冒險`,`記錄湘西山區土匪強盜出沒劫掠財物之傳奇`,`宣傳湘西豐富水利水電資源開發工程規劃`],h:`翠翠、儺送、老船夫之間如詩如畫的純真情義。`,e:`沈從文以如詩如歌之抒情筆調構築湘西世外桃源，借純情少女翠翠之愛情悲劇，寄託對未受污染之淳樸人性與至美風情之永恆禮讚。`},r),(t,n,r,i=`medium`)=>e({q:`錢鍾書著名長篇小說《圍城》書名借用了西洋諺語，小說核心名句為：`,c:`「婚姻是一座圍城，城外的人想衝進去，城裡的人想逃出來。」`,d:[`「人生如同一場牌局，拿什麼牌由命運決定」`,`「天下沒有不散的筵席，名利皆是過眼雲煙」`,`「知識分子是國家的棟樑，社會的良心導師」`],h:`城外的人想衝進去，城裡的人想逃出來。`,e:`錢鍾書以極致機敏之辛辣幽默，借圍城比喻人生在婚姻、事業、人際等各個層面普遍面臨之盲目追求與陷入圍困之荒謬困境。`},r),(t,n,r,i=`medium`)=>e({q:`林文月散文《翡冷翠在下雨》追尋徐志摩《翡冷翠的一夜》足跡，文中所呈現的散文氣質為：`,c:`典雅端莊、融貫中西文化素養、文筆細膩典雅、富含歷史人文深思之學者散文`,d:[`慷慨激昂、憤世嫉俗之政論批判雜文風格`,`市井流行口語通俗快節奏幽默小品文`,`驚悚懸疑神怪冒險故事探案傳奇風格`],h:`學者散文家，兼具女性細膩與學者宏富學養。`,e:`林文月兼學者、翻譯家與散文家於一身，散文風格溫潤雅潔、舒緩從容，將異國風物與古典文學情懷交融生輝。`},r),(t,n,r,i=`medium`)=>e({q:`劉克襄先生的當代自然生態散文作品（如《風鳥皮諾查》、《小綠山之歌》），引領臺灣散文開拓了何種嶄新領域：`,c:`深入自然山林荒野、結合鳥類植物鳥瞰觀察、融入深切環境倫理與人文土地關懷之生態文學`,d:[`倡導獵捕稀有野生動物標本製作技巧指南`,`介紹高難度極限攀岩戶外裝備商業評測報導`,`論證城市綠化必須砍伐原始林木種植草坪景觀`],h:`鳥人劉克襄，臺灣自然生態寫作之旗手。`,e:`劉克襄結合田野踏查、自然觀察與人文歷史考證，開創臺灣具備深厚生態倫理反思與土地守護情懷之自然生態散文潮流。`},r),(t,n,r,i=`medium`)=>e({q:`廖鴻基先生的海洋文學作品（如《討海人》、《鯨生鯨世》），其文字最震撼人心之處在於：`,c:`親身作為討海漁民航向廣袤大洋，以粗獷堅毅卻深情之筆墨描繪漁人血汗搏擊與鯨豚雄偉之海洋史詩`,d:[`宣導深海遠洋大型拖網捕撈獲取暴利之商業技巧`,`介紹海邊度假勝地水上摩托車休閒娛樂安全手冊`,`論證現代大型漁業加工廠自動化冷凍生產流水線`],h:`討海人與鯨豚在大洋黑潮中的生命對話。`,e:`廖鴻基走出陸地思維，以生命直接貼近浪濤與大洋黑潮，在孤獨與危難中重新喚醒海島臺灣人沉睡已久之壯闊海洋性格。`},r),(t,n,r,i=`medium`)=>e({q:`陳列散文名篇《玉山去來》記錄其攀登臺灣最高峰玉山之震撼體驗，文中描繪玉山日出破曉瞬間之宏大景致，所傳達的哲思為：`,c:`在自然造化之崇高壯麗面前，體悟人類自身的渺小，從而昇華出謙卑敬畏與深厚安寧`,d:[`征服自然界最高峰登上頂峰展現個人無敵蠻力`,`探討玉山山頂建造高山觀光旋轉餐廳之可行性`,`批評高山氣壓過低造成登山者嚴重缺氧高山症`],h:`在自然造化的莊嚴磅礡面前，人學會了謙遜肅穆。`,e:`陳列以清澈明淨、沉穩肅穆之筆致描摹玉山之雄渾壯美，展現生命在天地自然崇高大化前之謙卑敬畏與精神淬礪。`},r),(t,n,r,i=`medium`)=>e({q:`夏曼·藍波安代表臺灣達悟族（雅美族）原住民文學，其作品《冷海情深》、《八代灣的神話》核心展現了：`,c:`達悟族人與海洋共生、遵循飛魚祭傳統、敬畏大自然海洋神靈之部落古老智慧與文化認同`,d:[`倡導蘭嶼全面現代化商業炒作開發度假飯店`,`鼓勵部落青年放棄捕魚傳統進城追求個人名利`,`記錄達悟族製造大型現代化動力鐵殼捕魚船技術`],h:`海洋即是生命、文化與尊嚴之神聖源頭。`,e:`夏曼·藍波安以達悟族母體文化視角，真誠呈現造舟、潛海射魚與飛魚祭儀之精神底蘊，捍衛海島原住民之文化主體性與生命尊嚴。`},r),(t,n,r,i=`medium`)=>e({q:`瓦歷斯·諾幹是臺灣泰雅族重要原住民作家，其創作橫跨詩歌、散文與評論，名作《番人之眼》深刻探討了：`,c:`原住民族在現代漢人強勢主流文化衝擊下的歷史創傷、身分認同掙扎與主體自覺反思`,d:[`介紹泰雅族傳統獵槍槍枝構造與火藥調配技術`,`宣傳原住民部落民俗歌舞純供遊客觀賞收費行銷`,`主張全面拋棄母語徹底融入現代都市消費社會`],h:`以原住民自身之眼審視族群歷史與文化尊嚴。`,e:`瓦歷斯·諾幹以敏銳深刻之批判筆觸，穿透殖民與漢化歷史迷霧，重塑原住民族歷史敘事與尊嚴。`},r),(t,n,r,i=`medium`)=>e({q:`在描寫南臺灣屏東沿岸平原與糖業鐵道風光的鄉土新詩裡，作者若運用短促明快的疊字節奏反覆詠嘆甘蔗甜香、充沛雨水與肥沃黑土，全詩主要營造何種氛圍？`,c:`洋溢南方沃土生命力、豐饒踏實與親切飽滿的鄉土喜悅`,d:[`藉暴雨積水阻斷南部鐵道運輸，批判早期農村水利排水建設不足`,`借蔗農烈日負重勞動與糖價波動對照，控訴工業資本剝削農民`,`透過車廂外快速後退的單調農田景象，傾訴旅人長時間乘車的倦怠`],h:`明快音律搭配飽滿物產詞彙，凸顯土地帶來豐足與親和力。`,e:`疊字重複與味覺、視覺的豐盈意象彼此呼應，將南方平原的生機與土地親情表現得明朗動人。`},r),(t,n,r,i=`medium`)=>e({q:`羅智成現代詩以其獨特之「文明幽思」、「超現實語彙」與哲思氛圍著稱，被詩壇譽為：`,c:`「觀念的冒險家、語言的魔術師」（詩風兼具哲思冥想與神秘浪漫意境）`,d:[`「口語通俗詩歌之倡導者」`,`「傳統古典格律之復古守舊派」`,`「純粹描寫軍事政論之政治詩人」`],h:`《光之書》、《傾斜之書》展現奇特深邃之詩想世界。`,e:`羅智成詩作融合深邃哲思、超現實意象與純淨語言，構建出兼備智性探求與神秘浪漫之獨特詩學王國。`},r),(t,n,r,i=`medium`)=>e({q:`「驢不勝怒，蹄之。」《黔之驢》句中的「蹄」字，其詞性活用的情況為：`,c:`名詞活用為動詞，作「用蹄子踢」解`,d:[`名詞活用為形容詞，作「蹄狀的」解`,`名詞活用為副詞，作「像蹄一樣」解`,`動詞活用為名詞，作「蹄子」解`],h:`蹄原本是名詞，後面接代詞賓語「之」。`,e:`名詞「蹄」置於代詞賓語「之」前充當述語，活用為動詞，指「用蹄踢牠」。`},r),(t,n,r,i=`medium`)=>e({q:`「親賢臣，遠小人，此先漢所以興隆也。」句中「親」與「遠」的詞類活用為：`,c:`形容詞活用為動詞，分別作「親近」與「疏遠」解`,d:[`名詞活用為動詞，作「親戚」與「遠方」解`,`形容詞活用為名詞，作「親人」與「遠客」解`,`動詞活用為副詞，作「親自」與「長遠」解`],h:`親賢臣：親近賢德之臣；遠小人：疏遠奸佞小人。`,e:`形容詞「親」與「遠」帶賓語，活用為及物動詞，作「親近、疏遠」解。`},r),(t,n,r,i=`medium`)=>e({q:`「春風又綠江南岸」句中「綠」字之語法活用情況為：`,c:`形容詞的使動用法，作「使...變綠」解`,d:[`形容詞活用為名詞，作「綠色草木」解`,`名詞活用為動詞，作「長出綠草」解`,`形容詞活用為副詞，作「翠綠地」解`],h:`春風吹拂使江南沿岸草木返綠。`,e:`「綠」本為形容詞，在此為使動用法，意即「使江南之岸邊吹綠」。`},r),(t,n,r,i=`medium`)=>e({q:`「汗顏」一詞在日常語用中表示慚愧羞愧，其中「汗」字的語法活用為：`,c:`名詞活用為動詞使動用法，作「使...流汗（感到羞愧而出汗）」解`,d:[`純名詞，流出的汗水`,`形容詞，潮濕的`,`副詞，大量地`],h:`使臉上冒汗，形容極度羞愧。`,e:`「汗」本為名詞，在此使動活用為動詞，指慚愧恐懼得滿面流汗。`},r),(t,n,r,i=`medium`)=>e({q:`「蠶食鯨吞」形容強國以不同策略侵略弱國領土，句中「蠶」與「鯨」的語法活用為：`,c:`名詞活用為狀語（副詞修飾動詞），作「像蠶一樣」、「像鯨魚一樣」解`,d:[`名詞活用為動詞，作「變成蠶」、「變成鯨」解`,`名詞活用為形容詞，作「細小的」、「龐大的」解`,`純名詞充當主語`],h:`像蠶咬桑葉般細嚼，像鯨吞海水般大嚼。`,e:`名詞置於動詞「食」與「吞」之前，充當狀語（副詞功能），比喻行動之方式與姿態。`},r),(t,n,r,i=`medium`)=>e({q:`「群臣吏民能面刺寡人之過者，受上賞。」句中的「面」字語法作用為：`,c:`名詞作狀語，作「當面」解`,d:[`名詞充當主語，作「面孔」解`,`名詞活用為動詞，作「面對」解`,`形容詞充當表語，作「表面的」解`],h:`當面指出寡人的過失過錯。`,e:`「面」為名詞用作動詞「刺」（指責）的狀語修飾詞，相當於現代漢語之「當面地」。`},r),(t,n,r,i=`medium`)=>e({q:`「范增數目項王」《鴻門宴》句中的「目」字，其詞性與字義為：`,c:`名詞活用為動詞，作「用眼睛使眼色暗示」解`,d:[`名詞，眼睛視力`,`形容詞，醒目的`,`副詞，親眼`],h:`數次用眼睛給項羽遞眼神示意行刺。`,e:`「目」本為名詞眼睛，在此帶賓語「項王」，活用為動詞，作「使眼色」解。`},r),(t,n,r,i=`medium`)=>e({q:`「先破秦入咸陽者王之。」句中「王」字的讀音與語法活用為：`,c:`讀音ㄨㄤˋ，名詞的使動用法，作「使...成為王（封他為王）」解`,d:[`讀音ㄨㄤˊ，純名詞君王`,`讀音ㄨㄤˋ，動詞統治天下`,`讀音ㄨㄤˊ，形容詞王者風範`],h:`使先入咸陽的人成為王。`,e:`「王」在此處為使動用法，音ㄨㄤˋ，意為「讓他為王、封之為王」。`},r),(t,n,r,i=`medium`)=>e({q:`「老吾老，以及人之老；幼吾幼，以及人之幼。」孟子此名句中，前一個「老」與「幼」活用為：`,c:`形容詞活用為動詞，作「敬愛長輩、撫愛幼童」解`,d:[`形容詞活用為名詞，老年人與小孩`,`名詞活用為動詞，變老與變小`,`形容詞作副詞，緩慢地與細心地`],h:`敬愛我家的老人，進而推及別人家的老人。`,e:`前一個「老」為形容詞活用為動詞（敬愛），後一個「老」為形容詞活用為名詞（老人）。`},r),(t,n,r,i=`medium`)=>e({q:`「稍稍賓客其父」《傷仲永》句中「賓客」的語法活用為：`,c:`名詞的意動用法，作「以賓客之禮對待（把...當作尊貴賓客）」解`,d:[`名詞活用為動詞，作「拜訪客人」解`,`名詞充當主語，作「客人們」解`,`名詞作狀語，作「像客人一樣」解`],h:`以賓客之禮對待仲永的父親。`,e:`「賓客」在此為名詞的意動用法，意即「以賓客禮節尊崇款待其父」。`},r),(t,n,r,i=`medium`)=>e({q:`「不恥下問」句中「恥」字的語法活用為：`,c:`形容詞的意動用法，作「以...為恥辱」解`,d:[`形容詞活用為名詞，作「羞恥心」解`,`形容詞使動用法，作「使...感到羞恥」解`,`純副詞，作「可恥地」解`],h:`不以向地位比自己低下的人請教為可恥。`,e:`「恥」在此處為形容詞意動用法，作「以...為可恥、認為可恥」解。`},r),(t,n,r,i=`medium`)=>e({q:`「孔子登東山而小魯，登泰山而小天下。」句中「小」字的詞類活用為：`,c:`形容詞的意動用法，作「認為...很小、覺得...變小」解`,d:[`形容詞使動用法，作「把...縮小」解`,`形容詞活用為名詞，作「微小之處」解`,`純形容詞修飾魯國與天下`],h:`登上泰山覺得天下都變小了。`,e:`「小」帶賓語「魯」與「天下」，充當意動詞，作「覺得...渺小」解。`},r),(t,n,r,i=`medium`)=>e({q:`「漁人甚異之」《桃花源記》句中「異」字之語法功能為：`,c:`形容詞的意動用法，作「對此感到十分驚奇詫異」解`,d:[`形容詞使動用法，作「使事情變奇異」解`,`名詞活用為動詞，作「製造奇異」解`,`形容詞修飾賓語代詞之`],h:`漁人對眼前的桃花林景致感到無比驚異。`,e:`「異」在此為意動用法，意即「以...為異、覺得這件事極其奇特怪異」。`},r),(t,n,r,i=`medium`)=>e({q:`「幕天席地」形容胸襟無拘無束超然豪邁，句中「幕」與「席」活用為：`,c:`名詞的意動用法，作「以天為帳幕，以地為草席」解`,d:[`純名詞充當主語與賓語`,`名詞活用為動詞，搭建帷幕與鋪設草席`,`名詞作狀語，像帳幕與像草席一樣`],h:`把青天當作蚊帳屋頂，把大地當作床席地毯。`,e:`「幕」與「席」皆為名詞意動活用，意即「以天為幕，以地為席」。`},r),(t,n,r,i=`medium`)=>e({q:`「衣錦還鄉」形容功成名就後榮歸故里，句中「衣」字的讀音與活用為：`,c:`讀音ㄧˋ，名詞活用為動詞，作「穿著錦繡華服」解`,d:[`讀音ㄧ，純名詞衣服衣裳`,`讀音ㄧˋ，動詞脫下衣服`,`讀音ㄧ，形容詞美麗華貴的`],h:`穿著絲綢錦服回鄉。`,e:`「衣」作名詞讀ㄧ；在此處帶賓語「錦」，活用為動詞「穿著」，音ㄧˋ。`},r),(t,n,r,i=`medium`)=>e({q:`「左右欲刃此人」句中「刃」字之詞性活用為：`,c:`名詞活用為動詞，作「用刀刃斬殺」解`,d:[`純名詞，刀刃刀鋒`,`名詞作狀語，像刀刃一樣鋒利`,`形容詞，鋒利剛烈的`],h:`左右衛士想要用刀刃殺死這個人。`,e:`「刃」本為名詞刀刃，在此處充當謂語動詞，作「用刀殺死」解。`},r),(t,n,r,i=`medium`)=>e({q:`「天下雲集而響應，贏糧而景從。」賈誼《過秦論》句中「雲、響、景」活用為：`,c:`名詞作狀語，分別作「像雲一樣匯聚」、「像回聲一樣應和」、「像影子一樣跟隨」解`,d:[`名詞活用為動詞，聚集、響起、跟隨`,`純名詞充當句子主語`,`形容詞充當表語修飾軍隊`],h:`如雲聚集、如響應聲、如影隨形。`,e:`三個名詞皆置於動詞前充當狀語，生動描寫天下百姓反抗暴秦一呼百應之壯闊聲勢。`},r),(t,n,r,i=`medium`)=>e({q:`「日進斗金」形容商業生意極其興隆獲利豐厚，句中「日」與「斗」之語法作用為：`,c:`名詞作狀語，作「每天」、「一斗一斗地（以斗為量計量）」解`,d:[`名詞充當句子主語`,`名詞活用為動詞`,`形容詞修飾進與金`],h:`每日進帳以斗為量度的黃金。`,e:`名詞「日」修飾動詞「進」表示時間頻率；名詞「斗」修飾動詞表示計量方式，皆作狀語。`},r),(t,n,r,i=`medium`)=>e({q:`「風雨交加的夜晚，他在燈下筆耕不輟。」句中「筆」字在此處之語法功能為：`,c:`名詞作狀語，作「用筆（以筆為工具進行耕耘）」解`,d:[`純名詞充當動詞賓語`,`名詞活用為及物動詞`,`形容詞修飾耕耘`],h:`用毛筆代替犁耙在紙上耕耘寫作。`,e:`「筆耕」之「筆」以工具名詞充當動詞「耕」的狀語修飾詞，指以筆墨寫作為業。`},r),(t,n,r,i=`medium`)=>e({q:`「南通州，北通州，南北通州通南北。」句中最後一個「通」字之詞性為：`,c:`動詞，作「打通、穿梭往來貫通」解`,d:[`名詞，通暢的大道`,`形容詞，通暢便捷的`,`副詞，全部統統`],h:`貫通南北兩地。`,e:`前幾個通字為地名專有名詞或形容詞，末尾之「通南北」為動賓結構，通為動詞。`},r),(t,n,r,i=`medium`)=>e({q:`「他這個人說話十分風趣，常常逗得大家哄堂大笑。」句中「風趣」之詞性為：`,c:`形容詞，描繪說話幽默風趣之性格特質`,d:[`名詞，風俗趣味`,`動詞，吹起微風`,`副詞，非常`],h:`描述說話的風格特點。`,e:`「風趣」在句中充當謂語形容詞，描繪幽默有情趣之言語舉止特性。`},r),(t,n,r,i=`medium`)=>e({q:`「這篇文章深刻地揭露了社會底層人民的苦難。」句中「深刻」與「深刻地」之詞性依序為：`,c:`形容詞 ／ 副詞（狀語修飾動詞揭露）`,d:[`名詞 ／ 動詞`,`動詞 ／ 形容詞`,`副詞 ／ 名詞`],h:`加了地字修飾後方動詞揭露，充當狀語副詞。`,e:`「深刻」本為形容詞，加上結構助詞「地」修飾動作動詞「揭露」，轉化為狀語副詞。`},r),(t,n,r,i=`medium`)=>e({q:`下列文句中的「冠」字，何者詞性為「動詞」？`,c:`李白才思敏捷，詩作名「冠」古今`,d:[`他頭戴一頂高高的禮「冠」`,`「冠」狀動脈硬化是一種心臟疾病`,`怒髮衝「冠」憑欄處`],h:`位居第一、超越群雄之動詞。`,e:`「名冠古今」之冠作述語動詞，意為「位居第一、覆蓋超越」。`},r),(t,n,r,i=`medium`)=>e({q:`下列成語中的「衣」字，何者詞性轉品充當「動詞」（穿著衣服）解？`,c:`「衣」錦還鄉（穿著華麗絲綢衣裳返鄉）`,d:[`解「衣」推食`,`「衣」冠楚楚`,`天「衣」無縫`],h:`名詞「衣」讀ㄧ，轉品作動詞「穿衣」時傳統破音讀ㄧˋ。`,e:`「衣錦還鄉」之「衣」由名詞轉品作動詞「穿著」；「解衣推食」、「衣冠楚楚」、「天衣無縫」之「衣」皆為名詞。`},r),(t,n,r,i=`medium`)=>e({q:`下列文句中的「策」字，何者充當「動詞」使用？`,c:`「策」勳十二轉，賞賜百千強《木蘭詩》`,d:[`狡兔三窟為上「策」`,`束手無「策」無可奈何`,`出謀劃「策」籌劃謀略`],h:`策勳為記錄、登記功勳之動詞。`,e:`《木蘭詩》「策勳」之「策」為動詞，指在簡策上登記記錄軍功功績。`},r),(t,n,r,i=`medium`)=>e({q:`「春風吹又生」句中的「生」字，其詞性與字義為：`,c:`動詞，生長、萌芽復甦`,d:[`名詞，生命`,`形容詞，未煮熟的`,`副詞，硬生生地`],h:`春風吹拂野草重新生長萌芽。`,e:`「生」在句中充當謂語動詞，作「萌發、生長」解。`},r),(t,n,r,i=`medium`)=>e({q:`「知己知彼，百戰不殆。」句中第一個「知」與最後一個「殆」之詞性為：`,c:`動詞（了解知道） ／ 形容詞（危險困頓）`,d:[`名詞 ／ 動詞`,`形容詞 ／ 名詞`,`副詞 ／ 動詞`],h:`了解自己了解敵軍，絕無危險失敗。`,e:`「知」為認識了解之動詞，「殆」在此作形容詞「危殆、危險困厄」解。`},r),(t,n,r,i=`medium`)=>e({q:`下列各句中的「手」字，何者活用為「狀語副詞（親手）」？`,c:`庭有枇杷樹，吾妻死之年所「手」植也`,d:[`他有一雙靈巧的雙「手」`,`「手」疾眼快反應迅捷`,`反目成仇大打出「手」`],h:`親手栽種。`,e:`「手植」之「手」置於動詞「植」（栽種）之前，修飾動作方式，作「親手地」解。`},r),(t,n,r,i=`medium`)=>e({q:`「腰纏十萬貫，騎鶴上揚州。」句中的「腰」字語法作用為：`,c:`名詞作狀語，作「在腰間（在腰部纏繞包裹）」解`,d:[`名詞充當句子主語`,`名詞活用為動詞，彎曲腰部`,`形容詞修飾十萬貫錢幣`],h:`在腰部纏繫鉅額錢財。`,e:`「腰纏」之「腰」為方位處所名詞充當動詞「纏」之狀語，指「在腰際間纏繫錢幣」。`},r),(t,n,r,i=`medium`)=>e({q:`下列關於詞類活用判斷之敘述，何者「完全正確」？`,c:`「吾妻之美我者，私我也」中「美」為意動用法（認為我美）；「私」為動詞（偏愛）`,d:[`「不恥下問」中「恥」為使動用法（使他人感到羞恥）`,`「范增數目項王」中「目」為名詞作主語`,`「驢不勝怒，蹄之」中「蹄」為形容詞修飾之`],h:`認為我貌美，偏愛於我。`,e:`鄒忌諷齊王納諫中「美我」為意動用法「以我為美」；「私我」為動詞「偏愛我」。`},r),(t,n,r,i=`medium`)=>e({q:`在閱讀圖表與統計數據時，推論結論最容易犯下的邏輯謬誤為：`,c:`將「兩事物同時發生的相關性」，錯誤等同於「兩者具有必然因果關係」`,d:[`圖表呈現的數字太精確無法信任`,`柱狀圖與折線圖不可以繪製在同一坐標系`,`百分比總和必須超過百分之一百`],h:`相關不等於因果。`,e:`統計學與邏輯學重要法則：兩變數之高度相關往往由第三變數或偶然巧合引起，不可武斷斷定因果關係。`},r),(t,n,r,i=`medium`)=>e({q:`「小明每天早晨都喝一杯熱牛奶，他這次考試拿到了第一名。因此，喝熱牛奶是考第一名的唯一關鍵秘訣。」這段推論犯了何種邏輯錯誤？`,c:`倒果為因或強加因果（以先後發生的偶然事件強加因果聯繫）`,d:[`滑坡謬誤`,`偷換概念`,`訴諸群眾`],h:`兩件事前後發生，不代表前一件引發後一件。`,e:`犯了拉丁文所謂「在此之後，便因此之故」（Post hoc ergo propter hoc）之假因果謬誤。`},r),(t,n,r,i=`medium`)=>e({q:`「如果我們今天放寬學校圖書館的借書期限，明天學生就會徹底不還書，後天學校就會倒閉，國家就會走向毀滅！」這段論證屬於典型的：`,c:`滑坡謬誤（Slippery Slope，無合理依據地串聯極端連鎖惡果）`,d:[`訴諸權威`,`稻草人謬誤`,`人身攻擊`],h:`無根據地推導極端連鎖反應。`,e:`「滑坡謬誤」指不考慮中間環節之遏止機制，誇大微小改變將無可避免引發災難性極端毀滅結果。`},r),(t,n,r,i=`medium`)=>e({q:`在辯論比賽中，故意扭曲對方的原始主張，將對方的觀點誇張化或極端化後再加以猛烈抨擊，此種詭辯手法稱為：`,c:`稻草人謬誤（Straw Man Fallacy，立虛假稻草人標靶攻擊）`,d:[`偷換概念`,`訴諸無知`,`丐詞循環論證`],h:`樹立假想靶子自己攻擊打倒。`,e:`「稻草人謬誤」刻意曲解、誇大或虛構對手觀點，使之看似荒謬可笑，從而輕易擊敗虛假論點。`},r),(t,n,r,i=`medium`)=>e({q:`「因為愛因斯坦是享譽全球的物理學大師，所以他對古典文學紅樓夢的文學鑑賞評價必然是絕對權威無可爭辯的。」此論證犯了：`,c:`不當訴諸權威（Appeal to False Authority，將專業領域權威隨意跨界擴大套用）`,d:[`人身攻擊`,`訴諸憐憫`,`偷換概念`],h:`物理學權威不等於紅學文學專家。`,e:`將某領域之卓越權威不當延伸至其毫無專門研究之其他完全不同領域，屬於不當訴諸權威謬誤。`},r),(t,n,r,i=`medium`)=>e({q:`甲：「這個交通建設方案在預算與工期上都有嚴重漏洞。」乙：「你根本就不是本市居民，你有什麼資格在這裡指指點點！」乙的回應屬於：`,c:`訴諸人身攻擊（Ad Hominem，不駁論點本身，反而攻擊發言者個人身分背景）`,d:[`滑坡謬誤`,`稻草人謬誤`,`以偏概全`],h:`對人不對事，攻擊身分而非反駁預算漏洞。`,e:`迴避討論議題實質內容，直接針對發言者之個人身分、品格、地域或動機進行貶損攻擊，為人身攻擊謬誤。`},r),(t,n,r,i=`medium`)=>e({q:`「大家都買這款球鞋，網路上每個人都在穿，所以這款球鞋必定是世界上品質最好、最耐磨的運動鞋。」此推論依據為：`,c:`訴諸群眾（Appeal to Popularity，將流行普遍性等同於客觀真理性）`,d:[`訴諸同情`,`竊取論題`,`假兩難推理`],h:`大家都做的不代表客觀品質最優。`,e:`「訴諸大眾/群眾」以多數人之接受程度或流行風潮作為論證論點真實性之唯一依據，忽視客觀事實檢驗。`},r),(t,n,r,i=`medium`)=>e({q:`非連續性文本（如藥品仿單說明書、高鐵時刻表、火災逃生路線圖）的閱讀關鍵核心策略為：`,c:`根據具體目標問題檢索關鍵資訊、交叉比對條件約束與圖示指引`,d:[`一字不漏逐字從頭朗誦記憶默背`,`只看插圖完全忽略警語小字限制`,`主觀隨意猜測無視數據標準條款`],h:`圖表文本首重檢索、整合與條件約束判定。`,e:`閱讀圖表、仿單等非連續性文本，首重帶著明確任務目標快速定位資訊、注意注意事項警語與條件邊界限制。`},r),(t,n,r,i=`medium`)=>e({q:`閱讀捷運路線圖與轉乘站標示時，規劃「耗時最短路線」與「轉乘次數最少路線」，兩者可能不同，其關鍵原因在於：`,c:`轉乘換線需要步行耗費時間，站數少的路線可能因繞行或等車而總耗時未必最短`,d:[`捷運列車每次經過轉乘站皆會減速停駛五分鐘`,`乘客必須在轉乘站重新購票安檢`,`地圖上繪製的線條顏色會影響車速快慢`],h:`站數少 vs 換乘時間代價不同。`,e:`非連續性路網圖表分析需綜合考量停靠站數、轉乘步行換線耗時及班距等多元變項。`},r),(t,n,r,i=`medium`)=>e({q:`「凡是鳥類皆有羽毛。企鵝有羽毛。所以企鵝是鳥類。」這段三段論論證的邏輯結構為：`,c:`三段論中肯有效之演繹推理（大前提、小前提與推論結論邏輯一致）`,d:[`無效推理的大前提虛假錯誤`,`倒因為果的循環論證`,`無關因果的以偏概全`],h:`大前提符合事實，小前提具備屬性，結論合乎演繹邏輯。`,e:`此為標準形式邏輯三段論（Syllogism），大前提為真，小前提符合大前提條件，演繹推論結論完全正確。`},r),(t,n,r,i=`medium`)=>e({q:`「所有烏鴉都是黑色的。我看見天鵝是白色的。所以天鵝不是烏鴉。」這段邏輯推論屬於：`,c:`充分條件之否定後件假言推理（否定後件必否定前件，邏輯嚴密有效）`,d:[`肯定後件謬誤`,`以偏概全謬誤`,`假兩難推理`],h:`若A則B，非B則非A（逆否命題等價）。`,e:`若某生物為烏鴉則必為黑色；今非黑色（為白色），故必非烏鴉，符合逆否命題等價定理。`},r),(t,n,r,i=`medium`)=>e({q:`某市發布空氣品質指標（AQI）監測圖表，當AQI指標大於150時標示為紅色警戒（對所有族群不健康），學校應採取的標準應變措施為：`,c:`調整戶外體育課改於室內通風良好處進行，並建議敏感族群配戴口罩`,d:[`全校立即停課疏散學生回家休息`,`禁止學生飲用校內飲水機飲水`,`強制要求所有學生佩戴防毒面具上課`],h:`對照空氣品質指引規範相應防護等級。`,e:`AQI達紅色警戒標準處理指引：避免戶外劇烈運動，體育活動移入室內，敏感體質加強呼吸道防護。`},r),(t,n,r,i=`medium`)=>e({q:`在一份食品營養標籤圖表中，「每份本包裝含5份，每份熱量200大卡」，若小華吃完一整包該食品，他實際攝取的總熱量為：`,c:`1000 大卡（200 × 5 = 1000）`,d:[`200 大卡`,`500 大卡`,`40 大卡`],h:`每份熱量乘以包裝總份數。`,e:`非連續性文本數據計算：總熱量＝每份熱量（200大卡）× 總份數（5份）＝ 1000大卡。`},r),(t,n,r,i=`medium`)=>e({q:`「如果不是朋友，就是敵人！」這種將多元複雜的世界硬生生簡化為非黑即白兩種極端對立選項的論調，犯了：`,c:`假兩難謬誤（False Dilemma，非黑即白謬誤）`,d:[`滑坡謬誤`,`偷換概念`,`訴諸無知`],h:`人際關係存在中間立場、中立或陌生人，非僅有朋友或敵人二元對立。`,e:`「假兩難謬誤」無視客觀存在之中間狀態或多元可能性，強迫對方在人為製造的非此即彼極端中二選一。`},r),(t,n,r,i=`medium`)=>e({q:`「因為沒有任何人能夠徹底拿出確鑿證據證明世界上沒有外星人，所以外星人必然客觀存在。」這段論述犯了：`,c:`訴諸無知謬誤（Appeal to Ignorance，將未被證偽等同於已被證實）`,d:[`訴諸權威`,`訴諸群眾`,`人身攻擊`],h:`無法證明不存在，不等於就證明了存在。`,e:`「訴諸無知」將「尚未被證明為假」直接推論為「必然為真」，顛倒舉證責任之客觀邏輯。`},r),(t,n,r,i=`medium`)=>e({q:`「這次期末考試，班上有同學作弊被抓。由此可見，這所學校的學生品德極差，完全沒有誠信可言。」此論證犯了：`,c:`以偏概全（Hasty Generalization，以極少數孤立個案妄下涵蓋全體的普遍結論）`,d:[`倒因為果`,`假兩難推理`,`稻草人謬誤`],h:`以單一同學的行為概括全校所有學生。`,e:`樣本數量嚴重不足且不具代表性，便草率對整個群體做出全稱否定結論，為典型以偏概全。`},r),(t,n,r,i=`medium`)=>e({q:`在多篇文章主題整合閱讀時，面對兩篇對同一歷史事件（如商鞅變法）觀點截然相反的評論文章，批判性閱讀的最佳策略為：`,c:`分別梳理兩文各自的論點、所引用的史實論據與立論視角，客觀比對其論證完整性與局限`,d:[`直接認定文章字數較多的一篇必然更具權威可信度`,`只相信年代較早的古代古籍記載，現代歷史學研究皆不可信`,`隨機挑選一篇全盤接受，徹底拒絕閱讀另一篇的觀點`],h:`多元視角對照檢驗論據與邏輯鏈條。`,e:`批判性閱讀要求讀者不盲從單一立場，透過交叉比對不同觀點之後設前提、論據真實性與推理嚴密性，形成獨立判斷。`},r),(t,n,r,i=`medium`)=>e({q:`「小張今天上班遲到了三十分鐘。經理斥責他工作態度散漫，小張反駁：『您昨天開會也遲到了五分鐘啊！』」小張的反駁犯了：`,c:`積非成是／你也一樣謬誤（Tu Quoque，以指責他人過錯迴避檢討自身過失）`,d:[`滑坡謬誤`,`訴諸憐憫`,`稻草人謬誤`],h:`以別人的過失來為自己的過失辯護，無法證明自己沒有遲到過失。`,e:`「你也一樣」謬誤透過指出指責者同樣犯有類似過失，企圖轉移焦點以證明自身行為之合理性，本質上迴避了問題。`},r),(t,n,r,i=`medium`)=>e({q:`閱讀長條圖圖表時，若縱坐標刻度「並未從0開始起算」，而是從98到100展開，容易帶給讀者何種視覺誤導：`,c:`人為放大極微小的數據差異，讓人誤以為差距懸殊巨大`,d:[`讓人誤以為數據全部為零`,`讓人無法看清圖表的標題名稱`,`使顏色對比度降低`],h:`截斷縱軸刻度會不成比例地放大微小差距之視覺效果。`,e:`統計圖表視覺陷阱：非零起點之截斷坐標軸會將百分之幾的微小差異視覺上誇大為數倍懸殊，誤導公眾判斷。`},r),(t,n,r,i=`medium`)=>e({q:`「吸菸有害人體健康。因為醫學研究已明確證實吸菸會顯著增加肺癌與心血管疾病風險。所以我們應當遠離香菸。」這段論述在邏輯論證上屬於：`,c:`論點明確、論據真實充分、推論邏輯嚴謹有效之論證`,d:[`缺乏論據的空洞斷言`,`以偏概全的謬誤推導`,`前後矛盾的循環論證`],h:`論點、客觀醫學論據、結論三者邏輯緊密咬合。`,e:`具備明確主張（論點）、科學實驗數據支撐（論據）與合理因果演繹推導（論證），符合健全論證標準。`},r),(t,n,r,i=`medium`)=>e({q:`閱讀捷運車站緊急逃生平面圖時，第一步最關鍵的自我定位動作為：`,c:`尋找標註「您目前所在位置」（You are here）的圖示圖標`,d:[`直接朝最近的洗手間方向奔跑`,`查看站外周邊公車轉乘路線資訊`,`尋找站長室投訴服務電話號碼`],h:`必須先確定自己所在的原點位置，方能規劃逃生路徑。`,e:`解讀空間平面圖表，必須先確認自身在坐標系中之「當前位置」原點，進而依據箭頭指引選定安全逃生門。`},r),(t,n,r,i=`medium`)=>e({q:`「某補習班宣傳海報宣稱：本班歷年培育出多位會考滿級分榜首，因此只要報名本班，保證人人都能考上第一志願。」該海報推論的漏洞在於：`,c:`倖存者偏差與以偏概全（忽略了未考上第一志願的大多數學生基數與個人資質努力差異）`,d:[`滿級分榜首名單全為偽造虛構`,`補習班收費必然高於公立學校`,`海報印刷字體排版不夠精緻美觀`],h:`只展示成功倖存案例，忽視整體分母機率。`,e:`「倖存者偏差」（Survivorship Bias）只聚焦於極少數成功案例進行宣傳，隱匿未成功者之真實數據，造成必然成功之虛假因果印象。`},r),(t,n,r,i=`medium`)=>e({q:`在一份藥品包裝標示上寫明「成人每次服用一顆，每日三次，飯後服用；兒童（12歲以下）劑量減半。孕婦忌服。」下列用藥方式何者合乎規範？`,c:`40歲成年男性於午餐後服用一顆藥丸`,d:[`懷孕三個月之婦女遵醫囑服用半顆`,`8歲兒童於早餐前空腹服用一顆藥丸`,`成年人為了加速痊癒一次服用三顆`],h:`逐項比對用藥年齡、時間、劑量與禁忌條件約束。`,e:`嚴格對照非連續性文本之年齡、劑量（成人口服一顆）、時機（飯後）與禁忌族群（孕婦忌服），只有成年男性飯後一顆完全合格。`},r),(t,n,r,i=`medium`)=>e({q:`「世界上所有的天鵝都是白天鵝。這隻動物是一隻黑天鵝。所以這隻動物不是天鵝。」這段推理之所以荒謬，其根源在於：`,c:`大前提「世界上所有的天鵝都是白天鵝」本身背離客觀事實（大前提為假）`,d:[`推理形式違反了邏輯三段論規則`,`黑天鵝並非生物學鳥類物種`,`結論與小前提產生語義矛盾`],h:`大前提在澳洲發現黑天鵝後已被徹底證偽。`,e:`演繹推理之結論要成立，既需形式有效，更需「前提為真」；前提本身不符合客觀真實，演繹結論必然崩潰。`},r),(t,n,r,i=`medium`)=>e({q:`在科學實驗研究文本中，「對照組」的最核心功能為：`,c:`排除非實驗變因干擾，作為比對基準以確定實驗變因的真實效應`,d:[`增加實驗室人員之工作量`,`提供備用器材防止損壞`,`使實驗圖表版面呈現更加對稱美觀`],h:`控制單一變量，以對照組為基準比對效應。`,e:`科學實證邏輯：唯有設立除實驗變因外其餘條件完全相同之對照組，方能驗證該獨立變項是否為引發結果之必然原因。`},r),(t,n,r,i=`medium`)=>e({q:`閱讀折線圖時，若橫坐標為月份（1月至12月），縱坐標為月均降雨量，從圖中看見7月與8月降雨量形成極高峰，而12月至2月降雨量極低接近零，最合理的推斷為：`,c:`該地降雨時空分布極不均勻，具有明顯的乾季與雨季（夏雨冬乾特徵）`,d:[`該地全年氣候嚴寒終年降雪不化`,`該地屬於全年有雨的溫帶海洋性氣候`,`該地7月與8月必然發生強烈地震災情`],h:`夏雨集中，冬季少雨乾燥。`,e:`非連續性雨量折線圖判讀：降雨高度集中於夏季（7、8月），冬季極度乾燥，展現夏雨冬乾之季風或特定氣候類型特徵。`},r),(t,n,r,i=`medium`)=>e({q:`「這本書肯定是本暢銷好書，因為它被列入了暢銷書排行榜；而它之所以能列入排行榜，正是因為它是本好書。」這段論證犯了：`,c:`循環論證（Begging the Question，以結論作為前提來證明結論本身）`,d:[`滑坡謬誤`,`不當類比`,`稻草人謬誤`],h:`兜圈子論證，前提與結論互為因果。`,e:`「循環論證」把需要被證明的結論以不同措辭偽裝為前提，看似有因有果，實則毫無任何實質證明力。`},r),(t,n,r,i=`medium`)=>e({q:`「電腦與人腦一樣都能處理複雜資訊。人腦擁有喜怒哀樂的情感意識，因此超級電腦必然也擁有愛恨情仇的情感意識。」這段論證犯了：`,c:`不當類比（False Analogy，忽視兩事物本質機制的根本差異而強行類比）`,d:[`偷換概念`,`訴諸群眾`,`人身攻擊`],h:`資訊處理能力與生物神經情感意識並無本質必然可類比性。`,e:`「不當類比」單憑兩事物在某一表象特徵（計算資訊）之相似，便武斷推論兩者在完全不同層面（情感意識）亦必然相同。`},r),(t,n,r,i=`medium`)=>e({q:`非連續性文本中「圖例」（Legend）的最主要閱讀功能在於：`,c:`說明地圖或圖表中各種符號、線條、色彩所代表的具體含義與實體對象`,d:[`裝飾圖表周邊邊框空白處`,`標註地圖繪製工程師個人簽名`,`提供地圖列印紙張尺寸規格說明`],h:`圖例是解鎖圖形符號意涵的鑰匙。`,e:`圖例是圖表文字之符號對照表，讀者唯有先理解圖例中線條顏色符號指涉之概念，方能正確解讀地圖各項地理人文資訊。`},r),(t,n,r,i=`medium`)=>e({q:`面對網路未經證實的即時新聞訊息，素養導向的批判性查證步驟應包含：`,c:`檢視訊息來源出處、交叉比對多家權威專業媒體報導、查核原始官方數據與專家說法`,d:[`看到驚悚震撼標題立即轉發至所有通訊群組分享`,`只要有附上圖片或短片就必定是真實事件無須查核`,`只相信符合自己既定政治立場喜好的任何傳聞`],h:`查核來源、多方求證、檢驗原始證據鏈條。`,e:`現代數位資訊素養核心：不輕信單一來源驚悚煽情言論，查驗原始出處、比對權威獨立查核機構報告，保持理性審慎懷疑。`},r),(t,n,r,i=`medium`)=>e({q:`傳統文化中「文房四寶」是指書寫書法所不可或缺的四種經典文具：`,c:`筆、墨、紙、硯`,d:[`琴、棋、書、畫`,`梅、蘭、竹、菊`,`印章、印泥、鎮紙、字帖`],h:`毛筆、墨條、宣紙、端硯。`,e:`中國古典文房四寶指湖筆、徽墨、宣紙、端硯（筆墨紙硯）。`},r),(t,n,r,i=`medium`)=>e({q:`「琴棋書畫」在古代被譽為君子修身養性必備的「四藝」，其中「棋」通常是指：`,c:`圍棋`,d:[`象棋`,`跳棋`,`軍棋`],h:`黑白子交替落盤之古代博弈智慧。`,e:`古代文人四藝之「棋」專指圍棋，講求局勢佈局、進退取捨與靜心定力之哲思。`},r),(t,n,r,i=`medium`)=>e({q:`中國古代將「梅、蘭、竹、菊」並稱為花中「四君子」，其中「竹」象徵的君子人格品格為：`,c:`虛心謙遜、中通外直、堅韌不拔之高尚節操`,d:[`富貴吉祥繁華似錦`,`隱逸田園避世消極`,`嬌艷美麗惹人憐愛`],h:`竹子中空象徵虛心，節節向上象徵節操堅定。`,e:`竹本固、性直、心空、節貞，象徵君子虛心好學、堅忍不拔、不畏霜雪之崇高氣節。`},r),(t,n,r,i=`medium`)=>e({q:`古代以「歲寒三友」比喻在嚴酷逆境中經得起考驗的堅貞友誼，三友是指：`,c:`松、竹、梅`,d:[`梅、蘭、菊`,`松、柏、檜`,`桃、李、杏`],h:`經霜雪嚴寒而不凋零凋落。`,e:`松柏長青耐霜雪，竹子堅挺立寒冬，梅花傲雪凌霜開，合稱為「歲寒三友」。`},r),(t,n,r,i=`medium`)=>e({q:`傳統京劇戲曲角色行當分為「生、旦、淨、丑」四大類，其中「淨」角（俗稱大花臉）的人物特質主要為：`,c:`性格剛烈、豪邁威武或忠奸分明的男性人物（藉臉譜色彩象徵性格，如紅臉忠義、白臉奸詐）`,d:[`端莊嫻靜、重唱功的中青年女性人物（如青衣）`,`溫文儒雅、不勾臉譜的青年書生角色（如小生）`,`專門負責後場絲竹伴奏與鑼鼓司鼓的樂師行當`],h:`淨行重臉譜勾畫與寬厚嗓音，表現剛強粗豪或奸險鮮明性格。`,e:`京劇四大行當：生（一般男子）、旦（女性）、淨（花臉，性格剛烈威猛或奸詐者）、丑（鼻樑抹白粉之詼諧人物）。`},r),(t,n,r,i=`medium`)=>e({q:`「冠婚喪祭」為古代傳統社會人生的四大禮節規範，總稱為：`,c:`四禮`,d:[`五倫`,`三綱`,`六藝`],h:`加冠成年禮、婚禮、喪禮、祭祀之禮。`,e:`古人人生四大重要過渡儀式合稱為「四禮」：冠禮（成年）、婚禮、喪禮、祭禮。`},r),(t,n,r,i=`medium`)=>e({q:`古代官員告老退休離職歸鄉，在古代雅稱為：`,c:`致仕（或乞骸骨）`,d:[`就任`,`拔擢`,`左遷`],h:`將官位職權交還給君王，請求退還骸骨歸葬故鄉。`,e:`古代官員年老主動請求退休稱為「致仕」（還政於君）或「乞骸骨」。`},r),(t,n,r,i=`medium`)=>e({q:`古人官場升遷或貶降用語中，「左遷」一詞在歷史語境中意指：`,c:`貶官、降職（古以右為尊，故降官稱左遷）`,d:[`升官提拔`,`調任京城擔任重臣`,`奉命出使外國特使`],h:`白居易《琵琶行》：予左遷九江郡司馬。`,e:`古代漢代以右為尊、以左為卑，故調降官職謫遷外地稱為「左遷」。`},r),(t,n,r,i=`medium`)=>e({q:`農曆八月十五日中秋節，除了賞月吃月餅外，民間還有吃柚子之習俗，其諧音吉祥寓意為：`,c:`「柚」諧音「佑」，祈求神明與祖先保佑家人平安健康團圓`,d:[`柚子形狀像火球象徵生意興旺`,`柚子果肉酸甜可以防止中暑`,`柚子外皮堅硬可以用來雕刻面具`],h:`柚與佑諧音祈福保佑。`,e:`中秋吃柚子取「柚」與神佛祖先保「佑」之諧音，象徵護佑子孫闔家安康團聚。`},r),(t,n,r,i=`medium`)=>e({q:`農曆正月十五元宵節時進食湯圓，民間習俗賦予其何種美好文化寄託：`,c:`圓滾滾的湯圓象徵「團圓美滿、和睦幸福、吉利添歲」`,d:[`糯米熱量極高可以抵禦正月嚴寒`,`湯圓煮沸浮起象徵個人官運高升`,`防止春季傳染病爆發之醫藥食療方`],h:`圓形象徵合家團圓幸福美滿。`,e:`元宵吃湯圓象徵一家團聚圓滿，寄託人們對新的一年生活和美幸福之祈願。`},r),(t,n,r,i=`medium`)=>e({q:`傳統婚禮習俗中，新人喝「交杯酒」（合巹酒），其「合巹」的原初象徵意義為：`,c:`將一個苦瓠瓜剖為兩半盛酒合飲，象徵夫妻同甘共苦、合二為一結為一體`,d:[`考驗新郎新娘的酒量極限`,`慶祝新家莊稼豐收穀物滿倉`,`驅逐新房內可能存在的邪靈妖物`],h:`巹為苦匏剖分，合飲苦甘共嘗。`,e:`「合巹」為古代婚禮核心儀式，一瓠剖兩杯象徵同甘共苦，合飲象徵二人結為一體。`},r),(t,n,r,i=`medium`)=>e({q:`傳統喪禮訃聞中，若父母俱已離世，訃聞發布時在父母名下標註的用語為：`,c:`「考妣俱歿」或「嚴慈俱逝」`,d:[`椿萱並茂`,`福壽全歸`,`蘭摧玉折`],h:`考為父，妣為母，俱歿代表雙親皆已故。`,e:`父親稱考，母親稱妣；雙親皆已過世稱為「考妣俱歿」或「先考先妣俱逝」。`},r),(t,n,r,i=`medium`)=>e({q:`古代科舉制度中，在各省省城由巡撫主考、每三年舉行一次之鄉試中榜者稱為：`,c:`舉人`,d:[`秀才`,`進士`,`狀元`],h:`院試中秀才，鄉試中舉人，會試殿試中進士。`,e:`科舉流程：童試及第為秀才（生員）；鄉試及第為「舉人」（第一名稱解元）；殿試及第為「進士」（第一名稱狀元）。`},r),(t,n,r,i=`medium`)=>e({q:`古代科舉殿試最高榮譽「三鼎甲」，依序授予的名次稱謂為：`,c:`狀元（第一名）、榜眼（第二名）、探花（第三名）`,d:[`解元、會元、狀元`,`進士、舉人、秀才`,`傳臚、庶吉士、翰林`],h:`狀元、榜眼、探花。`,e:`殿試一甲三名賜進士及第：第一名稱狀元，第二名稱榜眼，第三名稱探花，合稱三鼎甲。`},r),(t,n,r,i=`medium`)=>e({q:`若一位讀書人在科舉考試中連續奪得「解元（鄉試第一）、會元（會試第一）、狀元（殿試第一）」，此罕見極致榮耀稱為：`,c:`連中三元（三元及第）`,d:[`金榜題名`,`名列前茅`,`五子登科`],h:`鄉試解元、會試會元、殿試狀元三元冠絕。`,e:`歷史上極少數天才士子連獲鄉試、會試、殿試第一名，尊稱為「連中三元」或「三元及第」。`},r),(t,n,r,i=`medium`)=>e({q:`傳統文化禮儀中「三從四德」是古代封建社會對女性的道德枷鎖，其中「四德」是指：`,c:`婦德（品德）、婦言（言談辭令）、婦容（儀容端莊）、婦功（女紅紡織操持）`,d:[`仁、義、禮、智`,`琴、棋、書、畫`,`忠、孝、節、義`],h:`德言容功為古代婦女之四德。`,e:`《禮記》所定婦人四德：婦德（德行操守）、婦言（言語合度）、婦容（修飾整潔）、婦功（勤治家事紡織）。`},r),(t,n,r,i=`medium`)=>e({q:`中國傳統古代音樂的「五音」（五聲音階）名稱為：`,c:`宮、商、角、徵、羽`,d:[`哆、來、咪、發、索`,`金、石、絲、竹、匏`,`平、上、去、入、清`],h:`宮商角徵羽對應現代 Do, Re, Mi, Sol, La。`,e:`中國古典五聲音階為：宮、商、角（ㄐㄩㄝˊ）、徵（ㄓˇ）、羽，相當於簡譜的 1, 2, 3, 5, 6。`},r),(t,n,r,i=`medium`)=>e({q:`傳統中醫診斷疾病的「四診」基本方法為：`,c:`望（觀察神色形態）、聞（聽聲嗅氣味）、問（詢問病情病史）、切（把脈觸診）`,d:[`針（毫針刺穴）、灸（艾草溫灼）、砭（石針刮按）、導（導引按蹺）`,`君（主治要藥）、臣（輔助加強）、佐（制約毒性）、使（引經調和）`,`陰（裡證虛寒）、陽（表證實熱）、表（病位淺層）、裡（病入臟腑）`],h:`望聞問切為診斷四法；陰陽表裡寒熱虛實為八綱辨證。`,e:`中醫四診：望診（觀氣色舌苔）、聞診（聽聲息嗅氣味）、問診（詢寒熱病史）、切診（切脈觸按）；君臣佐使則為方劑配伍原則。`},r),(t,n,r,i=`medium`)=>e({q:`古代宮殿與廟宇建築門口常擺放一對「石獅子」，依傳統禮法規範，其擺放與性別特徵為：`,c:`左雄右雌，雄獅腳踏繡球而雌獅護幼獅`,d:[`左雌右雄，皆口銜寶珠`,`雙方皆為雄獅以示威猛肅穆`,`雌雄任意擺放並無任何禮法講究`],h:`男左女右，左踩繡球右撫幼獅。`,e:`傳統建築門前石獅遵循「男左女右」尊卑位次：左側為雄獅，腳踏繡球象徵社稷乾坤；右側為雌獅，腳撫幼獅象徵子孫繁衍。`},r),(t,n,r,i=`medium`)=>e({q:`傳統吉祥刺繡與年畫中常繪有「蝙蝠」圖案，古人之所以極為喜愛蝙蝠，其文化寓意在於：`,c:`「蝠」與「福」同音諧音，五隻蝙蝠象徵「五福臨門」`,d:[`蝙蝠是夜間飛行捕食害蟲之益鳥`,`蝙蝠視力極佳象徵眼光獨到前瞻`,`古代醫書記載蝙蝠肉具有延年益壽之奇效`],h:`蝠諧音福氣之福。`,e:`傳統民俗吉祥文化善用諧音雙關：「蝠」諧音「福」，繪五隻蝙蝠象徵福、壽、康寧、修好德、考終命之「五福臨門」。`},r),(t,n,r,i=`medium`)=>e({q:`年畫圖案中繪製一條活蹦亂跳的金魚游在蓮花池中，其祝賀吉祥語意為：`,c:`連年有餘（蓮諧音「連」，魚諧音「餘」）`,d:[`鯉躍龍門`,`大展鴻圖`,`百子千孫`],h:`蓮連、魚餘諧音雙關。`,e:`以「蓮」諧音「連」，「魚」諧音「餘」，連年有餘寄託家家生活富足有餘糧之美好期盼。`},r),(t,n,r,i=`medium`)=>e({q:`傳統過年圍爐時桌上必備一整條「魚」，長輩常交代不可全部吃完，必須留下魚頭魚尾，此舉象徵：`,c:`取諧音「年年有餘」，且留頭留尾寓意「有頭有尾、善始善終」`,d:[`取「鯉躍龍門」典故，專供家中應考士子獨享魚首以求功名`,`依《禮記》祭祀規制，魚首魚尾須於正月初五迎財神時化火獻祭`,`源於沿海漁村冬捕禁忌，象徵將魚苗放歸大海以祈求來春漁獲`],h:`留下魚頭魚尾象徵有頭有尾、年年有餘。`,e:`除夕年菜吃魚保留頭尾，取諧音「年年有餘」，更寓意新的一年處事有頭有尾、善始善終。`},r),(t,n,r,i=`medium`)=>e({q:`春節傳統習俗在門上倒貼「福」字或「春」字，此種倒貼之文化寓意源於諧音：`,c:`倒諧音「到」，福倒了意即「福氣到了、春天到了」`,d:[`以前門房糊塗貼反形成之錯覺流行`,`防止路過惡靈看懂吉祥字樣帶來厄運`,`倒貼代表向下扎根基礎穩固不可動搖`],h:`倒與到同音諧音。`,e:`民間巧妙利用諧音，「福倒（到）了」、「春倒（到）了」，象徵美好福祉與新春降臨家門。`},r),(t,n,r,i=`medium`)=>e({q:`端午節民間傳統習慣在門楣上懸掛「艾草」與「菖蒲」，此民俗最初的科學與醫衛用意在於：`,c:`時值農曆五月氣候濕熱蟲毒盛行，艾草與菖蒲具特殊芳香精油可驅逐蚊蠅毒蟲、除穢消毒`,d:[`展示家中有少年參加龍舟競渡奪魁`,`向上天宣告家中擁有肥沃農田產業`,`裝飾門面迎接端午神仙到訪賜福`],h:`驅避蚊蟲瘟疫傳染之原始公衛智慧。`,e:`古稱五月為毒月惡月，懸掛艾草（招百福）與菖蒲（如蒲劍斬千邪），因其含揮發性芳香油，具備天然驅蚊防蟲抑菌功效。`},r),(t,n,r,i=`medium`)=>e({q:`民間相傳中秋節起義歷史傳說，朱元璋軍師劉伯溫策劃元末起義，將起義紙條藏於何處傳遞暗號：`,c:`暗藏於「月餅」餡料之中（相約「八月十五夜殺韃子」）`,d:[`縫製在軍隊士兵衣服領口內`,`包裹在江南端午粽子竹葉中`,`塞入元宵湯圓核心豆沙中`],h:`月餅藏字條傳遞起義信號。`,e:`民間傳說劉伯溫為避開蒙古官兵搜查，命人將藏有起義日期的紙條揉入月餅之中分送各地，促成中秋起義。`},r),(t,n,r,i=`medium`)=>e({q:`民間傳統稱「冬至大如年」，冬至這一天在中國古代天文與陰陽哲學上的關鍵轉折意義為：`,c:`冬至太陽直射南回歸線，北半球夜最長晝最短，此後白晝逐日增長，象徵「一陽初生、陰極陽盛之大吉轉折」`,d:[`冬至是全年中降雪量最大的一天`,`冬至是所有植物生長最迅速的一天`,`冬至是一年中距離太陽最近的一天`],h:`冬至一陽生，陰極之至，陽氣始生。`,e:`易經十二辟卦中冬至對應地雷復卦，「冬至一陽生」，代表至陰極盛而陽氣復甦回升，具有極重要之天地節律意義。`},r),(t,n,r,i=`medium`)=>e({q:`除夕夜守歲時，長輩給予晚輩「壓歲錢」（原名「壓祟錢」），其原初民俗用意為：`,c:`「歲」諧音「祟」，以銅錢鎮壓邪祟凶煞，祈願晚輩在新的一年平安健康順利長大`,d:[`鼓勵晚輩從小培養投資股票商業意識`,`抵償晚輩全年辛勤做家事的工資報酬`,`供晚輩在新年期間購買昂貴煙火鞭炮玩樂`],h:`壓祟驅除邪惡保平安。`,e:`傳說古代有一小妖名「祟」，除夕夜常摸熟睡小童頭頂致病，父母以紅線穿銅錢置枕下鎮壓之，故名「壓祟（歲）錢」。`},r),(t,n,r,i=`medium`)=>e({q:`古人稱人際交往情誼達到生死與共、可以為對方獻出生命之崇高境界，稱為：`,c:`刎頸之交（如廉頗與藺相如）`,d:[`市道之交`,`半面之交`,`一面之緣`],h:`即使割斷脖頸頭顱也絕無悔恨。`,e:`「刎頸之交」比喻同生死、共患難、交情深厚誓死不渝的至交摯友。`},r),(t,n,r,i=`medium`)=>e({q:`古代稱「忘記年齡輩分懸殊差異而結為好友」的知心朋友為：`,c:`忘年之交（如孔融與禰衡）`,d:[`竹馬之交`,`金蘭之交`,`布衣之交`],h:`超越年齡隔閡之深厚友誼。`,e:`不以年齡長幼為界限，因志同道合、性情相契而結為摯友，稱為「忘年之交」。`},r),(t,n,r,i=`medium`)=>e({q:`古人形容幼年時期一同長大、兩小無猜的童年好友，常借騎竹杖遊戲之意象稱為：`,c:`竹馬之交（或青梅竹馬）`,d:[`烏托之交`,`莫逆之交`,`金石之交`],h:`郎騎竹馬來，遶床弄青梅。`,e:`李白《長干行》：「郎騎竹馬來，遶床弄青梅。」後世以「青梅竹馬」、「竹馬之交」形容童年摯友相親相愛。`},r)];function n(e,n,r,i,a=`medium`){return t[Math.abs(Number(r)||0)%t.length](e,n,i,a)}export{t as CHINESE_TEMPLATES,n as getCHINESE_TEMPLATESQuestion};